    // World-space point occupied by the floating controller reticle that was
    // actually presented after aim stabilization. Vehicle fire reads this
    // independently from the current occupation and accepts it only when the
    // full salted seat key and title generation still match.
    struct ReachCompletedReticleTargetPublication
    {
        std::atomic<uint32_t> sequence{0};
        std::atomic<uint32_t> generation{0};
        std::atomic<uint64_t> sampleMs{0};
        // Local shot ray only (flat parity): when this frame's engine eye `base` was published, on the
        // sight clock (Sight_NowUs) -- the camera sample stamp of the intent point built from it (shot_lag 4f).
        std::atomic<uint64_t> sampleUs{0};
        std::atomic<int32_t> unitHandle{-1};
        std::atomic<int32_t> directParent{-1};
        std::atomic<uint32_t> definitionDatum{0xFFFFFFFFu};
        std::atomic<int32_t> seatIndex{-1};
        std::atomic<float> x{0.0f};
        std::atomic<float> y{0.0f};
        std::atomic<float> z{0.0f};
        // R-V27: the ORIGIN of the same presented sight ray, in the same game
        // space as the target above. A seated personal shot must leave this
        // point, not the rendered eye: the crosshair rides the controller ray,
        // so an eye-origin shot only crosses the sight at crosshair_distance_m
        // and misses it at every other range.
        std::atomic<float> originX{0.0f};
        std::atomic<float> originY{0.0f};
        std::atomic<float> originZ{0.0f};
        // Local shot ray only: the ENGINE EYE this frame -- where Reach aims this player's shots from
        // (on foot the stock camera base, never lifted by the leash; seated, the point of the stock
        // camera's line nearest the seat). Trace-and-reaim needs the offset from here to the ray's origin.
        std::atomic<float> baseX{0.0f};
        std::atomic<float> baseY{0.0f};
        std::atomic<float> baseZ{0.0f};
        // Local shot ray only: the rendered head (centre eye) of the same frame, which follows the
        // headset. The intent ray starts here; the DEV shot check compares the native origin with it.
        std::atomic<float> headX{0.0f};
        std::atomic<float> headY{0.0f};
        std::atomic<float> headZ{0.0f};
        // F06/F07 producer receipt of the ray that was actually published, so a
        // weapon-sensitive consumer that reads this point later re-qualifies
        // it against its own invocation instead of trusting an old point.
        std::atomic<uint64_t> supportEpoch{0};
        std::atomic<uint8_t> supportTrusted{0};
        std::atomic<uint64_t> raySerial{0};
    };
    ReachCompletedReticleTargetPublication g_reachCompletedReticleTarget;
    // The local player's shot ray for trace-and-reaim: on foot, or seated (directParent != -1).
    ReachCompletedReticleTargetPublication g_reachLocalShotRay;
    std::atomic<uint32_t> g_reachHandShotMoves{0};
    std::atomic<uint32_t> g_reachHandShotMisses{0};

    void ReachClearAimFeedback()
    {
        auto& published = g_reachAimFeedback;
        published.sequence.fetch_add(1, std::memory_order_acq_rel);
        published.generation.store(0, std::memory_order_relaxed);
        published.sampleMs.store(0, std::memory_order_relaxed);
        published.source.store(
            static_cast<uint8_t>(ReachAimFeedbackSource::OnFootCompact),
            std::memory_order_relaxed);
        published.x.store(1.0f, std::memory_order_relaxed);
        published.y.store(0.0f, std::memory_order_relaxed);
        published.z.store(0.0f, std::memory_order_relaxed);
        published.sequence.fetch_add(1, std::memory_order_release);
    }

    void ReachClearCompletedFrameFeedback()
    {
        g_reachLocalShotRay.generation.store(0,std::memory_order_release);
        g_reachLocalShotRay.supportEpoch.store(0,std::memory_order_relaxed);
        g_reachLocalShotRay.supportTrusted.store(0,std::memory_order_relaxed);
        g_reachLocalShotRay.raySerial.store(0,std::memory_order_relaxed);
        {
            auto& published = g_reachCompletedReticleAim;
            published.sequence.fetch_add(1, std::memory_order_acq_rel);
            published.generation.store(0, std::memory_order_relaxed);
            published.preparedSerial.store(0, std::memory_order_relaxed);
            published.source.store(
                static_cast<uint8_t>(ReachAimFeedbackSource::OnFootCompact),
                std::memory_order_relaxed);
            published.unitHandle.store(-1, std::memory_order_relaxed);
            published.directParent.store(-1, std::memory_order_relaxed);
            published.definitionDatum.store(
                0xFFFFFFFFu, std::memory_order_relaxed);
            published.seatIndex.store(-1, std::memory_order_relaxed);
            published.identity.store(
                static_cast<uint8_t>(ReachVehicleId::Unknown),
                std::memory_order_relaxed);
            published.x.store(0.0f, std::memory_order_relaxed);
            published.y.store(0.0f, std::memory_order_relaxed);
            published.z.store(-1.0f, std::memory_order_relaxed);
            published.sequence.fetch_add(1, std::memory_order_release);
        }
        {
            auto& published = g_reachCompletedEye;
            published.sequence.fetch_add(1, std::memory_order_acq_rel);
            published.generation.store(0, std::memory_order_relaxed);
            published.preparedSerial.store(0, std::memory_order_relaxed);
            published.sampleMs.store(0, std::memory_order_relaxed);
            published.unitHandle.store(-1, std::memory_order_relaxed);
            published.directParent.store(-1, std::memory_order_relaxed);
            published.definitionDatum.store(
                0xFFFFFFFFu, std::memory_order_relaxed);
            published.seatIndex.store(-1, std::memory_order_relaxed);
            published.x.store(0.0f, std::memory_order_relaxed);
            published.y.store(0.0f, std::memory_order_relaxed);
            published.z.store(0.0f, std::memory_order_relaxed);
            published.sequence.fetch_add(1, std::memory_order_release);
        }
        {
            auto& published = g_reachCompletedReticleTarget;
            published.sequence.fetch_add(1, std::memory_order_acq_rel);
            published.generation.store(0, std::memory_order_relaxed);
            published.sampleMs.store(0, std::memory_order_relaxed);
            published.unitHandle.store(-1, std::memory_order_relaxed);
            published.directParent.store(-1, std::memory_order_relaxed);
            published.definitionDatum.store(
                0xFFFFFFFFu, std::memory_order_relaxed);
            published.seatIndex.store(-1, std::memory_order_relaxed);
            published.x.store(0.0f, std::memory_order_relaxed);
            published.y.store(0.0f, std::memory_order_relaxed);
            published.z.store(0.0f, std::memory_order_relaxed);
            published.supportEpoch.store(0, std::memory_order_relaxed);
            published.supportTrusted.store(0, std::memory_order_relaxed);
            published.raySerial.store(0, std::memory_order_relaxed);
            published.sequence.fetch_add(1, std::memory_order_release);
        }
    }

    void ReachPublishShotOccupation(
        uint32_t generation, const ReachVehicleFrame* frame,
        bool chaseCamera = false)
    {
        const bool active = generation && frame && frame->active;
        auto& published = g_reachShotOccupation;
        published.sequence.fetch_add(1, std::memory_order_acq_rel);
        published.generation.store(
            active ? generation : 0, std::memory_order_relaxed);
        published.sampleMs.store(
            active ? GetTickCount64() : 0, std::memory_order_relaxed);
        published.active.store(active ? 1u : 0u, std::memory_order_relaxed);
        published.allowsWeapons.store(
            active &&
                (frame->seatFlags & kReachSeatAllowsWeaponsBit) != 0
                ? 1u
                : 0u,
            std::memory_order_relaxed);
        published.chaseCamera.store(
            active && chaseCamera ? 1u : 0u, std::memory_order_relaxed);
        published.unitHandle.store(
            active ? frame->unitHandle : -1, std::memory_order_relaxed);
        published.directParent.store(
            active ? frame->directParent : -1, std::memory_order_relaxed);
        published.definitionDatum.store(
            active ? frame->definitionDatum : 0xFFFFFFFFu,
            std::memory_order_relaxed);
        published.seatIndex.store(
            active ? frame->seatIndex : -1, std::memory_order_relaxed);
        published.sequence.fetch_add(1, std::memory_order_release);
    }

    void ReachPublishAimFeedback(
        uint32_t generation, ReachAimFeedbackSource source,
        const float forward[3])
    {
        if (!generation || !forward || !std::isfinite(forward[0]) ||
            !std::isfinite(forward[1]) || !std::isfinite(forward[2]))
        {
            return;
        }
        auto& published = g_reachAimFeedback;
        published.sequence.fetch_add(1, std::memory_order_acq_rel);
        published.generation.store(generation, std::memory_order_relaxed);
        published.sampleMs.store(GetTickCount64(), std::memory_order_relaxed);
        published.source.store(
            static_cast<uint8_t>(source), std::memory_order_relaxed);
        published.x.store(forward[0], std::memory_order_relaxed);
        published.y.store(forward[1], std::memory_order_relaxed);
        published.z.store(forward[2], std::memory_order_relaxed);
        published.sequence.fetch_add(1, std::memory_order_release);
        if (source == ReachAimFeedbackSource::SeatedUnitAim)
            g_reachUnitAimSamples.fetch_add(1, std::memory_order_relaxed);
        else if (source == ReachAimFeedbackSource::SeatedCompactFallback)
            g_reachUnitAimFallbacks.fetch_add(1, std::memory_order_relaxed);
    }

    bool ReachReadAimFeedback(float out[3])
    {
        if (!out)
            return false;
        const uint32_t generation =
            g_reachCamera.generation.load(std::memory_order_acquire);
        const uint64_t nowMs = GetTickCount64();
        auto& published = g_reachAimFeedback;
        for (int attempt = 0; attempt < 2; ++attempt)
        {
            const uint32_t before =
                published.sequence.load(std::memory_order_acquire);
            if (!before || (before & 1u))
                continue;
            const uint32_t sampleGeneration =
                published.generation.load(std::memory_order_relaxed);
            const uint64_t sampleMs =
                published.sampleMs.load(std::memory_order_relaxed);
            const auto source = static_cast<ReachAimFeedbackSource>(
                published.source.load(std::memory_order_relaxed));
            const float sample[3] = {
                published.x.load(std::memory_order_relaxed),
                published.y.load(std::memory_order_relaxed),
                published.z.load(std::memory_order_relaxed)};
            if (published.sequence.load(std::memory_order_acquire) != before)
                continue;
            if (sampleGeneration != generation || !sampleMs ||
                nowMs < sampleMs || nowMs - sampleMs > 500 ||
                source == ReachAimFeedbackSource::OnFootCompact ||
                !std::isfinite(sample[0]) || !std::isfinite(sample[1]) ||
                !std::isfinite(sample[2]))
            {
                return false;
            }
            memcpy(out, sample, sizeof(sample));
            return true;
        }
        return false;
    }

    bool ReachReadCompletedReticleAim(
        uint64_t expectedPreparedSerial, float outCameraLocal[3])
    {
        if (!expectedPreparedSerial || !outCameraLocal)
            return false;
        const uint32_t currentGeneration =
            g_reachCamera.generation.load(std::memory_order_acquire);
        auto& published = g_reachCompletedReticleAim;
        for (int attempt = 0; attempt < 2; ++attempt)
        {
            const uint32_t before =
                published.sequence.load(std::memory_order_acquire);
            if (!before || (before & 1u))
                continue;
            ReachReticleAimSample sample{};
            sample.generation =
                published.generation.load(std::memory_order_relaxed);
            sample.preparedSerial =
                published.preparedSerial.load(std::memory_order_relaxed);
            sample.source = static_cast<ReachAimFeedbackSource>(
                published.source.load(std::memory_order_relaxed));
            sample.occupation = {
                sample.generation,
                published.unitHandle.load(std::memory_order_relaxed),
                published.directParent.load(std::memory_order_relaxed),
                published.definitionDatum.load(std::memory_order_relaxed),
                published.seatIndex.load(std::memory_order_relaxed)};
            sample.cameraLocalDirection[0] =
                published.x.load(std::memory_order_relaxed);
            sample.cameraLocalDirection[1] =
                published.y.load(std::memory_order_relaxed);
            sample.cameraLocalDirection[2] =
                published.z.load(std::memory_order_relaxed);
            if (published.sequence.load(std::memory_order_acquire) != before)
                continue;
            if (!ReachReticleAimSampleAdmitted(
                    sample, currentGeneration, expectedPreparedSerial))
            {
                return false;
            }
            return ReachNormalizeUnitAimingVector(
                sample.cameraLocalDirection, outCameraLocal);
        }
        return false;
    }

    // The 2026-08-04 session produced 21 seated periods that stayed stock with
    // no logged reason: the identity-miss line dedups once per generation and
    // names nothing. These fixed slots let the hot frame builder publish the
    // exact tuple/type/seat the engine holds for each distinct unmatched or
    // out-of-census seat, and the 50 ms worker logs each one exactly once.
    // Allocation-free and lock-free by construction; slots never recycle
    // within a generation (8 distinct offenders per session is generous).
    struct ReachVehicleCensusMissSample
    {
        // 0 empty, 1 claimed (being filled), 2 ready to log, 3 logged.
        std::atomic<uint32_t> state{0};
        ReachVehicleFingerprint fingerprint{};
        int32_t observedType = 0;
        int32_t seatIndex = -1;
        int32_t seatCount = -1;
        uint8_t knownIdentity = 0;
    };
    std::array<ReachVehicleCensusMissSample, 8> g_reachVehicleCensusMisses;

    void ReachPublishVehicleCensusMiss(
        const ReachVehicleFingerprint& fingerprint, int32_t observedType,
        int32_t seatIndex, int32_t seatCount, uint8_t knownIdentity)
    {
        for (auto& slot : g_reachVehicleCensusMisses)
        {
            if (slot.state.load(std::memory_order_acquire) < 2)
                continue;
            if (ReachVehicleFingerprintEqual(slot.fingerprint, fingerprint) &&
                slot.seatIndex == seatIndex &&
                slot.knownIdentity == knownIdentity)
            {
                return;
            }
        }
        for (auto& slot : g_reachVehicleCensusMisses)
        {
            uint32_t expected = 0;
            if (!slot.state.compare_exchange_strong(
                    expected, 1, std::memory_order_acq_rel))
            {
                continue;
            }
            slot.fingerprint = fingerprint;
            slot.observedType = observedType;
            slot.seatIndex = seatIndex;
            slot.seatCount = seatCount;
            slot.knownIdentity = knownIdentity;
            slot.state.store(2, std::memory_order_release);
            return;
        }
    }

    // The Reach shot line, the exact O-E6c design with Reach-native evidence
    // (docs/REACH-VEHICLE-EVIDENCE.md R-V10). HREK proves a seated occupant's
    // shots leave (unit camera-position evaluator result, unit aiming vector):
    // the firing path copies the evaluator's answer into a PRIVATE stack
    // buffer and projects the muzzle onto that ray, so the shot origin can
    // move without feeding back into the engine camera. The evaluator has 34
    // retail call sites and only TWO are firing; substitution happens only
    // when the return address matches one of those two, the unit is the
    // seated local player's own, the seat's tag allows a personal weapon
    // (drivers and mounted gunners fire from a vehicle barrel), no authored
    // cinematic is running, and a fresh finite rendered eye exists.
    using ReachUnitCameraPositionFn = uint64_t(__fastcall*)(int32_t, float*);
    ReachUnitCameraPositionFn g_origReachUnitCameraPosition = nullptr;
    void* g_reachUnitCameraPositionTarget = nullptr;
    // Atomics let teardown revoke the optional substitution before disabling
    // its hook without racing a firing thread already inside the detour.
    std::atomic<uintptr_t> g_reachFiringOriginReturnA{0};
    std::atomic<uintptr_t> g_reachFiringOriginReturnB{0};
    std::atomic<uint32_t> g_reachCinematicLocked{0};
    std::atomic<uint32_t> g_reachFiringOriginMoves{0};
    std::atomic<uint32_t> g_reachFiringOriginSkips{0};
    // Why a personal seated shot kept its stock origin. Exactly one of these
    // advances per skipped firing call; the worker prints them together.
    std::atomic<uint32_t> g_reachFiringOriginSkipTorn{0};
    std::atomic<uint32_t> g_reachFiringOriginSkipNotSeated{0};
    std::atomic<uint32_t> g_reachFiringOriginSkipNoWeaponSeat{0};
    std::atomic<uint32_t> g_reachFiringOriginSkipKeyMismatch{0};
    std::atomic<uint32_t> g_reachFiringOriginSkipStaleEye{0};
    std::atomic<uint32_t> g_reachFiringOriginSkipNoSightRay{0};
    // Seated shots whose origin was left stock because trace-and-reaim was live (not a failure).
    std::atomic<uint32_t> g_reachFiringOriginConverged{0};
    // Seated shots whose origin was left stock because a chase camera was chosen for the seat (not a failure).
    std::atomic<uint32_t> g_reachFiringOriginChaseKept{0};
    // The occupied seat's own flags word, published by the engine
    // thread that read it so the worker can report it honestly.
    std::atomic<uint32_t> g_reachVehicleSeatFlagsPublished{0};
    // The occupied seat's ORIGINAL flags lack bit 4 (third-person camera): stock Reach rebases this seat's aim by
    // the vehicle's up frame, so the rebase skip (seat_aim_world_frame.inl, slot 2) stands down while it is
    // occupied and the seat drive writes the inverse (case b). "Original" is R-V27's lease's saved word when the
    // lease owns this seat's mutation, the live word otherwise. 0 = not seen; otherwise the Halo 3 key layout
    // (0x80000000 | definition index << 8 | seat). Camera/engine thread writes, WaitThread reads.
    std::atomic<uint32_t> g_reachSeatNativeNoThirdPerson{0};
    // How many times Reach's own first-person interpolation/palette
    // transaction ran while a vehicle seat was occupied. This is the
    // one number that separates "the engine never built the occupant's
    // arms and weapon" from "it built them and we placed or collapsed
    // them wrong", and no previous report could tell those apart.
    std::atomic<uint32_t> g_reachSeatedFpPaletteCalls{0};

    struct ReachShotOccupationSnapshot
    {
        uint32_t sequence = 0;
        uint32_t generation = 0;
        uint64_t sampleMs = 0;
        bool active = false;
        bool allowsWeapons = false;
        bool chaseCamera = false;
        ReachSeatLeaseKey key{};
    };

    struct ReachCompletedEyeSnapshot
    {
        uint32_t generation = 0;
        uint64_t preparedSerial = 0;
        uint64_t sampleMs = 0;
        ReachSeatLeaseKey key{};
        float eye[3]{};
    };

    struct ReachCompletedReticleTargetSnapshot
    {
        uint32_t sequence = 0;
        uint32_t generation = 0;
        uint64_t sampleMs = 0;
        uint64_t sampleUs = 0;   // local shot ray only: the sight-clock stamp of `base` (0: unknown)
        ReachSeatLeaseKey key{};
        float target[3]{};
        float origin[3]{};
        float base[3]{};
        float head[3]{};
        // F06/F07 producer receipt frozen with this point.
        uint64_t supportEpoch = 0;
        bool supportTrusted = false;
        uint64_t raySerial = 0;
    };

    bool ReachReadShotOccupation(ReachShotOccupationSnapshot& out)
    {
        auto& published = g_reachShotOccupation;
        for (int attempt = 0; attempt < 2; ++attempt)
        {
            const uint32_t before =
                published.sequence.load(std::memory_order_acquire);
            if (!before || (before & 1u))
                continue;
            ReachShotOccupationSnapshot sample{};
            sample.sequence = before;
            sample.generation =
                published.generation.load(std::memory_order_relaxed);
            sample.sampleMs =
                published.sampleMs.load(std::memory_order_relaxed);
            sample.active =
                published.active.load(std::memory_order_relaxed) != 0;
            sample.allowsWeapons =
                published.allowsWeapons.load(std::memory_order_relaxed) != 0;
            sample.chaseCamera =
                published.chaseCamera.load(std::memory_order_relaxed) != 0;
            sample.key = {
                sample.generation,
                published.unitHandle.load(std::memory_order_relaxed),
                published.directParent.load(std::memory_order_relaxed),
                published.definitionDatum.load(std::memory_order_relaxed),
                published.seatIndex.load(std::memory_order_relaxed)};
            if (published.sequence.load(std::memory_order_acquire) != before)
                continue;
            out = sample;
            return true;
        }
        return false;
    }

    bool ReachReadCompletedEye(ReachCompletedEyeSnapshot& out)
    {
        auto& published = g_reachCompletedEye;
        for (int attempt = 0; attempt < 2; ++attempt)
        {
            const uint32_t before =
                published.sequence.load(std::memory_order_acquire);
            if (!before || (before & 1u))
                continue;
            ReachCompletedEyeSnapshot sample{};
            sample.generation =
                published.generation.load(std::memory_order_relaxed);
            sample.preparedSerial =
                published.preparedSerial.load(std::memory_order_relaxed);
            sample.sampleMs =
                published.sampleMs.load(std::memory_order_relaxed);
            sample.key = {
                sample.generation,
                published.unitHandle.load(std::memory_order_relaxed),
                published.directParent.load(std::memory_order_relaxed),
                published.definitionDatum.load(std::memory_order_relaxed),
                published.seatIndex.load(std::memory_order_relaxed)};
            sample.eye[0] = published.x.load(std::memory_order_relaxed);
            sample.eye[1] = published.y.load(std::memory_order_relaxed);
            sample.eye[2] = published.z.load(std::memory_order_relaxed);
            if (published.sequence.load(std::memory_order_acquire) != before)
                continue;
            out = sample;
            return true;
        }
        return false;
    }

    // F06 consumer qualification, defined with the presented-ray producer below.
    // Declared here because the weapon-sensitive consumers that read a
    // previously published presented point run earlier in the file.
    bool ReachPresentedRayConsumable(GameTitle title, uint32_t generation,
        uint64_t consumerSerial, uint64_t raySupportEpoch,
        bool raySupportTrusted, uint64_t raySerial);
    // A SEATED ray (ReachBuildPresentedReticleWorldTarget `seated`): no F06 receipt exists in a seat (no
    // first-person interpolation runs there) and a seat holds no support grip, so it is consumable when it
    // belongs to this frame -- the serial staleness bound only.
    bool ReachSeatedRayConsumable(uint64_t raySerial, uint64_t consumerSerial)
    {
        return !VR_SupportGripWiredForTitle(GameTitle::HaloReach) ||
            support_grip::PresentedRaySerialCompatible(raySerial, consumerSerial);
    }

    bool ReachReadCompletedReticleTarget(
        ReachCompletedReticleTargetSnapshot& out,
        const ReachCompletedReticleTargetPublication& published=g_reachCompletedReticleTarget)
    {
        for (int attempt = 0; attempt < 2; ++attempt)
        {
            const uint32_t before =
                published.sequence.load(std::memory_order_acquire);
            if (!before || (before & 1u))
                continue;
            ReachCompletedReticleTargetSnapshot sample{};
            sample.sequence = before;
            sample.generation =
                published.generation.load(std::memory_order_relaxed);
            sample.sampleMs =
                published.sampleMs.load(std::memory_order_relaxed);
            sample.sampleUs =
                published.sampleUs.load(std::memory_order_relaxed);
            sample.key = {
                sample.generation,
                published.unitHandle.load(std::memory_order_relaxed),
                published.directParent.load(std::memory_order_relaxed),
                published.definitionDatum.load(std::memory_order_relaxed),
                published.seatIndex.load(std::memory_order_relaxed)};
            sample.target[0] =
                published.x.load(std::memory_order_relaxed);
            sample.target[1] =
                published.y.load(std::memory_order_relaxed);
            sample.target[2] =
                published.z.load(std::memory_order_relaxed);
            sample.origin[0] =
                published.originX.load(std::memory_order_relaxed);
            sample.origin[1] =
                published.originY.load(std::memory_order_relaxed);
            sample.origin[2] =
                published.originZ.load(std::memory_order_relaxed);
            sample.base[0] = published.baseX.load(std::memory_order_relaxed);
            sample.base[1] = published.baseY.load(std::memory_order_relaxed);
            sample.base[2] = published.baseZ.load(std::memory_order_relaxed);
            sample.head[0] = published.headX.load(std::memory_order_relaxed);
            sample.head[1] = published.headY.load(std::memory_order_relaxed);
            sample.head[2] = published.headZ.load(std::memory_order_relaxed);
            sample.supportEpoch =
                published.supportEpoch.load(std::memory_order_relaxed);
            sample.supportTrusted =
                published.supportTrusted.load(std::memory_order_relaxed) != 0;
            sample.raySerial =
                published.raySerial.load(std::memory_order_relaxed);
            if (published.sequence.load(std::memory_order_acquire) != before)
                continue;
            out = sample;
            return true;
        }
        return false;
    }

    // Runs on the engine's own weapon path. Seqlock reads plus three float
    // stores: no locks, allocation or logging. The original always runs first
    // and its register result is preserved. The full-key/current-generation
    // match prevents a prior seat or partial render from donating its eye.
    uint64_t ReachUnitCameraPositionBody(
        int32_t unitIndex, float* out, uintptr_t caller)
    {
        ReachUnitCameraPositionFn original = g_origReachUnitCameraPosition;
        const uint64_t stockResult =
            original ? original(unitIndex, out) : 0;
#if HALOMCCVR_DEV_DIAGNOSTICS
        ReachSimProbeFrame(unitIndex, caller);   // dev: one of the mod's own calls between ticks (dev_sim_probe 4)
#endif
        if (!out)
            return stockResult;
        const uintptr_t returnA = g_reachFiringOriginReturnA.load(
            std::memory_order_relaxed);
        const uintptr_t returnB = g_reachFiringOriginReturnB.load(
            std::memory_order_relaxed);
        if (caller != returnA && caller != returnB)
            return stockResult;           // not the shot line; leave it alone
        if (!Sight_FireTimeChangesAllowed())
            return stockResult;           // co-op safe shots: the origin stays the game's own
        if (g_reachCinematicLocked.load(std::memory_order_relaxed))
            return stockResult;           // authored camera owns the view
        ReachShotOccupationSnapshot occupation{};
        ReachCompletedEyeSnapshot renderedEye{};
        const uint64_t nowMs = GetTickCount64();
        // Trace-and-reaim live: the aim already converges this shot on the traced point from Reach's
        // own origin (on foot and in a seat alike). Moving the origin onto the sight ray as well would
        // correct it twice. The substitution below is the worst-case fallback.
        if (ReachConvergedShotLive(nowMs))
        {
            if (ReachReadShotOccupation(occupation) && occupation.active)
                g_reachFiringOriginConverged.fetch_add(1, std::memory_order_relaxed);
            return stockResult;
        }
        const uint32_t generation =
            g_reachCamera.generation.load(std::memory_order_acquire);
        const bool coherent =
            ReachReadShotOccupation(occupation) &&
            ReachReadCompletedEye(renderedEye) &&
            g_reachShotOccupation.sequence.load(
                std::memory_order_acquire) == occupation.sequence;
        ReachShotOriginSample sample{};
        sample.currentGeneration = generation;
        sample.nowMs = nowMs;
        sample.occupationSampleMs = occupation.sampleMs;
        sample.renderedEyeSampleMs = renderedEye.sampleMs;
        sample.renderedEyePreparedSerial = renderedEye.preparedSerial;
        sample.active = occupation.active;
        sample.allowsWeapons = occupation.allowsWeapons;
        sample.firingUnitIndex = unitIndex;
        sample.occupation = occupation.key;
        sample.renderedEye = renderedEye.key;
        memcpy(
            sample.renderedEyePosition, renderedEye.eye,
            sizeof(sample.renderedEyePosition));
        // The evaluator receives a full unit datum. Its firing argument is
        // compared by object index, while both publications still carry and
        // compare the complete salted unit, parent, definition and seat key.
        if (!coherent || !ReachShotOriginSampleAdmitted(sample))
        {
            g_reachFiringOriginSkips.fetch_add(1, std::memory_order_relaxed);
            // R-V25: the 12a7ee4 session skipped every personal shot and moved
            // none, and the single "SKIPPED" line could not say whether the
            // seat refused weapons, the keys disagreed or the eye was stale.
            // One lock-free increment on an already-rare firing call names it.
            std::atomic<uint32_t>* reason = &g_reachFiringOriginSkipTorn;
            if (!coherent)
                reason = &g_reachFiringOriginSkipTorn;
            else if (!sample.active)
                reason = &g_reachFiringOriginSkipNotSeated;
            else if (!sample.allowsWeapons)
                reason = &g_reachFiringOriginSkipNoWeaponSeat;
            else if (!ReachSeatLeaseKeyEqual(
                         sample.occupation, sample.renderedEye))
                reason = &g_reachFiringOriginSkipKeyMismatch;
            else
                reason = &g_reachFiringOriginSkipStaleEye;
            reason->fetch_add(1, std::memory_order_relaxed);
            return stockResult;
        }
        // A chase camera of the vehicle camera file is chosen for this seat: the sight's ray starts at the camera,
        // metres behind or above the occupant (and maybe past cover), so the shot leaves from the game's own point.
        if (occupation.chaseCamera)
        {
            g_reachFiringOriginChaseKept.fetch_add(1, std::memory_order_relaxed);
            return stockResult;
        }
        // R-V27: leave from where the SIGHT starts, not from the eye.
        //
        // The 7235d8d headset run proved this substitution finally fires for a
        // passenger ("seated personal-weapon shots are leaving the rendered
        // eye", 01:52:57) and the user still reported that shots do not follow
        // the crosshair. The rendered eye was the wrong point. In a Reach
        // vehicle the sight we present is the floating CONTROLLER reticle, and
        // ReachBuildPresentedReticleWorldTarget places it at
        // crosshair_distance_m along the controller ray. A shot leaving the eye
        // toward a point on the controller ray is a different line that merely
        // CROSSES the sight at that one distance; at every other range it is
        // off by the whole eye-to-hand offset - tens of centimetres, several
        // degrees at close range. Taking the ray's own origin makes the shot
        // line and the sight line the same line at every range, which is the
        // property the ODST work recorded as the whole point of moving an
        // origin at all.
        //
        // No silent fallback: without a fresh exact-key sight ray this shot
        // stays completely stock rather than leaving from a mismatched point.
        ReachCompletedReticleTargetSnapshot sight{};
        const bool sightRead = ReachReadCompletedReticleTarget(sight) &&
            g_reachCompletedReticleTarget.sequence.load(
                std::memory_order_acquire) == sight.sequence;
        const bool sightUsable = sightRead && sight.sampleMs != 0 &&
            sight.generation == generation &&
            ReachSeatLeaseKeyValid(sight.key) &&
            ReachSeatLeaseKeyEqual(sight.key, occupation.key) &&
            nowMs >= sight.sampleMs &&
            nowMs - sight.sampleMs <= kReachShotOriginFreshMs &&
            std::isfinite(sight.origin[0]) && std::isfinite(sight.origin[1]) &&
            std::isfinite(sight.origin[2]) &&
            // F06: the point is consumed later than it was produced; re-prove
            // the ray's producer receipt against this consuming invocation
            // (same owner, same epoch, serial staleness bound). A refused ray
            // leaves this shot completely stock - never a stale-owner origin.
            //
            // F3: the consuming frame's serial is the completed rendered eye's
            // prepared serial - the same frame whose occupation/freshness proof
            // (ReachShotOriginSampleAdmitted, above) admits this shot. The shot
            // origin itself is the presented sight ray (R-V27), not that eye
            // position. Passing the ray's own serial here would make the
            // staleness bound tautological. The other two re-qualification
            // sites (the on-foot hand shot and the vehicle redirect) have no
            // consuming prepared serial in scope inside the weapon transaction,
            // so they deliberately keep the ray serial and document the
            // conservative latest-only-receipt behaviour.
            // A seated target (all of g_reachCompletedReticleTarget is seated) carries no support receipt:
            // Reach runs no first-person interpolation in a seat, and a seat holds no support grip. Its ray
            // only has to belong to this frame (ReachSeatedRayConsumable).
            ReachSeatedRayConsumable(sight.raySerial, sample.renderedEyePreparedSerial);
        if (!sightUsable)
        {
            g_reachFiringOriginSkips.fetch_add(1, std::memory_order_relaxed);
            g_reachFiringOriginSkipNoSightRay.fetch_add(
                1, std::memory_order_relaxed);
            return stockResult;
        }
        out[0] = sight.origin[0];
        out[1] = sight.origin[1];
        out[2] = sight.origin[2];
        g_reachFiringOriginMoves.fetch_add(1, std::memory_order_relaxed);
        return stockResult;
    }

    // The counter spans the complete original call as well as our feature
    // body. Worker-side frozen RIP scanning closes only the tiny relay/prologue
    // window before this increment; no trampoline or title-module pointer is
    // cleared until this scope has left.
    __declspec(noinline) uint64_t __fastcall ReachUnitCameraPositionHook(
        int32_t unitIndex, float* out)
    {
        const uintptr_t caller =
            reinterpret_cast<uintptr_t>(_ReturnAddress());
        uint64_t result = 0;
        g_reachCamera.activeCallbacks.fetch_add(
            1, std::memory_order_acq_rel);
        // Stage 3U: runtime ownership must follow a REAL Reach camera callback,
        // not the outer Present loop.  Save & Quit stops this path before the
        // pinned title DLL can unload, so this timestamp is also the clean
        // signal that the installed core has become stale.
        g_reachLastCamCopyMs.store(
            GetTickCount64(), std::memory_order_release);
        __try
        {
#if HALOMCCVR_DEV_DIAGNOSTICS
            if (g_config.dev_sim_bisect & 4)
            {
                if (const ReachUnitCameraPositionFn plain = g_origReachUnitCameraPosition)
                    result = plain(unitIndex, out);
                __leave;
            }
#endif
            result = ReachUnitCameraPositionBody(unitIndex, out, caller);
        }
        __finally
        {
            g_reachCamera.activeCallbacks.fetch_sub(
                1, std::memory_order_acq_rel);
        }
        return result;
    }

    // Feature-local revocation is immediate and lock-free. The hook itself is
    // disabled, quiesced, and removed with every other Reach detour below: its
    // trampoline points into haloreach.dll and must never outlive the module.
    void RevokeReachFiringOriginFeature()
    {
        g_reachFiringOriginReturnA.store(0, std::memory_order_release);
        g_reachFiringOriginReturnB.store(0, std::memory_order_release);
    }

    // HREK weapons.cpp has exactly one call into this unit-adjust transaction
    // from the projectile builder. By the time it runs Reach has selected the
    // firing weapon, barrel, marker/origin and deepest controlling unit. The
    // original remains responsible for all of that. For the exact local seated
    // unit only, replace its central direction with the line from that native
    // origin through the floating reticle point; every downstream ballistic,
    // spread and tracking stage remains stock.
    using ReachUnitAdjustFn = void(__fastcall*)(
        int32_t unitIndex, float* origin, float* direction,
        const float* basisForward, const float* barrelOffset,
        const float* optionalCameraPoint, uint8_t firesFromCamera,
        uint8_t useUnitAim, uint8_t collision, uint32_t simulation);
    ReachUnitAdjustFn g_origReachUnitAdjust = nullptr;
    void* g_reachUnitAdjustTarget = nullptr;

    // Reach game brightness. haloreach.dll+0x252E28 is Reach's screen
    // colour/gamma publisher and the exact homologue of the Halo 3/ODST
    // function the headset already proved: same (a0, a1, a2) shuffle, same
    // imported `powf` against a rodata base, same (a0, powf) / (a1, a0*a1)
    // pairs. It keeps its own trampoline for the same cross-title
    // stale-pointer reason as ODST's.
    HudXformFn g_origReachHudXform = nullptr;
    void* g_reachHudXformTarget = nullptr;

    std::atomic<bool> g_reachVehicleShotRedirectEnabled{false};
    std::atomic<uint32_t> g_reachVehicleShotRedirects{0};
    std::atomic<uint32_t> g_reachVehicleShotRedirectMisses{0};
    // Seated shots left to Reach's own aim because trace-and-reaim was live (no redirect needed).
    std::atomic<uint32_t> g_reachVehicleShotConverged{0};

    // HREK render_first_person_view.cpp has one output-user predicate before
    // either first-person render pass.  Reach's vehicle passenger camera leaves
    // that predicate non-NONE even when the seat independently allows personal
    // weapons, so the already-built weapon state never reaches interpolation or
    // the visible palette.  Override only that exact render caller while the
    // admitted outer owner is an allows-weapons passenger.  Simulation, camera,
    // steering and firing consumers of the same accessor remain stock.
    using ReachFirstPersonRenderGateFn = int32_t(__fastcall*)(int32_t);
    ReachFirstPersonRenderGateFn g_origReachFirstPersonRenderGate = nullptr;
    void* g_reachFirstPersonRenderGateTarget = nullptr;
    std::atomic<uintptr_t> g_reachFirstPersonRenderGateReturn{0};
    std::atomic<uint32_t> g_reachPassengerFirstPersonAdmissions{0};

    int32_t ReachFirstPersonRenderGateBody(
        int32_t outputUserIndex, uintptr_t caller)
    {
        ReachFirstPersonRenderGateFn original =
            g_origReachFirstPersonRenderGate;
        if (!original)
            return -1;
        const int32_t stock = original(outputUserIndex);
        if(g_reachScopeRendering && g_reachOwnerScope.active &&
            caller==g_reachFirstPersonRenderGateReturn.load(std::memory_order_acquire))
            return 0; // Exact native render predicate: non-NONE skips FP pixels.
        if(!kReachR_V24PassengerRenderAdmissionEnabled)return stock;
        if (static_cast<uint16_t>(stock) == 0xFFFFu ||
            caller != g_reachFirstPersonRenderGateReturn.load(
                std::memory_order_acquire))
        {
            return stock;
        }
        const ReachOwnerScope& owner = g_reachOwnerScope;
        if (!ReachPassengerNeedsFirstPersonRenderAdmission(
                owner.active, owner.vehicleViewApplied, owner.vehicle.active,
                g_config.vehicle_first_person, owner.vehicle.seatFlags,
                static_cast<uint16_t>(stock)))
        {
            return stock;
        }
        g_reachPassengerFirstPersonAdmissions.fetch_add(
            1, std::memory_order_relaxed);
        return -1;
    }

    // Entered only through ReachFirstPersonRenderGateThunk (reach_render_gate_thunk.asm), which preserves
    // the volatile registers the native's callers keep live and supplies `caller`: this function's own
    // _ReturnAddress() would be the thunk.
    extern "C" __declspec(noinline) int32_t ReachFirstPersonRenderGateEnter(
        int32_t outputUserIndex, uintptr_t caller)
    {
        int32_t result = -1;
        g_reachCamera.activeCallbacks.fetch_add(
            1, std::memory_order_acq_rel);
        __try
        {
            result = ReachFirstPersonRenderGateBody(
                outputUserIndex, caller);
        }
        __finally
        {
            g_reachCamera.activeCallbacks.fetch_sub(
                1, std::memory_order_acq_rel);
        }
        return result;
    }

    void ReachUnitAdjustBody(
        int32_t unitIndex, float* origin, float* direction,
        const float* basisForward, const float* barrelOffset,
        const float* optionalCameraPoint, uint8_t firesFromCamera,
        uint8_t useUnitAim, uint8_t collision, uint32_t simulation,
        bool& substituted)
    {
        // T-2 evidence only: whether one of this body's mod substitutions
        // produced the final ray. Never read by gameplay; the body's
        // substitution, collision-clip, receipt/admission and restore paths
        // are unchanged.
        substituted = false;
        ReachUnitAdjustFn original = g_origReachUnitAdjust;
        if (!original)
            return;
        original(
            unitIndex, origin, direction, basisForward, barrelOffset,
            optionalCameraPoint, firesFromCamera, useUnitAim, collision,
            simulation);
        // Co-op safe shots: the shot stays as Reach built it -- no re-aim through the intent point, no hand ray
        // on foot and no redirect in a seat.
        if (!Sight_FireTimeChangesAllowed())
        {
            if (origin && direction && unitIndex != -1 &&
                unitIndex == LegacyCollisionIgnoredObject(GameTitle::HaloReach))
                Sight_NoteFireTimeStoodDown(GameTitle::HaloReach);
            return;
        }
        // The same HREK-proven weapon transaction handles on-foot shots. Own
        // only the exact current local unit and a completed, fresh on-foot ray.
        // Reuse native world clipping from the already-safe stock origin to
        // the hand so extending through a wall cannot move a bullet behind it.
        if(origin && direction && g_enabled.load(std::memory_order_acquire) &&
            g_vrAim.load(std::memory_order_acquire) && VR_IsStereoEnabled() &&
            g_reachCamera.armed.load(std::memory_order_acquire) &&
            !g_reachCinematicLocked.load(std::memory_order_relaxed))
        {
            ReachCompletedReticleTargetSnapshot handRay{};
            ReachShotOccupationSnapshot occupationNow{};
            const bool onFootNow=ReachReadShotOccupation(occupationNow) &&
                !occupationNow.active;
            const int32_t currentUnit=LegacyCollisionIgnoredObject(GameTitle::HaloReach);
            const uint32_t generation=g_reachCamera.generation.load(std::memory_order_acquire);
            bool nativeOnFoot=false;
            if(currentUnit!=-1 && unitIndex==currentUnit && g_reachCamera.unitInVehicle)
            {
                __try { nativeOnFoot=!g_reachCamera.unitInVehicle(currentUnit); }
                __except(EXCEPTION_EXECUTE_HANDLER) { nativeOnFoot=false; }
            }
            // TRACE-AND-REAIM live (reach_sight_trace.inl): the direct-drive aim already points the
            // native shot through the traced point, so the shot leaves exactly where Reach fires it.
            // Moving its origin to the hand as well would correct it twice. Measure and stand down.
            if(onFootNow && nativeOnFoot && currentUnit!=-1 && unitIndex==currentUnit &&
                ReachConvergedShotLive(GetTickCount64()))
            {
                // THE SHOT THROUGH THE INTENT POINT: the direct drive's angles were solved from the
                // previous render's eye; this shot leaves from this tick's. Aim it from its own origin through the
                // point the provider actuated (shot_lag_logic.h; within 10 mm it is left as Reach built it). Reach's
                // aim_assist, which may still turn it at its crosshair hit, traces that query through the same
                // point (ReachSightReaimCrosshairQuery).
                // FLAT PARITY (shot_lag_logic.h 4f): through P moved with the eye from P's camera sample
                // to this fire's -- Reach's own unit camera evaluator asked in this fire (the camera the native
                // origin was just built on), once proven equal to E_P at rest; unproven or absent, P as published.
                SightPointSample sample{};
                uint64_t atUs=0;
                if(ReachSightReadIntentSample(kSightIntentShotMaxAgeMs*1000ull,sample,atUs))
                {
                    ReachNoteFireEyeNativeLine(unitIndex,origin,direction);   // dev: is that eye on this line?
                    float moved[3]{};
                    const float* point=Sight_ShotPointSample(GameTitle::HaloReach,SightTransportSite::UnitAdjust,
                        sample,false,sample.point,moved);
                    if(Sight_ReaimThroughPoint(GameTitle::HaloReach,SightShotSite::UnitAdjust,origin,direction,point))
                        substituted=true;   // T-2 evidence: the re-aimed ray is final here
                }
                else
                    Sight_NoteReaimSkipped(GameTitle::HaloReach,SightShotSite::UnitAdjust,shot_lag::IntentUse::Stale);
                ReachSightMeasureShot(unitIndex,origin,direction,optionalCameraPoint,firesFromCamera,useUnitAim);
                ReachSightNoteShotLag(SightShotPath::UnitAdjust,origin,direction,false,-1);
                return;
            }
            float handDirection[3]{};
            const bool owned=onFootNow && nativeOnFoot &&
                ReachReadCompletedReticleTarget(handRay,g_reachLocalShotRay) &&
                handRay.key.directParent==-1 &&   // an on-foot ray, never a seat's
                // F06: the published on-foot hand ray is consumed later than it
                // was produced; re-prove its receipt against this consuming
                // invocation, or leave the shot stock. F3: no consuming
                // prepared serial exists inside this weapon transaction, so the
                // ray serial is passed deliberately; the receipt slot is
                // latest-only, which is what refuses both an old ray and an old
                // receipt (see the port document).
                ReachPresentedRayConsumable(GameTitle::HaloReach, generation,
                    handRay.raySerial, handRay.supportEpoch,
                    handRay.supportTrusted, handRay.raySerial) &&
                ReachBuildHandShotDirection(generation,handRay.generation,
                    unitIndex,currentUnit,handRay.key.unitHandle,GetTickCount64(),
                    handRay.sampleMs,handRay.origin,handRay.target,handDirection);
            if(onFootNow && unitIndex==currentUnit && currentUnit!=-1 && !owned)
                g_reachHandShotMisses.fetch_add(1,std::memory_order_relaxed);
            if(owned)
            {
                auto& feature=g_reachWorldCollision;
                const float distance=Halo4WorldCollisionDistanceSquared(origin,handRay.origin);
                const float maximum=1.5f*kReachWorldUnitsPerMeter;
                bool clipped=false;
                float accepted[3]{};
                if(feature.installed.load(std::memory_order_acquire) &&
                    feature.generation==generation && feature.resolver &&
                    distance>=0 && distance<=maximum*maximum)
                {
                    memcpy(accepted,handRay.origin,sizeof(accepted));
                    const bool previousOwned=g_legacyCollisionOwnedQuery;
                    g_legacyCollisionOwnedQuery=true;
                    __try
                    {
                        reinterpret_cast<ReachCollisionResolveFn>(feature.resolver)(
                            origin,handRay.origin,accepted,unitIndex);
                        const float acceptedDistance=
                            Halo4WorldCollisionDistanceSquared(origin,accepted);
                        clipped=acceptedDistance>=0 && acceptedDistance<=maximum*maximum;
                    }
                    __except(EXCEPTION_EXECUTE_HANDLER) { clipped=false; }
                    g_legacyCollisionOwnedQuery=previousOwned;
                }
                if(clipped)
                {
                    memcpy(origin,accepted,sizeof(accepted));
                    memcpy(direction,handDirection,sizeof(handDirection));
                    g_reachHandShotMoves.fetch_add(1,std::memory_order_relaxed);
                    substituted=true; // T-2 evidence: the hand ray is final
                    return;
                }
                g_reachHandShotMisses.fetch_add(1,std::memory_order_relaxed);
            }
        }
        if (!origin || !direction ||
            !g_reachVehicleShotRedirectEnabled.load(
                std::memory_order_acquire) ||
            g_reachCinematicLocked.load(std::memory_order_relaxed))
        {
            return;
        }
        // SEATED TRACE-AND-REAIM live: the direct-drive aim already puts Reach's own crosshair line
        // through the traced point, and Reach turns this seat's shot at whatever that line hits (its
        // aim_assist, which runs after this call). Redirecting the shot here toward the fixed-distance
        // reticle point would undo that, locally only. Stand down, as the on-foot hand shot ray does; the
        // passenger origin substitution stands down with it (ReachUnitCameraPositionBody).
        if (ReachConvergedShotLive(GetTickCount64()))
        {
            ReachShotOccupationSnapshot seatedNow{};
            if (ReachReadShotOccupation(seatedNow) && seatedNow.active &&
                seatedNow.generation ==
                    g_reachCamera.generation.load(std::memory_order_acquire) &&
                seatedNow.key.unitHandle == unitIndex)
            {
                g_reachVehicleShotConverged.fetch_add(1, std::memory_order_relaxed);
                // Dev SHOT LAG: the seated shot before the assist turns it (its line is the crosshair-assist path).
                ReachSightNoteShotLag(SightShotPath::UnitAdjust, origin, direction, true,
                                      seatedNow.key.directParent);
                return;
            }
        }

        ReachShotOccupationSnapshot occupation{};
        ReachCompletedReticleTargetSnapshot target{};
        const bool occupationRead =
            ReachReadShotOccupation(occupation);
        const bool targetRead =
            ReachReadCompletedReticleTarget(target);
        const bool occupationCoherent = occupationRead &&
            g_reachShotOccupation.sequence.load(
                std::memory_order_acquire) == occupation.sequence;
        const bool targetCoherent = targetRead &&
            g_reachCompletedReticleTarget.sequence.load(
                std::memory_order_acquire) == target.sequence;
        const bool coherent = occupationCoherent && targetCoherent &&
            // F06: the presented point is consumed later than it was produced;
            // the receipt must still prove this consuming invocation's owner
            // against the live relationship, or the shot stays stock. F3: as at
            // the on-foot hand-shot site, no consuming prepared serial exists
            // in this weapon transaction, so the ray serial is passed
            // deliberately (latest-only receipt => an old ray and an old
            // receipt are both refused).
            // Seated, as the firing-origin site: no support receipt in a seat (ReachSeatedRayConsumable). No
            // consuming serial is in scope here, so only a nonzero ray serial is required (the F06 comment
            // above describes the on-foot receipt this seated target never carries).
            ReachSeatedRayConsumable(target.raySerial, target.raySerial);
        const uint32_t generation =
            g_reachCamera.generation.load(std::memory_order_acquire);
        const bool localCandidate = occupationCoherent && occupation.active &&
            occupation.generation == generation &&
            occupation.key.unitHandle == unitIndex;

        ReachShotDirectionSample sample{};
        sample.currentGeneration = generation;
        sample.nowMs = GetTickCount64();
        sample.occupationSampleMs = occupation.sampleMs;
        sample.targetSampleMs = target.sampleMs;
        sample.active = occupation.active;
        sample.firingUnitIndex = unitIndex;
        sample.occupation = occupation.key;
        sample.targetKey = target.key;
        memcpy(sample.origin, origin, sizeof(sample.origin));
        memcpy(sample.target, target.target, sizeof(sample.target));
        if (!coherent || !ReachShotDirectionSampleAdmitted(sample))
        {
            if (localCandidate)
            {
                g_reachVehicleShotRedirectMisses.fetch_add(
                    1, std::memory_order_relaxed);
            }
            return;
        }

        const float towardReticle[3] = {
            target.target[0] - origin[0],
            target.target[1] - origin[1],
            target.target[2] - origin[2]};
        const float lengthSquared =
            towardReticle[0] * towardReticle[0] +
            towardReticle[1] * towardReticle[1] +
            towardReticle[2] * towardReticle[2];
        if (!std::isfinite(lengthSquared) || lengthSquared <= 1.0e-8f)
        {
            g_reachVehicleShotRedirectMisses.fetch_add(
                1, std::memory_order_relaxed);
            return;
        }
        const float inverseLength = 1.0f / sqrtf(lengthSquared);
        const float normalized[3] = {
            towardReticle[0] * inverseLength,
            towardReticle[1] * inverseLength,
            towardReticle[2] * inverseLength};
        memcpy(direction, normalized, sizeof(normalized));
        g_reachVehicleShotRedirects.fetch_add(1, std::memory_order_relaxed);
        substituted=true; // T-2 evidence: the reticle redirect is final
    }

    // T-2 shot event for Reach. The unit-adjust transaction IS the engine's
    // projectile-builder call (HREK 0xD67EE0; the pinned retail module has
    // exactly one image caller, the projectile transaction at 0x4C303A), so
    // every invocation this hook serves is a firing invocation and one event
    // is published per invocation. Final origin/direction are read after the
    // body: post-substitution when a mod path produced the ray, otherwise the
    // engine's stock values. Reach consumes no prepared serial inside this
    // weapon transaction (F3), so the event carries the latest published
    // prepared serial - a bounded snapshot, never an equality claim.
    void PublishReachShotDiagnostic(int32_t unitIndex, const float* origin,
        const float* direction, bool substituted, bool firesFromCamera,
        bool unitAim)
    {
        uint32_t weapon = UINT32_MAX;
        uint8_t barrel = kTelemetryShotIndexUnknown;
        ReachReadFiringContextForTelemetry(weapon, barrel);
        PublishShotDiagnostic(GameTitle::HaloReach,
            g_reachCamera.generation.load(std::memory_order_acquire),
            static_cast<uint32_t>(unitIndex), weapon,
            kTelemetryShotIndexUnknown, barrel,
            /*predicted=*/false, substituted, firesFromCamera, unitAim,
            origin, direction);
    }

    __declspec(noinline) void __fastcall ReachUnitAdjustHook(
        int32_t unitIndex, float* origin, float* direction,
        const float* basisForward, const float* barrelOffset,
        const float* optionalCameraPoint, uint8_t firesFromCamera,
        uint8_t useUnitAim, uint8_t collision, uint32_t simulation)
    {
        // T-2 shot gate FIRST: one atomic load, before any diagnostic read.
        // The transaction below is gameplay and always runs; this only decides
        // whether the same invocation also publishes a shot event.
        const bool telemetryAccepting = Telemetry_WeaponEventsAccepting();
        g_reachCamera.activeCallbacks.fetch_add(
            1, std::memory_order_acq_rel);
        __try
        {
#if HALOMCCVR_DEV_DIAGNOSTICS
            if (g_config.dev_sim_bisect & 8)
            {
                if (const ReachUnitAdjustFn plain = g_origReachUnitAdjust)
                    plain(unitIndex, origin, direction, basisForward, barrelOffset, optionalCameraPoint,
                          firesFromCamera, useUnitAim, collision, simulation);
                __leave;
            }
#endif
            // The projectile transaction names its shooter here, before its aim_assist traces the crosshair: the
            // local player's fire only from here (shot_lag::FireMark; ReachMuzzleFireDetour opens the fire). Seated,
            // unitIndex is the occupant (the seated redirect below matches it to the occupation's unit).
            if (reinterpret_cast<uintptr_t>(_ReturnAddress())==g_reachCamera.base+0x4C303F)
            {
                const bool local=
                    unitIndex!=-1 && unitIndex==LegacyCollisionIgnoredObject(GameTitle::HaloReach);
                // FLAT PARITY (reach_fire_eye.inl): our shooter's eye at this fire, after the tick's move -- the
                // camera this very unit-adjust builds the native origin on -- for every consumer of this fire. With
                // no enclosing fire detour (t_reachFire none) there is no fire scope to reuse: asked afresh.
                if (local)
                    ReachMeasureFireEye(unitIndex,t_reachFire==shot_lag::kFireNone);
                t_reachFire=shot_lag::FireMark(t_reachFire,local);
            }
            if (reinterpret_cast<uintptr_t>(_ReturnAddress())==g_reachCamera.base+0x4C303F &&
                ReachApplyBarrelAim(unitIndex,origin,direction,basisForward,collision,simulation))
            {
                // The committed muzzle barrel produced this final ray.
                if (telemetryAccepting)
                    PublishReachShotDiagnostic(unitIndex,origin,direction,true,
                        firesFromCamera!=0,useUnitAim!=0);
                __leave;
            }
            bool substituted=false;
            ReachUnitAdjustBody(
                unitIndex, origin, direction, basisForward, barrelOffset,
                optionalCameraPoint, firesFromCamera, useUnitAim, collision,
                simulation, substituted);
            if (telemetryAccepting)
                PublishReachShotDiagnostic(unitIndex,origin,direction,
                    substituted,firesFromCamera!=0,useUnitAim!=0);
        }
        __finally
        {
            g_reachCamera.activeCallbacks.fetch_sub(
                1, std::memory_order_acq_rel);
        }
    }

    Halo3VehicleDebounce g_reachVehicleFpDebounce;
