    int OdstReadFpModelIdentity(uint16_t tag,uint32_t& checksum)
    {
        return LegacyAnatomicalRenderNodeCount(GameTitle::Halo3ODST,tag,&checksum);
    }

    bool Halo3SelectHeldPaletteSources(uint16_t tag, const int32_t* boneMap,
                                      FpInterpolationContext& context)
    {
        context.heldSources={};
        if (!context.valid || !context.source || !boneMap ||
            context.slot<0 || context.slot>1 || context.count<=0 || context.count>64 ||
            context.generation!=g_halo3RuntimeGeneration.load(std::memory_order_acquire) ||
            !LegacyClassifyRuntimeWeapon(GameTitle::Halo3,tag,context.generation,
                                        context.source,boneMap))
            return false;
        const int count=LegacyAnatomicalRenderNodeCount(GameTitle::Halo3,tag);
        int32_t remap[64]{};
        if (count<=0 || count>64 ||
            !SafeReadBytes(boneMap,remap,size_t(count)*sizeof(*remap)))
            return false;
        return ResolveHalo3HeldPaletteSources(true,
            std::span<const int32_t>{remap,size_t(count)},context.count,
            context.cameraControl,context.heldSources);
    }

    void LegacyObserveReloadModel(
        GameTitle title, uint16_t renderModelTag, uint32_t generation,
        const BoneMatrix* source, const int32_t* boneMap)
    {
        // Optional reload identity is independent of collision settings. Read
        // through each title's existing verified tag reader; never change a
        // palette, inventory, native animation or camera to select an accessory.
        if(source && boneMap && generation)
        {
            const bool primary=title==GameTitle::HaloReach ||
                (g_fpInterpolationContexts[0].source==source &&
                 g_fpInterpolationContexts[0].generation==generation);
            const bool secondary=title!=GameTitle::HaloReach&&
                g_fpInterpolationContexts[1].source==source&&
                g_fpInterpolationContexts[1].generation==generation;
            uint32_t identity=0;
            // Observe the native body mapping too: it establishes the appended
            // held range for unfamiliar modded models without name guessing.
            const bool held=(primary||secondary)&&LegacyClassifyRuntimeWeapon(
                title,renderModelTag,generation,source,boneMap);
            if((primary||secondary) && LegacyReadWeaponRenderModelChecksum(title,renderModelTag,identity) &&
                (held||weapon_model::Find(title,identity))) {
                const auto model=weapon_model::LiveIdentity(identity,renderModelTag);
                if(primary)VR_ObserveWeaponModel(title,generation,model);
                else VR_ObserveSecondaryWeaponModel(title,generation,model);
            }
        }
    }

    bool LegacyObserveWeaponRenderModel(
        GameTitle title, uint16_t renderModelTag, uint32_t generation,
        const BoneMatrix* source, const int32_t* boneMap)
    {
        LegacyObserveReloadModel(title,renderModelTag,generation,source,boneMap);
        LegacyWorldCollisionFeature* feature=LegacyCollisionForTitle(title);
        if(!feature || !generation || feature->generation!=generation)
            return false;
        if (!g_config.world_collision && !Sight_PhysicalMelee()) return false;
        // Observe the body even when its checksum is unfamiliar. A validated
        // native model remap can authorize an uncatalogued held model.
        const bool mappedWeapon=feature->runtimeBoundsProven.load(std::memory_order_acquire) &&
            LegacyClassifyRuntimeWeapon(title,renderModelTag,generation,source,boneMap);
        uint32_t checksum=0;
        if(!LegacyReadWeaponRenderModelChecksum(
                title,renderModelTag,checksum))
            return false;
        const bool catalogued=LegacyWeaponBoundsForTitle(title,checksum)!=nullptr;
        if (!catalogued && !mappedWeapon) return false;
        int32_t mappedRoot=-1;
        if(!source || !boneMap ||
            !SafeReadBytes(boneMap,&mappedRoot,sizeof(mappedRoot)) ||
            mappedRoot<0 || mappedRoot>=64) return false;
        // H3 and ODST's proven native interpolation slots own their source graphs.
        // Do not let a secondary submission evict the primary weapon identity.
        const int slot = (title == GameTitle::Halo3 || title == GameTitle::Halo3ODST) &&
            g_fpInterpolationContexts[1].source == source &&
            g_fpInterpolationContexts[1].generation == generation &&
            g_fpInterpolationContexts[1].slot == 1 ? 1 : 0;
        auto& observation=feature->weaponObservation[slot];
        uint32_t sequence=observation.sequence.load(std::memory_order_acquire);
        if ((sequence&1u) || !observation.sequence.compare_exchange_strong(
                sequence,sequence+1,std::memory_order_acq_rel)) return false;
        feature->weaponObservation[slot].root.store(mappedRoot,std::memory_order_relaxed);
        feature->weaponObservation[slot].source.store(source,std::memory_order_relaxed);
        feature->weaponObservation[slot].tag.store(
            renderModelTag,std::memory_order_relaxed);
        feature->weaponObservation[slot].checksum.store(
            checksum,std::memory_order_relaxed);
        feature->weaponObservation[slot].generation.store(
            generation,std::memory_order_relaxed);
        feature->weaponObservation[slot].atMs.store(
            GetTickCount64(),std::memory_order_relaxed);
        observation.sequence.store(sequence+2,std::memory_order_release);
        if (!catalogued) feature->unknownWeaponModels.fetch_add(1,std::memory_order_relaxed);
        return true;
    }

    bool LegacyBuildMappedWeaponBounds(
        GameTitle title, const FpInterpolationContext& context,
        const BoneMatrix& root, const BoneMatrix* solved, float output[][3],
        uint64_t& shapeId)
    {
        shapeId=0;
        auto* feature=LegacyCollisionForTitle(title);
        if(!feature || !solved || !context.valid || context.slot<0 ||
            context.slot>1 || (context.slot==1 && title!=GameTitle::Halo3 &&
                title!=GameTitle::Halo3ODST))
            return false;
        const auto& observation=feature->weaponObservation[context.slot];
        const uint32_t sequence=observation.sequence.load(std::memory_order_acquire);
        if (sequence&1u) return false;
        const uint64_t observedAt=feature->weaponObservation[context.slot].atMs.load(
            std::memory_order_acquire);
        if(!LegacyWeaponCollisionCacheCanSupply(GetTickCount64(),observedAt,
                feature->generation,feature->weaponObservation[context.slot].generation.load(
                    std::memory_order_relaxed))) return false;
        const int32_t mappedRoot=feature->weaponObservation[context.slot].root.load(
            std::memory_order_relaxed);
        if(!LegacyMappedWeaponRootIsUsable(mappedRoot,context.count,
                reinterpret_cast<uintptr_t>(feature->weaponObservation[context.slot].source.load(
                    std::memory_order_relaxed)),
                reinterpret_cast<uintptr_t>(context.source)))
            return false;
        const uint32_t tag=feature->weaponObservation[context.slot].tag.load(std::memory_order_relaxed);
        const uint32_t checksum=feature->weaponObservation[context.slot].checksum.load(
            std::memory_order_relaxed);
        if (observation.sequence.load(std::memory_order_acquire)!=sequence) return false;
        uint32_t liveChecksum=0;
        if(tag>0xFFFEu || !LegacyReadWeaponRenderModelChecksum(
                title,static_cast<uint16_t>(tag),liveChecksum) ||
            liveChecksum!=checksum) return false;
        Halo4WeaponCollisionBounds bounds{};
        if (LegacyReadRuntimeWeaponBounds(title,static_cast<uint16_t>(tag),checksum,bounds))
            feature->runtimeBoundsReads.fetch_add(1,std::memory_order_relaxed);
        else
        {
            feature->runtimeBoundsRefusals.fetch_add(1,std::memory_order_relaxed);
            const auto* authored=LegacyWeaponBoundsForTitle(title,checksum);
            if (!authored) return false;
            bounds.runtimeImportChecksum=checksum;
            memcpy(bounds.minimum,authored->minimum,sizeof(bounds.minimum));
            memcpy(bounds.maximum,authored->maximum,sizeof(bounds.maximum));
        }
        BoneMatrix modelRoot{};
        float basis[9]{};
        if(!ComposeBoneMatrices(root,solved[mappedRoot],modelRoot) ||
            !NormalizedBasis(modelRoot,basis)) return false;
        // Match the renderer: destination[0] = root * source[boneMap[0]].
        // The combined graph's source[0] is a body/camera root, not the gun.
        const bool valid=Halo4BuildWeaponCollisionBoundsSamples(
            bounds,modelRoot.scale,basis,modelRoot.translation,
            modelRoot.translation,modelRoot.translation,output,
            kLegacyCollisionWeaponSamples)==kLegacyCollisionWeaponSamples;
        if(valid) shapeId=LegacyRuntimeWeaponShapeId(static_cast<uint16_t>(tag),mappedRoot,bounds);
        return valid;
    }

    bool LegacySelectWeaponRenderModel(
        GameTitle title, uint16_t candidateTag, uint32_t generation,
        uint16_t& selectedTag, uint32_t& checksum)
    {
        selectedTag=0xFFFFu;
        checksum=0;
        if(LegacyObserveWeaponRenderModel(title,candidateTag,generation) &&
            LegacyReadWeaponRenderModelChecksum(title,candidateTag,checksum) &&
            LegacyWeaponBoundsForTitle(title,checksum))
        {
            selectedTag=candidateTag;
            return true;
        }

        LegacyWorldCollisionFeature* feature=LegacyCollisionForTitle(title);
        if(!feature) return false;
        const uint64_t now=GetTickCount64();
        const uint64_t observedAt=feature->weaponObservation[0].atMs.load(
            std::memory_order_acquire);
        const uint32_t observedGeneration=
            feature->weaponObservation[0].generation.load(
                std::memory_order_relaxed);
        if(!LegacyWeaponCollisionCacheCanSupply(
                now,observedAt,generation,observedGeneration))
            return false;
        const uint32_t rawTag=feature->weaponObservation[0].tag.load(
            std::memory_order_relaxed);
        const uint32_t observedChecksum=
            feature->weaponObservation[0].checksum.load(
                std::memory_order_relaxed);
        if(rawTag>0xFFFEu || !observedChecksum)
            return false;
        const uint16_t cachedTag=static_cast<uint16_t>(rawTag);
        uint32_t currentChecksum=0;
        if(!LegacyReadWeaponRenderModelChecksum(
                title,cachedTag,currentChecksum) ||
            currentChecksum!=observedChecksum ||
            !LegacyWeaponBoundsForTitle(title,currentChecksum))
            return false;
        selectedTag=cachedTag;
        checksum=currentChecksum;
        return true;
    }

    bool LegacyBuildAuthoredWeaponBounds(
        GameTitle title, uint16_t renderModelTag, const BoneMatrix& modelRoot,
        const float collisionRoot[3], const float wrist[3],
        float output[][3])
    {
        // ff6d1fd: catalog identity was found, but the combined body's node 0
        // is not proof of the submitted weapon's visible root. Keep this
        // rejected publication dormant until a mapped weapon root is supplied.
        constexpr bool kEnableCombinedBodyWeaponBounds = false;
        if (!kEnableCombinedBodyWeaponBounds) return false;
        LegacyWorldCollisionFeature* feature=LegacyCollisionForTitle(title);
        if(!feature) return false;
        uint16_t selectedTag=0xFFFFu;
        uint32_t checksum=0;
        if(!LegacySelectWeaponRenderModel(
                title,renderModelTag,feature->generation,
                selectedTag,checksum)) return false;
        (void)selectedTag;
        const LegacyWeaponCollisionBounds* authored=
            LegacyWeaponBoundsForTitle(title,checksum);
        if(!authored) return false;
        float basis[9]{};
        if(!NormalizedBasis(modelRoot,basis)) return false;
        Halo4WeaponCollisionBounds bounds{};
        bounds.runtimeImportChecksum=checksum;
        memcpy(bounds.minimum,authored->minimum,sizeof(bounds.minimum));
        memcpy(bounds.maximum,authored->maximum,sizeof(bounds.maximum));
        return Halo4BuildWeaponCollisionBoundsSamples(
            bounds,modelRoot.scale,basis,modelRoot.translation,
            collisionRoot,wrist,output,kLegacyCollisionWeaponSamples)==
            kLegacyCollisionWeaponSamples;
    }

    bool InstallLegacyWorldCollision(
        LegacyWorldCollisionFeature& feature, GameTitle title,
        uintptr_t base, size_t size, uint32_t generation,
        void* detour, uint32_t expectedRva,
        const char* signature, bool fourArgumentResolver,
        uint32_t schedulerRva, const char* schedulerSignature)
    {
        const char* const titleName=title==GameTitle::Halo3?"Halo 3":
            title==GameTitle::Halo3ODST?"ODST":
            title==GameTitle::HaloReach?"Reach":"Unknown title";
        static constexpr char kFiveArgumentResolveSignature[]=
            "48 8B C4 48 89 58 08 48 89 70 10 48 89 78 18 55 41 56 41 57 "
            "48 8D 68 A9 48 81 EC C0 00 00 00 48 8B 05 ?? ?? ?? ?? 41 83 CF "
            "FF 48 89 45 BF 49 8B F8 0F BA 6D BF 09";
        const char* const resolveSignature=
            signature?signature:kFiveArgumentResolveSignature;
        feature.title=title;
        feature.runtimeBoundsProven.store(false,std::memory_order_release);
        feature.generation=generation;
        const bool runtimeBounds=LegacyProveRuntimeWeaponBounds(title,base,size);
        feature.runtimeBoundsProven.store(runtimeBounds,std::memory_order_release);
        feature.runtimeBoundsReads.store(0);
        feature.runtimeBoundsRefusals.store(0);
        feature.unknownWeaponModels.store(0);
        LOG("%s runtime weapon bounds: %s; native held-model remap; shared world contact "
            "and physical melee samples; catalog/hand fallback is feature-local",titleName,
            runtimeBounds ? "proven" : "StockFallback (missing/moved/ambiguous native proof)");
        feature.fourArgumentResolver=fourArgumentResolver;
        feature.originalIsVectorTest=false;
        feature.installed.store(false,std::memory_order_release);
        feature.target=nullptr;
        feature.original=nullptr;
        feature.resolver=nullptr;
        feature.nextQueryAtMs.store(0,std::memory_order_release);
        feature.queryActive.store(false,std::memory_order_release);
        feature.engineCalls.store(0,std::memory_order_release);
        feature.queryTicks.store(0,std::memory_order_release);
        feature.targetMisses.store(0,std::memory_order_release);
        feature.seeds.store(0,std::memory_order_release);
        feature.worker[0]=LegacyCollisionWorkerHand{};
        feature.worker[1]=LegacyCollisionWorkerHand{};
        feature.callbacks.store(0,std::memory_order_release);
        feature.queries.store(0,std::memory_order_release);
        feature.contacts[0].store(0,std::memory_order_release);
        feature.contacts[1].store(0,std::memory_order_release);
        feature.weaponContacts.store(0,std::memory_order_release);
        feature.boundsPublished.store(0,std::memory_order_release);
        feature.boundsFallbacks.store(0,std::memory_order_release);
        feature.secondaryPublishedAtMs.store(0,std::memory_order_release);
        feature.secondaryPublishedObject.store(-1,std::memory_order_release);
        for(auto& observation : feature.weaponObservation)
        {
            observation.sequence.store(0,std::memory_order_release);
            observation.tag.store(0xFFFFu,std::memory_order_release);
            observation.checksum.store(0,std::memory_order_release);
            observation.generation.store(0,std::memory_order_release);
            observation.atMs.store(0,std::memory_order_release);
            observation.root.store(-1,std::memory_order_release);
            observation.source.store(nullptr,std::memory_order_release);
        }
        feature.applied[0].store(0,std::memory_order_release);
        feature.applied[1].store(0,std::memory_order_release);
        feature.failures.store(0,std::memory_order_release);
        const uintptr_t hit=sig::Find(base,size,resolveSignature);
        const bool unique=hit && !sig::Find(
            hit+1,base+size-hit-1,resolveSignature);
        if(!unique || hit!=base+expectedRva)
        {
            LOG("%s world collision StockFallback: editing-kit-mapped "
                "collision resolver was %s%s; camera, hands, input and "
                "OpenXR remain live",titleName,
                unique?"unique":"missing/ambiguous",
                unique&&hit!=base+expectedRva?" but moved":"");
            return false;
        }
        uintptr_t hookHit=hit;
        if(schedulerRva)
        {
            if(!schedulerSignature)
                return false;
            hookHit=sig::Find(base,size,schedulerSignature);
            const bool schedulerUnique=hookHit && !sig::Find(
                hookHit+1,base+size-hookHit-1,schedulerSignature);
            if(!schedulerUnique || hookHit!=base+schedulerRva)
            {
                LOG("%s world collision StockFallback: editing-kit-mapped "
                    "active collision scheduler was %s%s; camera, hands, "
                    "input and OpenXR remain live",titleName,
                    schedulerUnique?"unique":"missing/ambiguous",
                    schedulerUnique&&hookHit!=base+schedulerRva
                        ?" but moved":"");
                return false;
            }
        }
        void* trampoline=nullptr;
        void* const target=reinterpret_cast<void*>(hookHit);
        if(MH_CreateHook(target,detour,&trampoline)!=MH_OK || !trampoline)
        {
            LOG("%s world collision StockFallback: optional resolver hook "
                "creation failed",titleName);
            return false;
        }
        feature.target=target;
        feature.original=trampoline;
        feature.resolver=schedulerRva
            ? reinterpret_cast<void*>(hit):trampoline;
        feature.originalIsVectorTest=schedulerRva!=0;
        if(MCCVR_EnableHook(target)!=MH_OK)
        {
            MH_RemoveHook(target);
            feature.target=nullptr;
            feature.original=nullptr;
            feature.resolver=nullptr;
            feature.originalIsVectorTest=false;
            LOG("%s world collision StockFallback: optional resolver hook "
                "enable failed",titleName);
            return false;
        }
        feature.installed.store(true,std::memory_order_release);
        if(schedulerRva)
            LOG("%s world collision Installed: native resolve wrapper "
                "+0x%X, active central scheduler +0x%X; final visible hand "
                "extrema and checksum-selected authored weapon bounds; "
                "33 ms bounded sweeps, contact haptics, fail-open isolation",
                titleName,expectedRva,schedulerRva);
        else
            LOG("%s world collision Installed: native resolve wrapper +0x%X; "
                "final visible hand extrema and checksum-selected authored "
                "weapon bounds; 33 ms bounded sweeps, contact haptics, "
                "fail-open isolation",titleName,expectedRva);
        return true;
    }

    struct SharedMeleeTelemetry
    {
        std::atomic<uint32_t> polls{0}, unavailable{0}, invalidVelocity{0};
        std::atomic<uint32_t> crossings{0}, pulses{0}, cooldownBlocks{0}, peakCmPerSecond{0};
    };
    SharedMeleeTelemetry g_sharedMeleeTelemetry[6];

    SharedMeleeTelemetry* SharedMeleeForTitle(GameTitle title)
    {
        switch(title)
        {
        case GameTitle::Halo2: return &g_sharedMeleeTelemetry[0];
        case GameTitle::Halo3: return &g_sharedMeleeTelemetry[1];
        case GameTitle::Halo3ODST: return &g_sharedMeleeTelemetry[2];
        case GameTitle::HaloReach: return &g_sharedMeleeTelemetry[3];
        case GameTitle::Halo4: return &g_sharedMeleeTelemetry[4];
        case GameTitle::HaloCE: return &g_sharedMeleeTelemetry[5];
        default: return nullptr;
        }
    }

    void LegacyWorldCollisionLogTick()
    {
        const GameTitle title=TitleAdapter_GetActiveTitle();
        LegacyWorldCollisionFeature* feature=LegacyCollisionForTitle(title);
        static uint64_t lastLogMs=0;
        const uint64_t now=GetTickCount64();
        if(now-lastLogMs<2000) return;
        lastLogMs=now;
#if HALOMCCVR_DEV_DIAGNOSTICS
        ReachSimTraceFlush();   // whatever title is up: a trace's last ticks are written after its game has gone
#endif
        if(title==GameTitle::HaloReach){ReportReachContactMelee();ReportReachMuzzle();ReportReachSightTrace();ReportReachHeadRelative();ReportReachNavMarkers();ReportReachNavProjection();}
        if(title==GameTitle::Halo3) { ReportHalo3ContactMelee(); ReportHalo3WeaponHaptics(); ReportHalo3Avatar(); ReportHalo3PartDraw(); ReportHalo3PlayerTags(); }
        if(title==GameTitle::Halo3ODST){ReportOdstContactMelee();ReportOdstMuzzle();ReportOdstWeaponHaptics();ReportOdstControllerFingers();ReportOdstPlayerTags();}
        if(auto* melee=SharedMeleeForTitle(title))
            LOG("Physical melee title=%d: requested=%d world-contact=%d threshold=%.2f m/s; "
                "%u polls / %u unavailable, %u missing velocity, peak %.2f m/s, "
                "%u crossings / %u native-input pulses / %u cooldown blocks; native range/target/damage",
                static_cast<int>(title),Sight_PhysicalMelee()?1:0,g_config.world_collision?1:0,
                g_config.physical_melee_swing_speed,melee->polls.exchange(0),
                melee->unavailable.exchange(0),melee->invalidVelocity.exchange(0),
                melee->peakCmPerSecond.exchange(0)/100.0f,melee->crossings.exchange(0),
                melee->pulses.exchange(0),melee->cooldownBlocks.exchange(0));
        if(!feature) return;
        const char* const name=title==GameTitle::Halo3?"Halo 3":
            title==GameTitle::Halo3ODST?"ODST":"Reach";
        LOG("%s world collision: installed=%d requested=%d, %llu native "
            "queries, left/right contacts %llu/%llu, weapon contacts %llu, "
            "authored bounds %llu published / %llu hand-only fallback, "
            "visible corrections %llu/%llu, callbacks %u, isolated "
            "failures %llu; scheduling %llu engine calls / %llu ticks / "
            "%llu passed over inside a simulation tick (Co-op safe) / "
            "%llu target misses / %llu seeds, mapped gun root %d",
            name,
            feature->installed.load(std::memory_order_acquire)?1:0,
            g_config.world_collision?1:0,
            static_cast<unsigned long long>(feature->queries.exchange(
                0,std::memory_order_relaxed)),
            static_cast<unsigned long long>(feature->contacts[0].exchange(
                0,std::memory_order_relaxed)),
            static_cast<unsigned long long>(feature->contacts[1].exchange(
                0,std::memory_order_relaxed)),
            static_cast<unsigned long long>(feature->weaponContacts.exchange(
                0,std::memory_order_relaxed)),
            static_cast<unsigned long long>(feature->boundsPublished.exchange(
                0,std::memory_order_relaxed)),
            static_cast<unsigned long long>(feature->boundsFallbacks.exchange(
                0,std::memory_order_relaxed)),
            static_cast<unsigned long long>(feature->applied[0].exchange(
                0,std::memory_order_relaxed)),
            static_cast<unsigned long long>(feature->applied[1].exchange(
                0,std::memory_order_relaxed)),
            feature->callbacks.load(std::memory_order_acquire),
            static_cast<unsigned long long>(feature->failures.load(
                std::memory_order_relaxed)),
            static_cast<unsigned long long>(feature->engineCalls.exchange(0)),
            static_cast<unsigned long long>(feature->queryTicks.exchange(0)),
            static_cast<unsigned long long>(feature->insideTick.exchange(0)),
            static_cast<unsigned long long>(feature->targetMisses.exchange(0)),
            static_cast<unsigned long long>(feature->seeds.exchange(0)),
            feature->weaponObservation[0].root.load(std::memory_order_relaxed));
        LOG("%s runtime weapon bounds: proven=%d reads=%llu refusals=%llu "
            "unknown-model observations=%llu (contact and melee)",name,
            feature->runtimeBoundsProven.load()?1:0,feature->runtimeBoundsReads.exchange(0),
            feature->runtimeBoundsRefusals.exchange(0),feature->unknownWeaponModels.exchange(0));
        if(title==GameTitle::HaloReach)
            LOG("Reach on-foot hand shot ray: %u applied / %u local stock fallback; "
                "exact completed-pair controller origin/direction, native world clipping",
                g_reachHandShotMoves.exchange(0,std::memory_order_relaxed),
                g_reachHandShotMisses.exchange(0,std::memory_order_relaxed));
    }

    const ReachFpLayoutCacheEntry* ReachFindFrozenLayout(
        int liveCount, int view, int id, int slot)
    {
        for (const ReachFpLayoutCacheEntry& entry : g_reachFpPairScope.layouts)
            if (entry.valid && entry.liveSourceCount==liveCount &&
                entry.interpolationView==view &&
                entry.interpolationId==id &&
                entry.interpolationSlot==slot && entry.layout.Valid())
                return &entry;
        return nullptr;
    }

    void ReachLearnLayout(const ReachFpInterpolationContext& context,
                          uint16_t bodyTag,
                          const ReachFpBodyLayout& layout)
    {
        if (!context.source || !layout.Valid() || !g_reachFpPairScope.armed)
            return;
        ReachFpLayoutCacheEntry* destination=nullptr;
        for (ReachFpLayoutCacheEntry& entry : g_reachFpLayoutCache)
        {
            if (entry.valid && entry.generation==g_reachFpPairScope.generation &&
                entry.liveSourceCount==context.liveSourceCount &&
                entry.interpolationView==context.interpolationView &&
                entry.interpolationId==context.interpolationId &&
                entry.interpolationSlot==context.interpolationSlot)
            {
                if (!entry.invalidateNextPair && entry.bodyTag==bodyTag &&
                    ReachLayoutsEqual(entry.layout,layout))
                    return;
                destination=&entry;
                break;
            }
            if (!entry.valid && !destination)
                destination=&entry;
        }
        if (!destination)
            destination=&g_reachFpLayoutCache[0];
        *destination={};
        destination->valid=true;
        destination->generation=g_reachFpPairScope.generation;
        destination->liveSourceCount=context.liveSourceCount;
        destination->interpolationView=context.interpolationView;
        destination->interpolationId=context.interpolationId;
        destination->interpolationSlot=context.interpolationSlot;
        destination->bodyTag=bodyTag;
        destination->learnedPreparedSerial=g_reachFpPairScope.preparedSerial;
        destination->layout=layout;
        PublishReachFpStatus(1,static_cast<int>(layout.paletteBodyNodeCount),
                             context.liveSourceCount);
    }

    void ReachInvalidateLayoutNextPair(
        const ReachFpInterpolationContext& context)
    {
        for (ReachFpLayoutCacheEntry& entry : g_reachFpLayoutCache)
            if (entry.valid && entry.generation==g_reachFpPairScope.generation &&
                entry.liveSourceCount==context.liveSourceCount &&
                entry.interpolationView==context.interpolationView &&
                entry.interpolationId==context.interpolationId &&
                entry.interpolationSlot==context.interpolationSlot)
                entry.invalidateNextPair=true;
        PublishReachFpStatus(3,0,context.liveSourceCount);
    }
    void ReachBeginFpPairScope(uint32_t generation, uint64_t preparedSerial,
                               const ReachVrRenderSnapshot& tracking,
                               const FpExplicitPoseTargets& targets,
                               bool showSeatedLegs)
    {
        g_reachFpPairScope={};
        for (auto& context : g_reachFpInterpolations)
            context={};
        g_reachFpCaptureSerial=0;
        g_reachFpPairScope.armed=true;
        g_reachFpPairScope.showSeatedLegs=showSeatedLegs;
        g_reachFpPairScope.generation=generation;
        g_reachFpPairScope.preparedSerial=preparedSerial;
        g_reachFpPairScope.targets=targets;

        // Freeze only the exact controller sample used for this prepared
        // stereo pair. Finger posing is presentation-only and remains stock
        // whenever tracking freshness, native owner, or weapon identity is
        // ambiguous.
        if (g_config.experimental_body_ik &&
            tracking.preparedSerial==preparedSerial &&
            tracking.predictedDisplayTimeNs>0 &&
            tracking.trackingSpaceEpoch>0)
        {
            VrContactTrackingSnapshot contact{};
            if (VR_GetContactTrackingSnapshot(contact) &&
                contact.timeNs==tracking.predictedDisplayTimeNs &&
                contact.referenceEpoch==tracking.trackingSpaceEpoch &&
                contact.leftHanded==tracking.leftHanded &&
                contact.handAlignment==tracking.handAlignment &&
                contact.controllerFingers[0].valid)
            {
                uint32_t owner=UINT32_MAX,weapon=UINT32_MAX,detail=0;
                if (ReachPrimaryWeaponEvidence(generation,owner,weapon,detail,
                        nullptr))
                {
                    g_reachFpPairScope.fingerSampleExact=true;
                    g_reachFpPairScope.fingerWeaponEvidenceValid=true;
                    g_reachFpPairScope.secondaryWeaponPresent=(detail&1u)!=0;
                    g_reachFpPairScope.supportFingerIsLeft=
                        FingerAnatomicalSupportSide(tracking.handAlignment)==0;
                    g_reachFpPairScope.supportFingerInput=
                        contact.controllerFingers[0];
                    g_reachFpPairScope.fingerWeaponOwner=owner;
                    g_reachFpPairScope.fingerPrimaryWeapon=weapon;
                    g_reachFpPairScope.fingerLeftHanded=tracking.leftHanded;
                    g_reachFpPairScope.fingerHandAlignment=tracking.handAlignment;
                    g_reachFpPairScope.fingerTrackingSerial=contact.serial;
                    g_reachFpPairScope.fingerTrackingEpoch=contact.referenceEpoch;
                    g_reachFpPairScope.fingerDisplayTimeNs=contact.timeNs;
                }
            }
        }

        // The 82/67 output counts alone also belong to Reach's third-person
        // Spartan/Elite render models. A palette may only become the native
        // seated-leg consumer on a LATER stereo pair after its exact immutable
        // HREK checksum/count tuple has been read at this outer boundary.
        for (const ReachFpLegPaletteObservation& observation :
             g_reachFpLegPaletteObservations)
        {
            if (!ReachFpLegObservationCanValidate(
                    observation.valid,observation.generation,
                    observation.observedPreparedSerial,
                    generation,preparedSerial))
            {
                continue;
            }
            uint32_t checksum=0;
            int nodeCount=0;
            const bool identityRead=ReachReadRenderModelIdentity(
                observation.tag,checksum,nodeCount);
            const ReachFpLegPaletteKind kind=identityRead
                ? ClassifyReachFpLegPalette(checksum,nodeCount)
                : ReachFpLegPaletteKind::None;
            if (kind!=ReachFpLegPaletteKind::None &&
                nodeCount==observation.nodeCount)
            {
                g_reachFpLegPaletteCache={
                    true,generation,observation.observedPreparedSerial,
                    observation.tag,kind};
                break;
            }
            g_reachFpLegPaletteIdentityRejects.fetch_add(
                1,std::memory_order_relaxed);
        }
        for (auto& observation : g_reachFpLegPaletteObservations)
            observation={};

        if (g_reachFpLegPaletteCache.valid &&
            g_reachFpLegPaletteCache.generation==generation &&
            preparedSerial>g_reachFpLegPaletteCache.learnedPreparedSerial)
        {
            uint32_t checksum=0;
            int nodeCount=0;
            const bool identityRead=ReachReadRenderModelIdentity(
                g_reachFpLegPaletteCache.tag,checksum,nodeCount);
            const ReachFpLegPaletteKind kind=identityRead
                ? ClassifyReachFpLegPalette(checksum,nodeCount)
                : ReachFpLegPaletteKind::None;
            if (kind==g_reachFpLegPaletteCache.kind &&
                kind!=ReachFpLegPaletteKind::None)
            {
                g_reachFpPairScope.legPaletteValid=true;
                g_reachFpPairScope.legPaletteTag=
                    g_reachFpLegPaletteCache.tag;
                g_reachFpPairScope.legPaletteKind=kind;
            }
            else
            {
                g_reachFpLegPaletteCache={};
                g_reachFpLegPaletteIdentityRejects.fetch_add(
                    1,std::memory_order_relaxed);
            }
        }
        else if (g_reachFpLegPaletteCache.valid &&
                 g_reachFpLegPaletteCache.generation!=generation)
        {
            g_reachFpLegPaletteCache={};
        }

        size_t frozen=0;
        for (ReachFpLayoutCacheEntry& entry : g_reachFpLayoutCache)
        {
            if (entry.valid && (entry.generation!=generation ||
                                entry.invalidateNextPair))
                entry={};
            if (DecideReachFpPairLayout(
                    entry.valid,entry.invalidateNextPair,entry.generation,
                    entry.learnedPreparedSerial,generation,preparedSerial)==
                    ReachFpPairLayoutDecision::Active &&
                frozen<kReachFpLayoutCacheCapacity)
                g_reachFpPairScope.layouts[frozen++]=entry;
        }
        g_fpStereoSolveScope={};
        g_fpStereoSolveScope.armed=true;
        if (targets.centerRootValid)
        {
            g_fpStereoSolveScope.centerRootValid=true;
            g_fpStereoSolveScope.centerRoot=targets.centerRoot;
        }
    }

    void ReachEndFpPairScope()
    {
        g_stereoEye.store(-1,std::memory_order_release);
        g_fpStereoSolveScope={};
        for (auto& context : g_reachFpInterpolations)
            context={};
        g_reachFpCaptureSerial=0;
        g_reachFpPairScope={};
    }

    void ReachApplyFreeSupportFingerPose(uint16_t tag,int paletteCount,
        const ReachFpInterpolationContext& context,BoneMatrix* destination) noexcept
    {
        if(!destination || !g_config.experimental_body_ik ||
            !g_reachFpPairScope.armed || !g_reachFpPairScope.fingerSampleExact ||
            !g_reachFpPairScope.fingerWeaponEvidenceValid ||
            context.generation!=g_reachFpPairScope.generation ||
            context.preparedSerial!=g_reachFpPairScope.preparedSerial ||
            !context.valid || !context.transformed || context.interpolationView!=0 ||
            context.interpolationSlot!=0 ||
            g_reachFpPairScope.secondaryWeaponPresent)
        {
            g_reachFingerPoseRefused.fetch_add(1,std::memory_order_relaxed);
            return;
        }
        const bool supportAttached=context.targets.supportGripResolved
            ? context.targets.supportGripAttached : context.targets.twoHandAimActive;
        if(!reach_fingers::FreeSupportPoseAdmitted(true,true,true,
            g_reachFpPairScope.secondaryWeaponPresent,supportAttached,
            context.targets.twoHandAimActive,g_reachFpPairScope.fingerSampleExact,
            context.interpolationSlot==0))
        {
            g_reachFingerPoseRefused.fetch_add(1,std::memory_order_relaxed);
            return;
        }
        uint32_t owner=UINT32_MAX,weapon=UINT32_MAX,detail=0;
        VrContactTrackingSnapshot currentFingerSample{};
        if(!ReachPrimaryWeaponEvidence(context.generation,owner,weapon,detail,
                nullptr) || owner!=g_reachFpPairScope.fingerWeaponOwner ||
            weapon!=g_reachFpPairScope.fingerPrimaryWeapon ||
            ((detail&1u)!=0)!=g_reachFpPairScope.secondaryWeaponPresent ||
            !VR_GetContactTrackingSnapshot(currentFingerSample) ||
            currentFingerSample.serial!=g_reachFpPairScope.fingerTrackingSerial ||
            currentFingerSample.timeNs!=g_reachFpPairScope.fingerDisplayTimeNs ||
            currentFingerSample.referenceEpoch!=g_reachFpPairScope.fingerTrackingEpoch ||
            currentFingerSample.leftHanded!=g_reachFpPairScope.fingerLeftHanded ||
            currentFingerSample.handAlignment!=g_reachFpPairScope.fingerHandAlignment ||
            !currentFingerSample.controllerFingers[0].valid ||
            currentFingerSample.controllerFingers[0].trigger!=
                g_reachFpPairScope.supportFingerInput.trigger ||
            currentFingerSample.controllerFingers[0].grip!=
                g_reachFpPairScope.supportFingerInput.grip)
        {
            g_reachFingerPoseRefused.fetch_add(1,std::memory_order_relaxed);
            return;
        }
        uint32_t checksum=0;
        int verifiedCount=0;
        if(!ReachReadRenderModelIdentity(tag,checksum,verifiedCount) ||
            verifiedCount!=paletteCount || (paletteCount!=47&&paletteCount!=41))
        {
            g_reachFingerPoseRefused.fetch_add(1,std::memory_order_relaxed);
            return;
        }
        AnatomicalPalmMarkers markers{};
        if(!ReachAnatomicalPalmMarkers(checksum,paletteCount,markers))
        {
            g_reachFingerPoseRefused.fetch_add(1,std::memory_order_relaxed);
            return;
        }
        const unsigned side=g_reachFpPairScope.supportFingerIsLeft?0u:1u;
        const int wristNode=side==0?markers.leftNode:markers.rightNode;
        if(wristNode<0||wristNode>=paletteCount)
        {
            g_reachFingerPoseRefused.fetch_add(1,std::memory_order_relaxed);
            return;
        }
        Halo4FloatingTransform wrist{},palm{};
        wrist.scale=destination[wristNode].scale;
        std::memcpy(wrist.rotation,destination[wristNode].rotation,
            sizeof(wrist.rotation));
        std::memcpy(wrist.translation,destination[wristNode].translation,
            sizeof(wrist.translation));
        if(!Halo4FloatingTransformValid(wrist) ||
            !Halo4ComposeFloatingTransforms(wrist,
                side==0?markers.left:markers.right,palm))
        {
            g_reachFingerPoseRefused.fetch_add(1,std::memory_order_relaxed);
            return;
        }
        const float palmDown[3]{-palm.rotation[6],-palm.rotation[7],
            -palm.rotation[8]};
        BoneMatrix before[reach_fingers::kSpartanNodeCount]{};
        BoneMatrix candidate[reach_fingers::kSpartanNodeCount]{};
        const size_t bytes=size_t(paletteCount)*sizeof(BoneMatrix);
        if(!SafeReadBytes(destination,before,bytes))
        {
            g_reachFingerPoseWriteFailures.fetch_add(1,std::memory_order_relaxed);
            return;
        }
        const bool solved=reach_fingers::Apply(checksum,
            static_cast<unsigned>(paletteCount),side,before,palmDown,
            g_reachFpPairScope.supportFingerInput,candidate);
        if(!solved)
        {
            g_reachFingerPoseRefused.fetch_add(1,std::memory_order_relaxed);
            return;
        }
        if(!SafeWriteBytes(destination,candidate,bytes))
        {
            if(!SafeWriteBytes(destination,before,bytes))
                g_reachFingerPoseRollbackFailures.fetch_add(
                    1,std::memory_order_relaxed);
            g_reachFingerPoseWriteFailures.fetch_add(1,std::memory_order_relaxed);
            return;
        }
        g_reachFingerPoseApplied.fetch_add(1,std::memory_order_relaxed);
    }

    void ReachObserveFpLegPalette(uint16_t tag, int nodeCount)
    {
        if (!g_reachFpPairScope.armed ||
            (nodeCount!=kReachSpartanFpLegNodeCount &&
             nodeCount!=kReachEliteFpLegNodeCount))
        {
            return;
        }
        ReachFpLegPaletteObservation* destination=nullptr;
        for (auto& observation : g_reachFpLegPaletteObservations)
        {
            if (observation.valid &&
                observation.generation==g_reachFpPairScope.generation &&
                observation.observedPreparedSerial==
                    g_reachFpPairScope.preparedSerial &&
                observation.tag==tag)
            {
                return;
            }
            if (!observation.valid && !destination)
                destination=&observation;
        }
        if (!destination)
            return;
        *destination={
            true,g_reachFpPairScope.generation,
            g_reachFpPairScope.preparedSerial,tag,nodeCount};
        g_reachFpLegPaletteObservationCount.fetch_add(
            1,std::memory_order_relaxed);
    }

    bool ReachBuildCenterFpRoot(
        const unsigned char* compact, const float* positionOverride,
        BoneMatrix& out)
    {
        if (!compact) return false;
        const float* pos=reinterpret_cast<const float*>(compact+0x00);
        const float* fwdIn=reinterpret_cast<const float*>(compact+0x0C);
        const float* upIn=reinterpret_cast<const float*>(compact+0x18);
        float fwd[3]={fwdIn[0],fwdIn[1],fwdIn[2]};
        float up[3]={upIn[0],upIn[1],upIn[2]};
        const float fl=sqrtf(fwd[0]*fwd[0]+fwd[1]*fwd[1]+fwd[2]*fwd[2]);
        if (!isfinite(fl) || fl<1e-4f) return false;
        for (float& component : fwd) component/=fl;
        float left[3]={up[1]*fwd[2]-up[2]*fwd[1],
                       up[2]*fwd[0]-up[0]*fwd[2],
                       up[0]*fwd[1]-up[1]*fwd[0]};
        const float ll=sqrtf(left[0]*left[0]+left[1]*left[1]+left[2]*left[2]);
        if (!isfinite(ll) || ll<1e-4f) return false;
        for (float& component : left) component/=ll;
        up[0]=fwd[1]*left[2]-fwd[2]*left[1];
        up[1]=fwd[2]*left[0]-fwd[0]*left[2];
        up[2]=fwd[0]*left[1]-fwd[1]*left[0];
        out={};
        out.scale=1.0f;
        memcpy(out.rotation,fwd,sizeof(fwd));
        memcpy(out.rotation+3,left,sizeof(left));
        memcpy(out.rotation+6,up,sizeof(up));
        memcpy(out.translation,positionOverride ? positionOverride : pos,
               sizeof(out.translation));
        return ReachBoneMatrixFinite(out);
    }

    bool ReachBuildPreparedControllerTarget(
        const ReachVrRenderSnapshot& tracking, bool left,
        const float gameplayBase[3], BoneMatrix& out, float& meshScale,
        contact_melee::TrackingToWorld* contactSpace=nullptr,
        contact_melee::TrackingToWorld* contactController=nullptr,
        BoneMatrix* neutralVisual=nullptr)
    {
        const bool valid=left ? tracking.leftControllerValid
                              : tracking.rightAimValid;
        if (!valid || !gameplayBase) return false;
        float q[4],p[3];
        if (left)
        {
            memcpy(q,tracking.leftControllerOrientation,sizeof(q));
            memcpy(p,tracking.leftControllerPosition,sizeof(p));
        }
        else
        {
            memcpy(q,tracking.rightAimOrientation,sizeof(q));
            memcpy(p,tracking.rightAimPosition,sizeof(p));
        }
        float ql=0.0f;
        for (float component : q)
        {
            if (!isfinite(component)) return false;
            ql+=component*component;
        }
        ql=sqrtf(ql);
        if (!isfinite(ql) || ql<1e-5f) return false;
        for (float& component : q) component/=ql;
        if (contactController)
        {
            // Contact motion follows the physical hand. The visual two-hand
            // solver still controls the mesh, and invalid contact tracking
            // cannot reject the existing first-person render transaction.
            *contactController={};
            if ((!left && !tracking.rightPhysicalValid) ||
                !contactController->SetPose(left ? q : tracking.rightPhysicalOrientation,p))
                contactController->unitsPerMetre=0;
        }
        float hullYaw = 0.0f, hullPitch = 0.0f;
        const bool followValid =
            Halo3ReadRollStableFollow(hullYaw, hullPitch);
        float basis[9];
        BuildTrackedGameBasisFromFrame(
            q, false, followValid, hullYaw, hullPitch, basis);
        float neutralBasis[9];memcpy(neutralBasis,basis,sizeof(neutralBasis));
        float defaultYaw=0,defaultPitch=0,defaultRoll=0;
        if(!left)VR_ReachDefaultVisualAngles(defaultYaw,defaultPitch,defaultRoll);
        const float visualYaw=g_config.barrel_yaw_deg+defaultYaw;
        const float visualPitch=g_config.barrel_pitch_deg+defaultPitch;
        const float visualRoll=g_config.barrel_roll_deg+defaultRoll;
        if (left)
        {
            float mount[9],trimmed[9];
            BasisFromAngles(-g_config.gun_yaw_deg*0.0174533f,
                             g_config.gun_pitch_deg*0.0174533f,
                            -g_config.gun_roll_deg*0.0174533f,mount);
            MultiplyBases(basis,mount,trimmed);
            memcpy(basis,trimmed,sizeof(basis));
        }
        else if (visualPitch!=0.0f ||
                 visualYaw!=0.0f ||
                 visualRoll!=0.0f)
        {
            // Mesh-only barrel trim (per title profile); aim ray untouched.
            float mount[9],trimmed[9];
            BasisFromAngles(-visualYaw*0.0174533f,
                             visualPitch*0.0174533f,
                            -visualRoll*0.0174533f,mount);
            MultiplyBases(basis,mount,trimmed);
            bool finite=true;
            for(int j=0;j<9;++j) if(!isfinite(trimmed[j])){finite=false;break;}
            if(finite) memcpy(basis,trimmed,sizeof(basis));
        }
        const float dx=p[0]-g_headPosRef[0];
        const float dy=p[1]-g_headPosRef[1];
        const float dz=p[2]-g_headPosRef[2];
        const float sh=sinf(g_headYawRef),ch=cosf(g_headYawRef);
        const float roomForward=dx*sh-dz*ch;
        const float roomRight=dx*ch+dz*sh;
        const float cg=cosf(g_gameYawRef),sg=sinf(g_gameYawRef);
        const float scale=g_worldScale.load(std::memory_order_relaxed);
        float offset[3]{};
        float positionBasis[9]{};
        const float positionLocal[3] = {roomForward, -roomRight, dy};
        float positionWorld[3]{};
        const bool positionFollows =
            followValid &&
            Halo3ComposeRollStableFollowBasis(
                hullYaw, hullPitch, g_gameYawRef,
                0.0f, 0.0f, 0.0f, positionBasis) &&
            Halo3TransformBasisVector(
                positionBasis, positionLocal, positionWorld);
        if (positionFollows)
        {
            offset[0] = positionWorld[0] * scale;
            offset[1] = positionWorld[1] * scale;
            offset[2] = positionWorld[2] * scale;
        }
        else
        {
            offset[0] = (cg*roomForward+sg*roomRight)*scale;
            offset[1] = (sg*roomForward-cg*roomRight)*scale;
            offset[2] = dy*scale;
        }
        if (contactSpace)
        {
            // Invert the SAME position transform used by this hand. Native
            // geometry can then be compared in physical tracking metres.
            if (!positionFollows)
            {
                const float flat[9]{cg,sg,0,-sg,cg,0,0,0,1};
                memcpy(positionBasis,flat,sizeof(flat));
            }
            *contactSpace={};
            contactSpace->unitsPerMetre=scale;
            contactSpace->axis[0]={positionBasis[0]*sh-positionBasis[3]*ch,
                positionBasis[1]*sh-positionBasis[4]*ch,positionBasis[2]*sh-positionBasis[5]*ch};
            contactSpace->axis[1]={positionBasis[6],positionBasis[7],positionBasis[8]};
            contactSpace->axis[2]={-positionBasis[0]*ch-positionBasis[3]*sh,
                -positionBasis[1]*ch-positionBasis[4]*sh,-positionBasis[2]*ch-positionBasis[5]*sh};
            const auto reference=contactSpace->World({g_headPosRef[0],g_headPosRef[1],g_headPosRef[2]});
            contactSpace->origin={gameplayBase[0]-reference.x,gameplayBase[1]-reference.y,
                                  gameplayBase[2]-reference.z};
        }
        const float standoff=weapon_alignment::Forward(left,(left?g_config.left_gun_forward_m:g_config.gun_forward_m),g_config.left_hand_forward_m)*scale;
        const float rightOff=weapon_alignment::Right(false,(left?g_config.left_gun_right_m:g_config.gun_right_m))*scale;
        const float upOff=weapon_alignment::Up((left?g_config.left_gun_up_m:g_config.gun_up_m))*scale;
        out={};
        out.scale=1.0f;
        memcpy(out.rotation,basis,sizeof(basis));
        for (int axis=0;axis<3;++axis)
            out.translation[axis]=gameplayBase[axis]+offset[axis]+
                basis[axis]*standoff + basis[3+axis]*rightOff +
                basis[6+axis]*upOff;
        if (neutralVisual) {
            *neutralVisual=out;
            if (!left) {
                memcpy(neutralVisual->rotation,neutralBasis,sizeof(neutralBasis));
                for(int i=0;i<3;++i) neutralVisual->translation[i]+=
                    (neutralBasis[i]-basis[i])*standoff+(neutralBasis[3+i]-basis[3+i])*rightOff+
                    (neutralBasis[6+i]-basis[6+i])*upOff;
            }
        }
        meshScale=left
            ? Clamp(g_config.left_hand_scale,0.3f,3.0f)
            : Clamp(g_config.gun_scale,0.3f,3.0f);
        return ReachBoneMatrixFinite(out) && isfinite(meshScale);
    }

    bool ReachAlignRightTargetToAuthoredBarrel(
        const BoneMatrix& baseTarget, const BoneMatrix& authoredWrist,
        BoneMatrix& alignedTarget)
    {
        float barrelLocal[3]={authoredWrist.rotation[0],
                              authoredWrist.rotation[3],
                              authoredWrist.rotation[6]};
        const float length=sqrtf(barrelLocal[0]*barrelLocal[0]+
                                 barrelLocal[1]*barrelLocal[1]+
                                 barrelLocal[2]*barrelLocal[2]);
        if (!isfinite(length) || length<1e-4f) return false;
        for (float& component : barrelLocal) component/=length;
        float worldBarrel[3]={0.0f,0.0f,0.0f};
        for (int column=0;column<3;++column)
            for (int row=0;row<3;++row)
                worldBarrel[row]+=baseTarget.rotation[column*3+row]*
                    barrelLocal[column];
        const float ray[3]={baseTarget.rotation[0],baseTarget.rotation[1],
                            baseTarget.rotation[2]};
        float swing[9],rotated[9];
        ShortestArcRotation(worldBarrel,ray,swing);
        MultiplyBases(swing,baseTarget.rotation,rotated);
        alignedTarget=baseTarget;
        memcpy(alignedTarget.rotation,rotated,sizeof(rotated));
        return ReachBoneMatrixFinite(alignedTarget);
    }

    // Reach's verified body maps resolve the left wrist and publish the
    // complete source-space left-hand descendant mask, including custom order.
    // The shared rigid (arm_ik=0) reconstruction intentionally carries the
    // whole weapon assembly from the right wrist; that is correct for the gun.
    // HREK proves the visible left-hand skin is also weighted across its hidden
    // upper-arm/forearm/humerus/radius branch. Apply the controller delta only
    // to the visible hand. The later Reach-only presentation pass co-locates
    // those hidden influence records at the solved wrist before collapsing
    // them, so their geometry disappears without pulling the glove back toward
    // four separate arm pivots. Live animation/marker graphs remain untouched.
    bool ReachBindFloatingLeftHandToController(
        const BoneMatrix& renderRoot, const FpInterpolationContext& fp,
        uint64_t leftControllerOwnedSourceBranch,
        const FpExplicitPoseTargets& targets)
    {
        if (!targets.leftWristValid)
            return true;
        if (!ReachBoneMatrixFinite(renderRoot) ||
            !ReachBoneMatrixFinite(targets.leftWrist) ||
            fp.count<=0 ||
            fp.count>static_cast<int>(kReachFpMaxSourceNodeCount) ||
            fp.lWrist<0 || fp.lWrist>=fp.count ||
            fp.lWrist>=64 ||
            !(fp.lWristDescendants&(uint64_t{1}<<fp.lWrist)) ||
            (leftControllerOwnedSourceBranch&fp.lWristDescendants)!=
                fp.lWristDescendants ||
            (leftControllerOwnedSourceBranch&fp.wristDescendants)!=0 ||
            (fp.count<64 &&
             (leftControllerOwnedSourceBranch>>fp.count)!=0))
        {
            return false;
        }

        BoneMatrix currentWristWorld{}, inverseCurrentWrist{}, worldDelta{};
        BoneMatrix inverseRoot{}, deltaRoot{}, recordDelta{};
        if (!ComposeBoneMatrices(
                renderRoot,g_fpPaletteScratch[fp.lWrist],currentWristWorld) ||
            !InvertBoneMatrix(currentWristWorld,inverseCurrentWrist) ||
            !ComposeBoneMatrices(
                targets.leftWrist,inverseCurrentWrist,worldDelta) ||
            !InvertBoneMatrix(renderRoot,inverseRoot) ||
            !ComposeBoneMatrices(worldDelta,renderRoot,deltaRoot) ||
            !ComposeBoneMatrices(inverseRoot,deltaRoot,recordDelta))
        {
            return false;
        }

        for (int node=0;node<fp.count && node<64;++node)
        {
            if (!(fp.lWristDescendants&(uint64_t{1}<<node)))
                continue;
            BoneMatrix transformed{};
            if (!ComposeBoneMatrices(
                    recordDelta,g_fpPaletteScratch[node],transformed) ||
                !ReachBoneMatrixFinite(transformed))
            {
                return false;
            }
            g_fpPaletteScratch[node]=transformed;
        }

        BoneMatrix verifiedWrist{};
        if (!ComposeBoneMatrices(
                renderRoot,g_fpPaletteScratch[fp.lWrist],verifiedWrist) ||
            !ReachBoneMatrixFinite(verifiedWrist))
        {
            return false;
        }
        for (int axis=0;axis<3;++axis)
            if (fabsf(verifiedWrist.translation[axis]-
                      targets.leftWrist.translation[axis])>0.01f)
                return false;
        return true;
    }

    std::atomic<uint64_t> g_reachAnatomicalApplications{0};
    std::atomic<uint64_t> g_reachAnatomicalRefusals{0};

    bool ReachRouteLeftHandedPalette(uint16_t tag, const int32_t* boneMap, const FpInterpolationContext& fp,
        const BoneMatrix& root, const FpExplicitPoseTargets& rawTargets)
    {
        if (!rawTargets.rightWristValid || !rawTargets.leftWristValid ||
            fp.count <= 0 || fp.count > int(kReachFpMaxSourceNodeCount) ||
            fp.heldObjectStart <= 0 || fp.heldObjectStart > 64 ||
            !fp.heldSources.explicitMap)
            return false;
        uint32_t checksum = 0;
        int bodyCount = 0;
        AnatomicalPalmMarkers palms{};
        if (!ReachReadRenderModelIdentity(tag,checksum,bodyCount) ||
            bodyCount != fp.heldObjectStart ||
            !ReachAnatomicalPalmMarkers(checksum,bodyCount,palms)) return false;
        int32_t remap[64]{};
        if (!boneMap || !SafeReadBytes(boneMap,remap,size_t(bodyCount)*sizeof(*remap)) ||
            remap[palms.rightNode] != fp.wrist || remap[palms.leftNode] != fp.lWrist)
            return false;
        const auto value = [](const BoneMatrix& input) {
            Halo4FloatingTransform out{};
            out.scale = input.scale;
            std::memcpy(out.rotation, input.rotation, sizeof(out.rotation));
            std::memcpy(out.translation, input.translation, sizeof(out.translation));
            return out;
        };
        Halo4FloatingTransform palette[kReachFpMaxSourceNodeCount];
        for (int i = 0; i < fp.count; ++i) palette[i] = value(g_fpPaletteScratch[i]);
        if (!RouteLeftHandedFloatingPalette(palette, size_t(fp.count),
                fp.wrist, fp.wristDescendants, fp.lWrist, fp.lWristDescendants,
                value(root), palms.right, palms.left))
            return false;
        for (int i = 0; i < fp.count; ++i)
        {
            g_fpPaletteScratch[i].scale = palette[i].scale;
            std::memcpy(g_fpPaletteScratch[i].rotation, palette[i].rotation, sizeof(palette[i].rotation));
            std::memcpy(g_fpPaletteScratch[i].translation, palette[i].translation, sizeof(palette[i].translation));
        }
        return true;
    }

    void ReachCaptureFpInterpolation(
        int view, int id, int slot, bool result,
        BoneMatrix** outBones, int* outCount, uint32_t muzzleUnit, uint32_t muzzleWeapon)
    {
        if (slot!=0 || g_reachNestedOuterSuppressed || !result ||
            !outBones || !outCount || !*outBones ||
            !g_reachFpPairScope.armed ||
            g_reachFpPairScope.generation!=g_reachCamera.generation ||
            !g_reachCamera.armed.load(std::memory_order_acquire) ||
            !g_enabled.load(std::memory_order_relaxed) ||
            !g_vrAim.load(std::memory_order_relaxed)) return;
        const int count=*outCount;
        if (count<=0 || count>static_cast<int>(kReachFpMaxSourceNodeCount))
            return;

        // Retail pairs each interpolation with its palette immediately. Retain
        // one bounded context per outstanding transaction and let the palette
        // consume the newest exact source-pointer match, as H3/ODST do.
        ReachFpInterpolationContext* destination=nullptr;
        for (auto& candidate : g_reachFpInterpolations)
            if (!candidate.valid)
            {
                destination=&candidate;
                break;
            }
        if (!destination)
            return;
        *destination={};
        ReachFpInterpolationContext& context=*destination;
        context.valid=true;
        context.generation=g_reachFpPairScope.generation;
        context.preparedSerial=g_reachFpPairScope.preparedSerial;
        context.captureSerial=++g_reachFpCaptureSerial;
        context.source=*outBones;
        context.liveSourceCount=count;
        context.interpolationView=view;
        context.interpolationId=id;
        context.interpolationSlot=slot;
        uint32_t currentUnit=UINT32_MAX,currentWeapon=UINT32_MAX;
        if (ReachCaptureMuzzleOwner(view,slot,currentUnit,currentWeapon) &&
            muzzleUnit==currentUnit && muzzleWeapon==currentWeapon)
        { context.muzzleUnit=muzzleUnit;context.muzzleWeapon=muzzleWeapon; }
        currentUnit=currentWeapon=UINT32_MAX;
        if (ReachCaptureGripOwner(view,slot,currentUnit,currentWeapon))
        { context.gripUnit=currentUnit;context.gripWeapon=currentWeapon; }

        const ReachFpLayoutCacheEntry* frozen=
            ReachFindFrozenLayout(count,view,id,slot);
        if (!frozen) return;
        context.layout=frozen->layout;
        context.bodyTag=frozen->bodyTag;
        if (!context.layout.Valid() ||
            !g_reachFpPairScope.targets.centerRootValid ||
            !g_reachFpPairScope.targets.rightWristValid ||
            !ReachBoneMatrixFinite(g_reachFpPairScope.targets.centerRoot) ||
            !ReachBoneMatrixFinite(g_reachFpPairScope.targets.rightWrist) ||
            !isfinite(g_reachFpPairScope.targets.rightScale) ||
            g_reachFpPairScope.targets.rightScale<=0.0f ||
            (g_reachFpPairScope.targets.leftWristValid &&
             (!ReachBoneMatrixFinite(g_reachFpPairScope.targets.leftWrist) ||
              !isfinite(g_reachFpPairScope.targets.leftScale) ||
              g_reachFpPairScope.targets.leftScale<=0.0f))) return;
        const size_t liveBytes=static_cast<size_t>(count)*sizeof(BoneMatrix);
        if (!SafeReadBytes(context.source,context.untouchedLive,liveBytes))
            return;
        for (int node=0;node<count;++node)
            if (!ReachBoneMatrixFinite(context.untouchedLive[node]))
                return;
        context.targets=g_reachFpPairScope.targets;
        // Persistent support grip: the pair's frozen owner trust travels with
        // this invocation's targets, so the palette below presents the same
        // decision the FP hook just resolved. A resolved pair that is NOT the
        // relationship owner re-seats the visible weapon hand on the ordinary
        // calibrated one-hand target (B2 stale-owner fallback); an unresolved
        // pair (feature off) leaves the targets byte-identical to the base.
        context.targets.supportGripResolved=
            g_reachFpPairScope.supportGripResolved;
        context.targets.supportGripAttached=
            g_reachFpPairScope.supportGripAttached;
        if (g_reachFpPairScope.supportGripResolved &&
            !g_reachFpPairScope.supportGripAttached &&
            context.targets.rightOneHandWristValid)
        {
            context.targets.rightWrist=context.targets.rightOneHandWrist;
            context.targets.aimNeutral=context.targets.oneHandAimNeutral;
            context.targets.aimVisual=context.targets.oneHandAimVisual;
            context.targets.rightScale=context.targets.rightOneHandScale;
        }

        // Match the accepted H3/ODST split exactly: the live interpolation bank
        // is only for marker/muzzle/attachment consumers and receives one rigid
        // controller transform. Every visible palette below is reconstructed
        // independently from untouchedLive into private scratch.
        // Prepared wrists are already absolute world targets (pre-head gameplay
        // base + tracked controller displacement). Match H3/ODST by using the
        // center root only for world/record conversion; adding its head
        // translation again would make the assembly drift on a physical turn.
        FpExplicitPoseTargets markerTargets=context.targets;
        BoneMatrix alignedRight{};
        if (!ReachAlignRightTargetToAuthoredBarrel(
                markerTargets.rightWrist,
                context.untouchedLive[context.layout.rightWristSource],
                alignedRight)) return;
        if (!ApplyControllerToMarkerBonesWithTarget(
                markerTargets.centerRoot,alignedRight,markerTargets.rightScale,
                context.source,count,context.layout.rightWristSource))
        {
            SafeWriteBytes(context.source,context.untouchedLive,liveBytes);
            return;
        }
        for (int node=0;node<count;++node)
        {
            BoneMatrix checked{};
            if (!SafeReadBytes(context.source+node,&checked,sizeof(checked)) ||
                !ReachBoneMatrixFinite(checked))
            {
                SafeWriteBytes(context.source,context.untouchedLive,liveBytes);
                return;
            }
        }
        context.transformed=true;
    }
    // ---- Weapon-order diagnostic tranche (read-only evidence) ----
    void PublishReachFpDiagnostic(WeaponOrderEventKind kind,
        WeaponOrderEventStatus status, uint64_t preparedSerial, uint32_t unit,
        uint32_t weapon, uint64_t aux0, uint64_t aux1) noexcept
    {
        if (!Telemetry_WeaponEventsAccepting())
            return;
        Telemetry_PublishWeaponEvent(static_cast<uint8_t>(kind),
            static_cast<uint8_t>(status),
            static_cast<uint8_t>(GameTitle::HaloReach),
            g_reachCamera.generation.load(std::memory_order_acquire),
            preparedSerial, unit, weapon, aux0, aux1);
    }

    __declspec(noinline) bool __fastcall ReachFpInterpolate(
        int view, int id, int slot, BoneMatrix** outBones, int* outCount)
    {
        g_reachCamera.activeCallbacks.fetch_add(1,std::memory_order_acq_rel);
        // Diagnostic-only FP entry + ungated before-read (no gameplay effect).
        uint32_t diagnosticBeforeUnit = UINT32_MAX;
        uint32_t diagnosticBeforeWeapon = UINT32_MAX;
        uint32_t diagnosticBeforeDetail = 0;
        const bool diagnosticArmed =
            Telemetry_WeaponEventsAccepting() && slot == 0 && view == 0;
        if (diagnosticArmed)
        {
            Game_DiagnosticNoteFpThread(GameTitle::HaloReach);
            PublishReachFpDiagnostic(WeaponOrderEventKind::FpEntry,
                WeaponOrderEventStatus::NoObservation,
                g_reachFpPairScope.preparedSerial,
                UINT32_MAX, UINT32_MAX, uint64_t(slot), uint64_t(view));
            uint32_t probeUnit = UINT32_MAX, probeWeapon = UINT32_MAX;
            uint32_t probeDetail = 0;
            if (Game_DiagnosticReadPrimaryWeapon(GameTitle::HaloReach,
                    probeUnit, probeWeapon, probeDetail))
            {
                diagnosticBeforeUnit = probeUnit;
                diagnosticBeforeWeapon = probeWeapon;
                diagnosticBeforeDetail = probeDetail;
            }
        }
        // Persistent support grip production evidence (root slot-0 invocation
        // of the stereo pair only: whichever slot-0 view interpolates first
        // resolves, the other eye reuses the pair's frozen decision, and a
        // later invocation of the same pair must not overwrite it). The
        // before-read is taken here; the after-read lands IMMEDIATELY after the
        // native original and BEFORE ReachCaptureFpInterpolation copies the
        // support-dependent targets into the per-invocation context (A015 §16
        // ordering). Read-only with respect to the durable relationship; PG
        // off: no read, no publication, no receipt.
        const bool supportRootInvocation = g_config.persistent_support_grip &&
            slot == 0 && g_reachFpPairScope.armed &&
            !g_reachFpPairScope.supportGripResolved;
        PrimaryWeaponEvidence supportBefore{};
        const bool supportBeforeOk = supportRootInvocation &&
            Game_ReadPrimaryWeaponEvidence(GameTitle::HaloReach, supportBefore);
        bool result=false;
        uint32_t muzzleUnit=UINT32_MAX,muzzleWeapon=UINT32_MAX;
        (void)ReachCaptureMuzzleOwner(view,slot,muzzleUnit,muzzleWeapon);
        __try
        {
            ReachFpInterpolateFn original=g_reachOrigFpInterpolate;
            if (original)
                result=original(view,id,slot,outBones,outCount);
            if (result && slot==0)
                g_reachFirstPersonPrevMs.store(
                    g_reachFirstPersonMs.exchange(GetTickCount64(),std::memory_order_acq_rel),
                    std::memory_order_release);
            if (supportRootInvocation)
            {
                PrimaryWeaponEvidence supportAfter{};
                const bool supportAfterOk =
                    Game_ReadPrimaryWeaponEvidence(GameTitle::HaloReach,
                        supportAfter);
                const SupportInvocationResolution resolution =
                    Game_ResolveSupportInvocation(GameTitle::HaloReach,
                        supportBefore, supportBeforeOk, supportAfter,
                        supportAfterOk, true);
                g_reachFpPairScope.supportGripAttached = resolution.trusted;
                g_reachFpPairScope.supportGripResolved = true;
                // F06/F07: freeze the title-native invocation receipt for this
                // pair so the presented-ray producer and its consumers can
                // require the consuming invocation's own owner proof instead of
                // trusting the latest durable cache.
                support_grip::SupportInvocationReceipt receipt{};
                receipt.resolved = true;
                receipt.title = GameTitle::HaloReach;
                receipt.generation = resolution.generation;
                receipt.serial = g_reachFpPairScope.preparedSerial;
                receipt.evidence = resolution.evidence;
                receipt.producerAgreement = resolution.producerAgreement;
                receipt.owner = resolution.owner;
                receipt.relationshipReadable = resolution.relationshipReadable;
                receipt.relationshipEngaged = resolution.relationshipEngaged;
                receipt.relationshipEpoch = resolution.relationshipEpoch;
                VR_PublishSupportInvocationReceipt(receipt);
            }
            ReachCaptureFpInterpolation(view,id,slot,result,outBones,outCount,muzzleUnit,muzzleWeapon);
        }
        __finally
        {
            g_reachCamera.activeCallbacks.fetch_sub(1,std::memory_order_acq_rel);
        }
        // Diagnostic-only stable commit, mirroring the existing ownership
        // stable point ungated: inventory identity plus engine FP record
        // agreement (bit2) must survive the interpolation unchanged.
        if (diagnosticArmed && result &&
            diagnosticBeforeWeapon != UINT32_MAX &&
            (diagnosticBeforeDetail & 0x4u) != 0)
        {
            uint32_t afterUnit = UINT32_MAX, afterWeapon = UINT32_MAX;
            uint32_t afterDetail = 0;
            if (Game_DiagnosticReadPrimaryWeapon(GameTitle::HaloReach,
                    afterUnit, afterWeapon, afterDetail) &&
                (afterDetail & 0x4u) != 0 &&
                afterUnit == diagnosticBeforeUnit &&
                afterWeapon == diagnosticBeforeWeapon)
                PublishReachFpDiagnostic(WeaponOrderEventKind::FpWeaponCommit,
                    WeaponOrderEventStatus::Success,
                    g_reachFpPairScope.preparedSerial,
                    afterUnit, afterWeapon, uint64_t(slot), afterDetail);
        }
        return result;
    }

    bool ReachRestoreFpLiveGraph(ReachFpInterpolationContext& context)
    {
        if (!context.transformed)
            return true;
        if (!context.source || context.liveSourceCount<=0 ||
            context.liveSourceCount>static_cast<int>(kReachFpMaxSourceNodeCount))
            return false;
        const size_t bytes=static_cast<size_t>(context.liveSourceCount)*
            sizeof(BoneMatrix);
        if (!SafeWriteBytes(context.source,context.untouchedLive,bytes))
            return false;
        context.transformed=false;
        return true;
    }

    bool ReachBuildCenteredNativeFpPalette(
        const BoneMatrix& paletteRoot, const BoneMatrix& centerRoot,
        const BoneMatrix* untouchedSource, int sourceCount,
        const BoneMatrix*& replacement)
    {
        replacement=untouchedSource;
        if (!untouchedSource || sourceCount<=0 ||
            sourceCount>static_cast<int>(kReachFpMaxSourceNodeCount) ||
            !ReachBoneMatrixFinite(paletteRoot) ||
            !ReachBoneMatrixFinite(centerRoot))
        {
            return false;
        }
        BoneMatrix inverseRoot{},centerToPalette{};
        if (!InvertBoneMatrix(paletteRoot,inverseRoot) ||
            !ComposeBoneMatrices(inverseRoot,centerRoot,centerToPalette))
        {
            return false;
        }
        for (int node=0;node<sourceCount;++node)
        {
            if (!ComposeBoneMatrices(
                    centerToPalette,untouchedSource[node],
                    g_fpPaletteScratch[node]) ||
                !ReachBoneMatrixFinite(g_fpPaletteScratch[node]))
            {
                return false;
            }
        }
        replacement=g_fpPaletteScratch;
        return true;
    }

    void ReachProcessFpPalette(
        uint16_t tag, const BoneMatrix* root, BoneMatrix* destination,
        uintptr_t unused, const BoneMatrix* source, const int32_t* boneMap)
    {
        ReachFpPaletteFn original=g_reachOrigFpPalette;
        (void)LegacyObserveWeaponRenderModel(
            GameTitle::HaloReach,tag,
            g_reachCamera.generation.load(std::memory_order_acquire),source,boneMap);
        // R-V27: one relaxed increment when a seat is occupied. Reach builds
        // the occupant's first-person arms and weapon through this exact
        // transaction, so a non-zero count while seated means the engine did
        // build them and any remaining fault is ours (placement or collapse);
        // a zero count means it never built them at all.
        if (g_reachVehicleTrimSnapshot.load(std::memory_order_relaxed) != 0)
        {
            g_reachSeatedFpPaletteCalls.fetch_add(
                1, std::memory_order_relaxed);
        }
        if (g_reachNestedOuterSuppressed)
        {
            if (original)
                original(tag,root,destination,unused,source,boneMap);
            return;
        }

        // Match and consume the newest outstanding interpolation transaction by
        // exact source pointer. This is the same final-palette ownership model
        // used by Halo 3 and ODST; no render-model palette is admitted by guess.
        ReachFpInterpolationContext* matched=nullptr;
        for (auto& candidate : g_reachFpInterpolations)
        {
            const bool current=candidate.valid && source &&
                candidate.source==source && g_reachFpPairScope.armed &&
                candidate.generation==g_reachCamera.generation &&
                candidate.generation==g_reachFpPairScope.generation &&
                candidate.preparedSerial==g_reachFpPairScope.preparedSerial;
            if (current && (!matched ||
                            candidate.captureSerial>matched->captureSerial))
                matched=&candidate;
        }
        ReachFpInterpolationContext context{};
        const bool contextCurrent=matched!=nullptr;
        if (matched)
        {
            context=*matched;
            matched->valid=false;
        }
        const BoneMatrix* selectedSource=source;

        int paletteCount=0;
        uint32_t bodyChecksum=0;
        int32_t mapCopy[kReachFpMaxSourceNodeCount]{};
        ReachFpBodyLayout observed{};
        bool bodyLayout=false;
        const bool paletteCountResolved=contextCurrent &&
            ReachReadRenderModelIdentity(tag,bodyChecksum,paletteCount);
        if (paletteCountResolved)
            ReachObserveFpLegPalette(tag,paletteCount);
        if (paletteCountResolved && boneMap &&
            (paletteCount==static_cast<int>(kReachSpartanFpBodyNodeCount) ||
             paletteCount==static_cast<int>(kReachEliteFpBodyNodeCount)) &&
            SafeReadBytes(boneMap,mapCopy,
                static_cast<size_t>(paletteCount)*sizeof(int32_t)))
        {
            bodyLayout=ResolveReachFpBodyLayout(
                std::span<const int32_t>{mapCopy,
                    static_cast<size_t>(paletteCount)},
                static_cast<size_t>(context.liveSourceCount),observed,bodyChecksum);
        }
        if (contextCurrent && !bodyLayout &&
            (paletteCount==static_cast<int>(kReachSpartanFpBodyNodeCount) ||
             paletteCount==static_cast<int>(kReachEliteFpBodyNodeCount)))
            PublishReachFpStatus(4,paletteCount,context.liveSourceCount);
        const bool frozenLayoutValid=context.layout.Valid();
        const bool exactBodyMatchesFrozen=bodyLayout && frozenLayoutValid &&
            tag==context.bodyTag && ReachLayoutsEqual(context.layout,observed);
        const ReachFpPaletteAction action=DecideReachFpPaletteAction(
            contextCurrent,frozenLayoutValid,context.transformed,bodyLayout,
            exactBodyMatchesFrozen,tag==context.bodyTag);
        const ReachFpLegPaletteKind frozenLegKind=
            g_reachFpPairScope.legPaletteValid
                ? g_reachFpPairScope.legPaletteKind
                : ReachFpLegPaletteKind::None;
        const bool exactSeatedLegPalette=
            paletteCountResolved &&
            ReachFpLegNodeCountMatchesKind(frozenLegKind,paletteCount) &&
            !ReachFpShouldCollapseVisiblePalette(
                g_reachFpPairScope.showSeatedLegs,frozenLegKind,
                g_reachFpPairScope.legPaletteTag,tag);
        auto restoreStockAndInvalidate=[&](bool relearnExactBody) {
            if (context.transformed)
            {
                selectedSource=context.untouchedLive;
                ReachRestoreFpLiveGraph(context);
            }
            ReachInvalidateLayoutNextPair(context);
            if (relearnExactBody)
                ReachLearnLayout(context,tag,observed);
        };

        if (action==ReachFpPaletteAction::LearnStockOnly)
        {
            ReachLearnLayout(context,tag,observed);
        }
        else if (action==ReachFpPaletteAction::RestoreStockAndInvalidate)
        {
            restoreStockAndInvalidate(bodyLayout);
        }
        else if (action==ReachFpPaletteAction::ArticulateKnownTransaction)
        {
            if (exactSeatedLegPalette)
            {
                selectedSource=context.untouchedLive;
                BoneMatrix centerRoot=context.targets.centerRoot;
                if (root)
                    centerRoot.scale=root->scale;
                const bool nativeBodyReady=root &&
                    context.targets.centerRootValid &&
                    ReachBuildCenteredNativeFpPalette(
                        *root,centerRoot,context.untouchedLive,
                        context.liveSourceCount,selectedSource);
                if (!nativeBodyReady)
                {
                    // This is a leg-presentation failure, not evidence that the
                    // proven 47/41 arms layout changed. Pass this exact body
                    // palette its untouched stock source and leave the
                    // controller-owned live marker graph alone. Invalidating
                    // the shared layout here would take working floating hands
                    // down with an optional native-body conversion failure.
                    selectedSource=context.untouchedLive;
                    g_reachFpLegPaletteBuildFailures.fetch_add(
                        1,std::memory_order_relaxed);
                }
                else
                {
                    g_reachFpLegPalettePreserved.fetch_add(
                        1,std::memory_order_relaxed);
                    PublishReachFpStatus(
                        2,static_cast<int>(
                            context.layout.paletteBodyNodeCount),
                        context.liveSourceCount);
                }
            }
            else if (!root || !context.targets.rightWristValid ||
                context.liveSourceCount<=0 ||
                context.liveSourceCount>
                    static_cast<int>(kReachFpMaxSourceNodeCount) ||
                !ReachBoneMatrixFinite(*root))
            {
                restoreStockAndInvalidate(false);
            }
            else
            {
                FpInterpolationContext fp{};
                fp.source=source;
                fp.count=context.liveSourceCount;
                fp.player=context.interpolationView;
                fp.slot=context.interpolationSlot;
                fp.wrist=context.layout.rightWristSource;
                fp.cameraControl=context.layout.cameraControlSource;
                fp.elbow=context.layout.rightElbowSource;
                fp.shoulder=context.layout.rightShoulderSource;
                fp.wristDescendants=
                    context.layout.rightHandSourceDescendants;
                fp.heldObjectStart=static_cast<int>(
                    context.layout.paletteBodyNodeCount);
                // This palette's native model supplies the held outputs. The
                // body palette owns no weapon outputs; unrendered graph extras
                // must not become guns merely because the Elite lacks them.
                fp.heldSources.explicitMap=true;
                if (!exactBodyMatchesFrozen &&
                    (!paletteCountResolved || !boneMap ||
                     !SafeReadBytes(boneMap,mapCopy,
                         static_cast<size_t>(paletteCount)*sizeof(int32_t)) ||
                     !ResolveReachFpHeldSources(context.layout,
                         std::span<const int32_t>{mapCopy,
                             static_cast<size_t>(paletteCount)},fp.heldSources)))
                {
                    // Refuse only this unrelated/malformed model. A valid
                    // arms layout must survive an optional palette failure.
                    selectedSource=context.untouchedLive;
                    PublishReachFpStatus(4,paletteCount,context.liveSourceCount);
                    if (original)
                        original(tag,root,destination,unused,selectedSource,boneMap);
                    return;
                }
                fp.lWrist=context.layout.leftWristSource;
                fp.lElbow=context.layout.leftElbowSource;
                fp.lShoulder=context.layout.leftShoulderSource;
                fp.lWristDescendants=
                    context.layout.leftHandSourceDescendants;
                fp.valid=true;
                fp.generation=context.generation;
                fp.muzzleUnit=context.muzzleUnit;fp.muzzleWeapon=context.muzzleWeapon;
                fp.gripUnit=context.gripUnit;fp.gripWeapon=context.gripWeapon;
                selectedSource=context.untouchedLive;
                const BoneMatrix* replacement=selectedSource;
                FpExplicitPoseTargets targets=context.targets;
                targets.centerRoot.scale=root->scale;
                BoneMatrix alignedRight{};
                if (!ReachAlignRightTargetToAuthoredBarrel(
                        targets.rightWrist,
                        context.untouchedLive[
                            context.layout.rightWristSource],
                        alignedRight))
                {
                    restoreStockAndInvalidate(false);
                    if (original)
                        original(tag,root,destination,unused,
                                 selectedSource,boneMap);
                    return;
                }
                targets.rightWrist=alignedRight;
                // Publish the pair the effect system needs. `stock` is where
                // the engine still believes the weapon is - the player's body -
                // and `alignedRight` is where the player actually sees it. The
                // muzzle flash resolves against the former; re-parenting it
                // between the two puts it on the gun with no offset.
                // MUST be centerRoot, not untouchedLive[rightWristSource].
                // The live-graph bone is in the first-person skeleton's LOCAL
                // space; effect matrices are in world space. Comparing them put
                // the nearest approach at 75,842 mm (7478cb7 probe) - not a
                // near miss, two different coordinate systems. centerRoot and
                // alignedRight are both absolute world poses supplied by the
                // Reach adapter, so distances between them and an effect matrix
                // are meaningful. centerRoot sits at the player's head, which
                // is exactly where the stuck flash renders.
                if (context.targets.centerRootValid)
                {
                    ReachPublishWeaponAnchor(
                        context.targets.centerRoot, alignedRight,
                        g_reachCamera.generation);
                }
                if (ReachBoneMatrixFinite(alignedRight))
                {
                    g_reachWeaponAnchorMoved = alignedRight;
                    g_reachWeaponAnchorPending = true;
                }
                bool armsSolved=false;
                const bool reconstructed=ReconstructVisiblePaletteSource(
                    tag,fp,*root,source,replacement,&targets,
                    context.untouchedLive,&armsSolved);
                selectedSource=replacement;
                bool leftHandBound=reconstructed &&
                    selectedSource==g_fpPaletteScratch;
                // Persistent support grip (A017 §11): for a RESOLVED pair the
                // visible support attachment follows the frozen relationship
                // trust, never the aim-authority flag: a trusted same-owner
                // invocation keeps the support hand attached even when aim
                // authority is off, and an owner-untrusted invocation never
                // inherits it. With the feature off the pair is unresolved and
                // `twoHandAimActive` remains the only input (PG-off parity).
                const bool supportGripAttached=targets.supportGripResolved
                    ? targets.supportGripAttached : targets.twoHandAimActive;
                if (leftHandBound &&
                    ReachShouldBindVisibleLeftHandToController(
                        supportGripAttached))
                {
                    leftHandBound=ReachBindFloatingLeftHandToController(
                        *root,fp,
                        context.layout.leftControllerOwnedSourceBranch,
                        targets);
                }
                bool anatomicalLeftHanded = false;
                if (reconstructed && leftHandBound && targets.handAlignment)
                {
                    anatomicalLeftHanded = ReachRouteLeftHandedPalette(tag, boneMap, fp, *root, context.targets);
                    (anatomicalLeftHanded ? g_reachAnatomicalApplications : g_reachAnatomicalRefusals)
                        .fetch_add(1, std::memory_order_relaxed);
                }
                bool outputFinite=reconstructed && leftHandBound;
                for (int i=0;outputFinite && i<fp.count;++i)
                    outputFinite=ReachBoneMatrixFinite(g_fpPaletteScratch[i]);
                if (!outputFinite)
                {
                    restoreStockAndInvalidate(false);
                }
                else
                {
                    // Contact buffers name controller roles. Source masks name
                    // anatomy, so publish the same assignment as the palette.
                    FpInterpolationContext contactContext = fp;
                    if (anatomicalLeftHanded)
                    {
                        std::swap(contactContext.wrist, contactContext.lWrist);
                        std::swap(contactContext.wristDescendants, contactContext.lWristDescendants);
                    }
                    LegacyPublishReloadTarget(GameTitle::HaloReach,tag,
                        g_reachCamera.generation.load(std::memory_order_acquire),
                        contactContext,*root,g_fpPaletteScratch,boneMap,&targets);
                    LegacyPublishWorldCollisionVolumes(
                        GameTitle::HaloReach,tag,contactContext,*root,
                        g_fpPaletteScratch,
                        LegacyCollisionIgnoredObject(GameTitle::HaloReach),
                        g_reachCamera.generation.load(
                            std::memory_order_acquire),&targets);
                    // The exact hand/arm masks and held-object boundary come
                    // from the pinned HREK/retail layouts. When visible arms
                    // are requested, ReconstructVisiblePaletteSource has
                    // already solved the verified shoulder/elbow/wrist chains
                    // against this pair's controller targets. Keep unrelated
                    // body nodes hidden here; body_wip owns native body
                    // visibility separately.
                    if (selectedSource==g_fpPaletteScratch)
                    {
                        const uint64_t keep=fp.wristDescendants|
                            fp.lWristDescendants;
                        const bool showTrackedArms=
                            ReachMayShowControllerTrackedArms(
                                !g_config.floating_hands,g_config.arm_ik,
                                supportGripAttached,targets.rightWristValid,
                                targets.leftWristValid,armsSolved);
                        const uint64_t hiddenLeft=
                            context.layout.leftControllerOwnedSourceBranch&
                            ~fp.lWristDescendants;
                        const uint64_t hiddenRight=
                            context.layout.rightControllerOwnedSourceBranch&
                            ~fp.wristDescendants;
                        BoneMatrix collapsedAtLeftWrist=
                            g_fpPaletteScratch[fp.lWrist];
                        collapsedAtLeftWrist.scale=0.0001f;
                        BoneMatrix collapsedAtRightWrist=
                            g_fpPaletteScratch[fp.wrist];
                        collapsedAtRightWrist.scale=0.0001f;
                        for (int i=0;i<fp.count;++i)
                        {
                            const bool hand=i<64 &&
                                (keep&(uint64_t{1}<<i));
                            const bool held=FpSourceIndexIsHeldObject(i,fp.count,
                                fp.heldObjectStart,fp.heldSources);
                            if (!hand && !held)
                            {
                                const bool leftArm=i<64 &&
                                    (hiddenLeft&(uint64_t{1}<<i));
                                const bool rightArm=i<64 &&
                                    (hiddenRight&(uint64_t{1}<<i));
                                const auto action=ReachFpPaletteVisibility(
                                    hand,held,showTrackedArms,leftArm,rightArm);
                                if (action==ReachFpVisibilityAction::Keep)
                                    continue;
                                if (action==ReachFpVisibilityAction::CollapseAtLeftWrist)
                                {
                                    g_fpPaletteScratch[i]=
                                        collapsedAtLeftWrist;
                                }
                                else if (action==ReachFpVisibilityAction::CollapseAtRightWrist)
                                {
                                    g_fpPaletteScratch[i]=
                                        collapsedAtRightWrist;
                                }
                                else
                                {
                                    g_fpPaletteScratch[i].scale=0.0001f;
                                }
                            }
                        }
                    }
                    PublishReachFpStatus(
                        2,static_cast<int>(
                            context.layout.paletteBodyNodeCount),
                        context.liveSourceCount);
                }
            }
        }
        if (original)
            original(tag,root,destination,unused,selectedSource,boneMap);

        if (original && selectedSource==g_fpPaletteScratch && !bodyLayout &&
            action==ReachFpPaletteAction::ArticulateKnownTransaction && !g_reachNestedOuterSuppressed)
            ReachPublishMuzzlePalette(tag,context,destination);

        if (original && selectedSource==g_fpPaletteScratch && exactBodyMatchesFrozen &&
            action==ReachFpPaletteAction::ArticulateKnownTransaction)
            ReachApplyVisualHandOffsets(tag,boneMap,context,destination);

        if (original && selectedSource==g_fpPaletteScratch && !bodyLayout &&
            action==ReachFpPaletteAction::ArticulateKnownTransaction &&
            !g_reachNestedOuterSuppressed)
            ReachApplyFreeSupportFingerPose(tag,paletteCount,context,destination);

        // Candidate 511eb0b put alignedRight here after the visible palette had
        // already been composed. alignedRight is an absolute world pose; the
        // live interpolation records are local to the first-person root. The
        // same source file had already measured those as different coordinate
        // spaces, but the candidate nevertheless copied the world matrix into
        // one local record. It was ineffective for the muzzle flash and was
        // superseded by b942078's accepted loaded-tag retarget, yet the bad
        // write remained active. Do not let a later render consumer observe
        // that internally inconsistent skeleton. The coherent rigid local
        // graph transform performed before the palette remains unchanged.
        if (g_reachWeaponAnchorPending &&
            context.layout.rightWristSource >= 0 &&
            context.layout.rightWristSource < context.liveSourceCount &&
            context.source)
        {
            if constexpr (kReachPostPaletteWorldWristWriteEnabled)
            {
                SafeWriteBytes(
                    const_cast<BoneMatrix*>(context.source) +
                        context.layout.rightWristSource,
                    &g_reachWeaponAnchorMoved, sizeof(BoneMatrix));
                g_reachLiveGraphWeaponWrites.fetch_add(
                    1, std::memory_order_relaxed);
            }
            else
            {
                g_reachWorldWristWritesPrevented.fetch_add(
                    1, std::memory_order_relaxed);
            }
        }
        g_reachWeaponAnchorPending = false;
    }
    __declspec(noinline) void __fastcall ReachFpPalette(
        uint16_t tag, const BoneMatrix* root, BoneMatrix* destination,
        uintptr_t unused, const BoneMatrix* source, const int32_t* boneMap)
    {
        g_reachCamera.activeCallbacks.fetch_add(1,std::memory_order_acq_rel);
        __try
        {
            ReachProcessFpPalette(
                tag,root,destination,unused,source,boneMap);
        }
        __finally
        {
            g_reachCamera.activeCallbacks.fetch_sub(1,std::memory_order_acq_rel);
        }
    }

    unsigned char* ReachVehicleObjectData(int32_t handle, uint8_t& kind)
    {
        kind = 0;
        if (handle == -1)
            return nullptr;
        const int16_t wantedSalt = static_cast<int16_t>(handle >> 16);
        if (!wantedSalt)
            return nullptr;
        auto** slots = reinterpret_cast<void**>(HALOMCCVR_GAME_TLS_ARRAY());
        const auto* tlsIndex = reinterpret_cast<const uint32_t*>(
            g_reachCamera.base + kReachEngineTlsIndexRva);
        if (!slots || !tlsIndex || *tlsIndex >= 0x200)
            return nullptr;
        auto* tls = reinterpret_cast<unsigned char*>(slots[*tlsIndex]);
        auto* collection = tls
            ? *reinterpret_cast<unsigned char**>(
                  tls + kReachTlsObjectCollectionOffset)
            : nullptr;
        if (!collection ||
            !*(collection + kReachDataCollectionInitializedOffset) ||
            *reinterpret_cast<const uint64_t*>(
                collection + kReachDataCollectionStrideOffset) !=
                kReachObjectEntryStride)
        {
            return nullptr;
        }
        const uint32_t index = static_cast<uint16_t>(handle);
        const int32_t count = *reinterpret_cast<const int32_t*>(
            collection + kReachDataCollectionCountOffset);
        auto* entries = *reinterpret_cast<unsigned char**>(
            collection + kReachDataCollectionEntriesOffset);
        if (!entries || count <= 0 || count > 0x10000 ||
            index >= static_cast<uint32_t>(count))
        {
            return nullptr;
        }
        auto* entry = entries + static_cast<size_t>(index) *
            kReachObjectEntryStride;
        const int16_t liveSalt = *reinterpret_cast<const int16_t*>(
            entry + kReachObjectEntrySaltOffset);
        if (!liveSalt || liveSalt != wantedSalt)
            return nullptr;
        kind = *(entry + kReachObjectEntryKindOffset);
        return *reinterpret_cast<unsigned char**>(
            entry + kReachObjectEntryDataOffset);
    }

    // SHOTS FROM THE MUZZLE, seated: true -- and counted as "held off" -- while the seat
    // points the gun away from the converged point by a natural cause (Game_SeatMuzzleRefusal), so the title's
    // barrel-shot transaction refuses the redirect and the shot leaves as the game fires it. Defensive: no
    // seated muzzle palette is known to publish. It never touches the claim, the reticle or the write.
    bool SeatMuzzleShotHeld(GameTitle title)
    {
        if (Game_SeatMuzzleRefusal(title) == converge::SeatMuzzleRefusal::None)
            return false;
        Sight_NoteMuzzleShotHeld(title);
        return true;
    }

