        std::atomic<float> vrikPedestalScale{0.0f};
        std::atomic<float> vrikPedestalTilt{0.0f};
        std::atomic<float> vrikShoulderSpan{0.0f};
        std::atomic<float> vrikTargetMiss{0.0f};
