    int Halo4SafeRead(const void* source, void* destination, size_t bytes);
    int Halo4SafeWrite(void* destination, const void* source, size_t bytes);

    bool Halo4FindUniquePinned(
        uintptr_t base, size_t size, const char* pattern, uint32_t rva,
        uintptr_t& result)
    {
        result = sig::Find(base, size, pattern);
        return result && result - base == rva &&
            !sig::Find(result + 1, base + size - result - 1, pattern);
    }

    bool Halo4WriteExecutable(
        void* destination, const void* expected, const void* replacement,
        size_t bytes)
    {
        if (!destination || !expected || !replacement || !bytes)
            return false;
        std::vector<uint8_t> current(bytes);
        if (!Halo4SafeRead(destination, current.data(), bytes) ||
            std::memcmp(current.data(), expected, bytes) != 0)
            return false;
        DWORD previous = 0;
        if (!VirtualProtect(
                destination, bytes, PAGE_EXECUTE_READWRITE, &previous))
            return false;
        const bool wrote = Halo4SafeWrite(destination, replacement, bytes) != 0;
        DWORD ignored = 0;
        const bool protectedAgain = VirtualProtect(
            destination, bytes, previous, &ignored) != 0;
        FlushInstructionCache(GetCurrentProcess(), destination, bytes);
        return wrote && protectedAgain &&
            Halo4SafeRead(destination, current.data(), bytes) &&
            std::memcmp(current.data(), replacement, bytes) == 0;
    }

    template<size_t N>
    bool Halo4PatchMatches(
        uintptr_t address, const std::array<uint8_t, N>& bytes)
    {
        std::array<uint8_t, N> current{};
        return Halo4SafeRead(
                   reinterpret_cast<const void*>(address), current.data(), N) &&
            current == bytes;
    }

    template<size_t N>
    bool Halo4RestoreOwnedPatch(
        uintptr_t address, const std::array<uint8_t, N>& owned,
        const std::array<uint8_t, N>& stock)
    {
        std::array<uint8_t, N> current{};
        if (!Halo4SafeRead(
                reinterpret_cast<const void*>(address), current.data(), N))
            return false;
        if (current == stock)
            return true;
        if (current != owned)
            return false;
        return Halo4WriteExecutable(
            reinterpret_cast<void*>(address), owned.data(), stock.data(), N);
    }

    uint32_t Halo4RetainedRuntimeGeneration()
    {
        // Cross-title pending ownership is keyed to the installed camera-core
        // generation, never raw DLL residency. This slot was accidentally
        // omitted when the C-H4-3 camera core became permanent, leaving H4 as
        // the only supported VR title that the shared handoff manager could
        // not retain or retire by generation.
        return g_halo4Camera.generation.load(std::memory_order_acquire);
    }

    // ~1 second at 120 Hz, two eyes per frame. Long enough that a few frames
    // of start-up discovery are never mistaken for a failure.
    constexpr uint32_t kHalo4UncapturedEyeLimit = 240;

    // C-H4-8: 1% of headroom on the solved cover. Float rounding through
    // atan/tan and the engine's own projection build can leave the cover a hair
    // under the native frustum, and being one ulp short trips vr.cpp's
    // whole-slice fallback - the exact failure this candidate exists to remove.
    // The cost is ~1% of raster area; the alternative is an intermittent,
    // frame-dependent geometry fault.
    constexpr float kHalo4CoverMargin = 1.01f;

    // C-H4-9. The single predicate that decides who owns Halo 4's look pitch.
    // The render camera, the XInput hook and the closed loop all sample this
    // one function, so there is no state in which the view has taken pitch and
    // the stick has not, or the loop steers while the view still adds.
    //
    // F2 (g_enabled) is a real off switch: turning it off returns every part of
    // this to C-H4-8's behaviour rather than leaving a half-owned camera.
    bool Halo4LookPitchOwned()
    {
        return TitleAdapter_GetActiveTitle() == GameTitle::Halo4 &&
            g_halo4Camera.armed.load(std::memory_order_acquire) &&
            !g_halo4Camera.sceneTargetMissing.load(std::memory_order_acquire) &&
            g_enabled.load(std::memory_order_acquire) &&
            VR_IsStereoEnabled();
    }

    // ---- C-H4-11: first-person hands -----------------------------------
    // Resolved once per install from the signature-verified anchor, never a
    // bare address.
    uint32_t* g_halo4EngineTlsIndex = nullptr;
    int Halo4SafeRead(const void* source, void* destination, size_t bytes);
    int Halo4SafeWrite(void* destination, const void* source, size_t bytes);

    struct Halo4FirstPersonAccess
    {
        unsigned char* record = nullptr;   // fp_weapons[user]
        unsigned char* nodes[kHalo4FirstPersonMaxWeapons]{};
        int32_t nodeCount[kHalo4FirstPersonMaxWeapons]{0, 0};
        int weapons = 0;
    };

    // Every dereference on this path is proven before it is taken. E-H4-11
    // showed the engine itself indexing fp_weapons[user] with the block
    // pointer NULL - that crash IS this chain, so a missing link here must
    // return false, never fault. SEH covers the reads that a torn teardown
    // could invalidate between the check and the load.
    bool Halo4ResolveFirstPerson(int user, Halo4FirstPersonAccess& out)
    {
        out = Halo4FirstPersonAccess{};
        if (!g_halo4EngineTlsIndex || user < 0 ||
            user >= static_cast<int>(kHalo4FirstPersonMaxUsers))
        {
            return false;
        }
        __try
        {
            const uint32_t slot = *g_halo4EngineTlsIndex;
            // The engine's own index must be a plausible TLS slot; a torn or
            // pre-init read here is exactly how a wild pointer gets built.
            if (slot >= 1088)
                return false;
            auto** slots = reinterpret_cast<unsigned char**>(
                HALOMCCVR_GAME_TLS_ARRAY());
            if (!slots)
                return false;
            unsigned char* tls = slots[slot];
            if (!tls)
                return false;
            auto* weapons = *reinterpret_cast<unsigned char**>(
                tls + kHalo4TlsFirstPersonWeaponsOffset);
            auto* orientations = *reinterpret_cast<unsigned char**>(
                tls + kHalo4TlsFirstPersonOrientationsOffset);
            if (!weapons || !orientations)
                return false; // the E-H4-11 state: blocks not present

            unsigned char* record =
                weapons + static_cast<size_t>(user) *
                    kHalo4FirstPersonWeaponsUserStride;
            const uint32_t flags = *reinterpret_cast<uint32_t*>(
                record + kHalo4FirstPersonRecordFlagsOffset);
            // Retail gates the whole node path on this bit before it reads a
            // single matrix (0x3B53A3-0x3B53A9). Honour the same gate.
            if ((flags & kHalo4FirstPersonRecordActiveFlag) == 0)
                return false;
            const int32_t unit = *reinterpret_cast<int32_t*>(
                record + kHalo4FirstPersonRecordUnitOffset);
            if (unit == -1)
                return false;

            out.record = record;
            for (uint32_t weapon = 0; weapon < kHalo4FirstPersonMaxWeapons;
                 ++weapon)
            {
                unsigned char* sub = record +
                    static_cast<size_t>(weapon) * kHalo4FirstPersonWeaponStride;
                // E-H4-17: a COUNT, not an index. A weapon with no composed
                // skeleton reports 0 and must be skipped rather than written.
                const int32_t nodes = *reinterpret_cast<int32_t*>(
                    sub + kHalo4FirstPersonWeaponNodeCountOffset);
                if (nodes <= 0 ||
                    nodes > static_cast<int32_t>(kHalo4FirstPersonMaxNodes))
                {
                    continue;
                }
                const size_t index =
                    weapon + static_cast<size_t>(user) *
                        kHalo4FirstPersonMaxWeapons;
                out.nodes[weapon] = orientations +
                    index * kHalo4FirstPersonOrientationStride +
                    kHalo4FirstPersonNodeArrayOffset;
                out.nodeCount[weapon] = nodes;
                ++out.weapons;
            }
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            out = Halo4FirstPersonAccess{};
            return false;
        }
        return out.weapons > 0;
    }

    // E-H4-21b / C-H4-13.  The final model-skinning consumer receives absolute
    // 0x34-byte matrices.  Work only on a private copy: unlike C-H4-12's
    // animation-producer write this cannot feed our pose back into Halo 4.
    // Sized to the record's fixed bank, which is what actually bounds the copy.
    // One record is processed per detour call, so a single scratch serves both
    // the arms solve and the weapon carry.
    thread_local BoneMatrix g_halo4VrikScratch[kHalo4FirstPersonBankTransforms];
    thread_local BoneMatrix g_halo4ScopeHidden[kHalo4FirstPersonBankTransforms];
    thread_local bool g_halo4ScopeRendering=false,g_halo4ScopePixelsValid=true;
    std::atomic<uint32_t> g_halo4ScopeFaultGeneration{0},g_halo4ScopeFaults{0};
    // Roots published for the Halo 4 first-person path.
    //
    // SUPERSEDED BY E-H4-22 / C-H4-29, and the superseded reasoning is left
    // here because it was wrong in an instructive way. This block used to argue
    // that Halo 4 roots its whole first-person assembly on the render camera,
    // that the record's own node 0 therefore IS that camera, and that anchoring
    // on node 0 would glue the rig to the game camera. Disassembly of the
    // producer 0x3B1B4C shows that is true of the two WEAPON fills only. The
    // BODY fill's root argument is NULL (or, on one gated branch, an
    // identity-basis pure translation), so the arms record never carried a
    // camera to be glued to, and node 0 is simply b_pedestal - the anchor the
    // record actually has.
    //
    // The rule the old text was reaching for still holds and is now enforced in
    // one place: exactly one pose per stereo pair, with the eye entering only
    // at the very end. Halo 3, ODST and Reach all do this, and C-H4-29 does it
    // as a single per-eye translation applied to the finished rig.
    //
    // Sequence-guarded so a reader never sees a half-written matrix, and each
    // serial stays zero until a record has actually solved.
    struct Halo4CenterRoot
    {
        std::atomic<uint32_t> sequence{0};
        std::atomic<float> value[12]{};   // position, forward, left, up
    };
    Halo4CenterRoot g_halo4CenterRoot;
    // The body/aim frame before Halo 4's HMD pose is composed onto the camera.
    // Controller ownership uses this frame, never the post-HMD camera frame.
    Halo4CenterRoot g_halo4ControllerRoot;
    // When the controller root was published (the sight clock, us; inside its sequence): the camera sample the on-foot
    // intent point is built from, which a flat-parity muzzle shot moves with the eye from (PublishAimIntent).
    std::atomic<uint64_t> g_halo4ControllerRootUs{0};
    // What the stereo transaction lifted the VIEW by on top of that frame, straight up (world units), that
    // is not the head: the physical crouch give-back plus the leash below the character's eye. The hands
    // are placed from the controller root, so they rise by it too, or they sink away from the eyes by that
    // much when physical crouch engages. Published with the controller root;
    // the root itself stays the engine's eye, which the sight trace and the scope shoot from.
    std::atomic<float> g_halo4HandsLiftZ{0.0f};
    // Exact active-eye render roots. E-H4-22: the producer composes the two
    // WEAPON records through this camera, so the weapon carry uses it to
    // express a model-frame hand motion in the weapon's own world frame. The
    // body record does not carry it and must not have it removed.
    Halo4CenterRoot g_halo4EyeRoot[2];
    thread_local Halo4VrRenderSnapshot g_halo4RigTracking{};
    thread_local bool g_halo4RigTrackingActive=false;

    void Halo4PublishCenterRoot(const Halo4CameraBasis& center)
    {
        const float left[3] = {
            center.up[1]*center.forward[2]-center.up[2]*center.forward[1],
            center.up[2]*center.forward[0]-center.up[0]*center.forward[2],
            center.up[0]*center.forward[1]-center.up[1]*center.forward[0]};
        const float packed[12] = {
            center.position[0],center.position[1],center.position[2],
            center.forward[0],center.forward[1],center.forward[2],
            left[0],left[1],left[2],
            center.up[0],center.up[1],center.up[2]};
        for (float component : packed)
            if (!isfinite(component)) return;
        g_halo4CenterRoot.sequence.fetch_add(1,std::memory_order_acq_rel);
        for (int i=0;i<12;++i)
            g_halo4CenterRoot.value[i].store(
                packed[i],std::memory_order_relaxed);
        g_halo4CenterRoot.sequence.fetch_add(1,std::memory_order_release);
    }

    void Halo4PublishControllerRoot(const Halo4CameraBasis& center)
    {
        const float left[3] = {
            center.up[1]*center.forward[2]-center.up[2]*center.forward[1],
            center.up[2]*center.forward[0]-center.up[0]*center.forward[2],
            center.up[0]*center.forward[1]-center.up[1]*center.forward[0]};
        const float packed[12] = {
            center.position[0],center.position[1],center.position[2],
            center.forward[0],center.forward[1],center.forward[2],
            left[0],left[1],left[2],center.up[0],center.up[1],center.up[2]};
        for (float component : packed)
            if (!isfinite(component)) return;
        g_halo4ControllerRoot.sequence.fetch_add(1,std::memory_order_acq_rel);
        for (int i=0;i<12;++i)
            g_halo4ControllerRoot.value[i].store(
                packed[i],std::memory_order_relaxed);
        g_halo4ControllerRootUs.store(Sight_NowUs(),std::memory_order_relaxed);
        g_halo4ControllerRoot.sequence.fetch_add(1,std::memory_order_release);
    }

    void Halo4PublishEyeRoot(int eye, const Halo4CameraBasis& camera)
    {
        if (eye<0 || eye>1) return;
        const float left[3] = {
            camera.up[1]*camera.forward[2]-camera.up[2]*camera.forward[1],
            camera.up[2]*camera.forward[0]-camera.up[0]*camera.forward[2],
            camera.up[0]*camera.forward[1]-camera.up[1]*camera.forward[0]};
        const float packed[12] = {
            camera.position[0],camera.position[1],camera.position[2],
            camera.forward[0],camera.forward[1],camera.forward[2],
            left[0],left[1],left[2],camera.up[0],camera.up[1],camera.up[2]};
        for (float component : packed)
            if (!isfinite(component)) return;
        Halo4CenterRoot& destination=g_halo4EyeRoot[eye];
        destination.sequence.fetch_add(1,std::memory_order_acq_rel);
        for (int i=0;i<12;++i)
            destination.value[i].store(packed[i],std::memory_order_relaxed);
        destination.sequence.fetch_add(1,std::memory_order_release);
    }

    // Blam column order is forward / left / up, matching BoneMatrix::rotation.
    bool Halo4LoadCenterRoot(float scale, BoneMatrix& root)
    {
        for (int attempt=0;attempt<4;++attempt)
        {
            const uint32_t before=
                g_halo4CenterRoot.sequence.load(std::memory_order_acquire);
            if (!before || (before&1)) continue;
            float packed[12];
            for (int i=0;i<12;++i)
                packed[i]=g_halo4CenterRoot.value[i].load(
                    std::memory_order_relaxed);
            const uint32_t after=
                g_halo4CenterRoot.sequence.load(std::memory_order_acquire);
            if (before!=after || (after&1)) continue;
            root=BoneMatrix{};
            root.scale=isfinite(scale)&&fabsf(scale)>0.001f ? scale : 1.0f;
            for (int i=0;i<3;++i)
            {
                root.translation[i]=packed[i];
                root.rotation[i]=packed[3+i];      // forward
                root.rotation[3+i]=packed[6+i];    // left
                root.rotation[6+i]=packed[9+i];    // up
            }
            return true;
        }
        return false;
    }

    bool Halo4LoadControllerRoot(float scale, BoneMatrix& root, uint64_t* stampUs=nullptr)
    {
        for (int attempt=0;attempt<4;++attempt)
        {
            const uint32_t before=g_halo4ControllerRoot.sequence.load(
                std::memory_order_acquire);
            if (!before || (before&1)) continue;
            float packed[12];
            for (int i=0;i<12;++i)
                packed[i]=g_halo4ControllerRoot.value[i].load(
                    std::memory_order_relaxed);
            const uint64_t publishedUs=g_halo4ControllerRootUs.load(std::memory_order_relaxed);
            const uint32_t after=g_halo4ControllerRoot.sequence.load(
                std::memory_order_acquire);
            if (before!=after || (after&1)) continue;
            if (stampUs) *stampUs=publishedUs;
            root=BoneMatrix{};
            root.scale=isfinite(scale)&&fabsf(scale)>0.001f ? scale : 1.0f;
            for (int i=0;i<3;++i)
            {
                root.translation[i]=packed[i];
                root.rotation[i]=packed[3+i];
                root.rotation[3+i]=packed[6+i];
                root.rotation[6+i]=packed[9+i];
            }
            return true;
        }
        return false;
    }

    bool Halo4LoadActiveEyeRoot(float scale, BoneMatrix& root)
    {
        const int eye=g_stereoEye.load(std::memory_order_acquire);
        if (eye<0 || eye>1) return false;
        const Halo4CenterRoot& source=g_halo4EyeRoot[eye];
        for (int attempt=0;attempt<4;++attempt)
        {
            const uint32_t before=source.sequence.load(std::memory_order_acquire);
            if (!before || (before&1)) continue;
            float packed[12];
            for (int i=0;i<12;++i)
                packed[i]=source.value[i].load(std::memory_order_relaxed);
            const uint32_t after=source.sequence.load(std::memory_order_acquire);
            if (before!=after || (after&1)) continue;
            root=BoneMatrix{};
            root.scale=isfinite(scale)&&fabsf(scale)>0.001f ? scale : 1.0f;
            for (int i=0;i<3;++i)
            {
                root.translation[i]=packed[i];
                root.rotation[i]=packed[3+i];
                root.rotation[3+i]=packed[6+i];
                root.rotation[6+i]=packed[9+i];
            }
            return true;
        }
        return false;
    }

    // Dormant C-H4-29..34 relation state retained for forensic history. The
    // active C-H4-35 path below neither reads nor publishes it.
    // The weapon records precede the body record in the rejected model. Cache the
    // most recent successful BODY hand in root-local space, never a world
    // delta carrying the previous eye/head root. Each weapon uses its own eye
    // root and current controller pose to build the world delta it needs.
    AtomicBoneMatrix g_halo4StockRightHandLocal;
