    // world transform built from a different eye.
    AtomicBoneMatrix g_halo4RightHandMotion;
    std::atomic<uint64_t> g_halo4RightHandMotionSerial{0};
    std::atomic<uint64_t> g_halo4RightHandMotionPublishedAt{0};
