    constexpr uint32_t kHalo4PhysicsCollectorResultRva = 0x1C15A8;
    constexpr uint32_t kHalo4WorldLineTestRva = 0x0F4218;
    constexpr uint32_t kHalo4WorldLineFilterGlobalRva = 0x2FFB0B8;
