// THE FIRE-TICK EYE, Halo 3 on foot (sight_layer.h Sight_SetFireEyeSource; in every build:
// the dev key shot_point_transport, default 1, is the A/B): the eye the shot leaves from at this fire, from the unit's
// camera evaluator (0x212198) -- the one the game proves to be the engine eye (EyeProof: within 5 cm of the engine
// camera at rest), so E_fire - E_P is motion, not two sources' offset. In order of preference:
//   * the crosshair query's own start (`siteEye`): the firing assist asked that evaluator for it at 0x13BC0D in this
//     very fire;
//   * a muzzle shot (`askEvaluator`; never the witness): the evaluator asked for the local unit NOW, inside the fire
//     routine (0x368651), after the tick has moved the unit -- the same eye the assist would trace from;
//   * this tick's published eye (PublishHalo3TickEye) CARRIED ONE TICK (shot_lag::CarryTickEye), the local unit's and
//     from this tick (shot_lag::FireEyeGate). Uncarried it is the eye BEFORE this tick's move -- the eye the last
//     render showed -- with which the muzzle transport measures 0 mm on every moving shot, while
//     stock flat fires one tick of strafe ahead of the crosshair the player aimed with (shot_lag_logic.h).
// Fire thread; the evaluator call under SEH with the lane's callback count held (RemoveHalo3DualAim's quiescence).
static shot_lag::FireEye Halo3AskEvaluatorEye(uint32_t generation, int32_t unit, float eye[3])
{
    auto& feature = g_halo3Dual;
    feature.callbacks.fetch_add(1, std::memory_order_acq_rel);
    shot_lag::FireEye why = shot_lag::FireEye::NoSource;
    __try
    {
        const Halo3DualCameraFn evaluator = feature.cameraOriginal;
        if (evaluator && feature.enabled.load(std::memory_order_acquire) &&
            !feature.faulted.load(std::memory_order_acquire) && generation && feature.generation == generation &&
            unit != -1)
        {
            float position[3]{}, direction[3]{};
            const int32_t path = evaluator(static_cast<uint32_t>(unit), position, direction);
            if (!shot_lag::EvaluatorTookFirstPersonPath(path))
                why = shot_lag::FireEye::ChasePath;
            else if (shot_lag::Finite3(position))
            {
                memcpy(eye, position, sizeof(position));
                why = shot_lag::FireEye::Measured;
            }
            else
                why = shot_lag::FireEye::Faulted;
        }
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        why = shot_lag::FireEye::Faulted;
    }
    feature.callbacks.fetch_sub(1, std::memory_order_acq_rel);
    return why;
}
static shot_lag::FireEye Halo3FireEyeForShot(const float* siteEye, bool askEvaluator, const SightPointSample& sample,
                                             float eye[3], float& ageMs)
{
    (void)sample;   // Halo 3 carries its own tick eye (the acquisition's), not the camera sample's
    ageMs = -1.0f;
    const uint32_t generation = TitleAdapter_GetGeneration(GameTitle::Halo3);
    if (!generation || TitleAdapter_GetActiveTitle() != GameTitle::Halo3)
        return shot_lag::FireEye::NoSource;
    if (g_halo3TickEyeProof.load(std::memory_order_relaxed) != static_cast<uint32_t>(TickEyeProof::Proven))
        return shot_lag::FireEye::Unproven;
    if (siteEye && shot_lag::Finite3(siteEye))
    {
        memcpy(eye, siteEye, sizeof(float) * 3);
        ageMs = 0.0f;
        return shot_lag::FireEye::Measured;
    }
    const int32_t local = LegacyCollisionIgnoredObject(GameTitle::Halo3);
    shot_lag::FireEye asked = shot_lag::FireEye::Count;
    if (askEvaluator)
    {
        asked = Halo3AskEvaluatorEye(generation, local, eye);
        if (asked == shot_lag::FireEye::Measured)
        {
            ageMs = 0.0f;
            return asked;
        }
    }
    float tickEye[3]{}, vel[3]{};
    bool velValid = false;
    uint64_t stampUs = 0;
    int32_t unit = -1;
    const bool read = ReadHalo3TickEye(generation, 250000, tickEye, vel, velValid, stampUs, &unit);
    const uint64_t nowUs = Sight_NowUs();
    const uint32_t tickUs = g_legacyTickPeriodUs[0].load(std::memory_order_relaxed);
    const shot_lag::FireEye verdict = shot_lag::FireEyeGate(read, true, unit, local, stampUs, nowUs, tickUs);
    if (verdict != shot_lag::FireEye::Measured)
        return asked != shot_lag::FireEye::Count ? asked : verdict;
    // At rest (no velocity yet) the eye itself is the carried eye.
    (void)shot_lag::CarryTickEye(tickEye, velValid ? vel : nullptr, float(tickUs ? tickUs : 16667) * 1.0e-6f, eye);
    ageMs = float(nowUs - stampUs) / 1000.0f;
    return shot_lag::FireEye::CarriedTick;
}
static const bool g_halo3FireEyeRegistered =
    (Sight_SetFireEyeSource(GameTitle::Halo3, &Halo3FireEyeForShot), true);

// THE FIRE EYE, Halo 4 on foot: halo4_fire_eye.inl (measured: the unit camera position the fire
// itself asks, proven at rest; until proven, E_P carried one measured tick).

// THE INTENT POINT (sight_layer.h SightIntent; shot_lag_logic.h). Input thread, every poll whose converged solve
// resolved: P = H + u * r from ONE frame-coherent pair where the title publishes camera frames (Halo 3, ODST:
// PublishCamFrame), else from the solve's own ray (Halo 4). The hands are kept here, keyed by the head sample of
// the committed aim sample they came from, so a render that used that head sample pairs with its own hand even
// when this poll's hand belongs to a frame not rendered yet. Dev counters say how P was built.
static void PublishAimIntent(GameTitle title, const SightRay& ray, const float handKey[3], uint64_t handSerial,
                             float rangeWu, bool seated, bool railHeld, float solvedYaw, float solvedPitch)
{
    static shot_lag::HandFrame s_hands[8];
    static size_t s_next = 0;
    static GameTitle s_title = GameTitle::None;
    static uint32_t s_generation = 0;
    if (s_title != title || s_generation != ray.generation)
    {
        for (auto& hand : s_hands)
            hand = shot_lag::HandFrame{};
        s_title = title;
        s_generation = ray.generation;
    }
    const uint64_t now = Sight_NowUs();
    const bool keyed = handKey && shot_lag::Finite3(handKey);
    if (keyed)
    {
        shot_lag::HandFrame& hand = s_hands[s_next++ % 8];
        hand.valid = true;
        memcpy(hand.key, handKey, sizeof(hand.key));
        memcpy(hand.dir, ray.dir, sizeof(hand.dir));
        hand.stampUs = now;
        hand.serial = handSerial;
    }
    SightIntent intent{};
    shot_lag::IntentPoint& p = intent.p;
    p.generation = ray.generation;
    p.stampUs = now;   // the poll's own pair; a coherent pair below takes its hand's stamp
    p.railHeld = railHeld;
    p.seated = seated;
    p.rangeWu = rangeWu;
    p.solvedYaw = solvedYaw;
    p.solvedPitch = solvedPitch;
    memcpy(p.head, ray.head, sizeof(p.head));
    memcpy(p.dir, ray.dir, sizeof(p.dir));
    memcpy(p.eye, ray.eye, sizeof(p.eye));
    for (int axis = 0; axis < 3; ++axis)
        intent.solvePoint[axis] = ray.head[axis] + ray.dir[axis] * rangeWu;
    const bool cameraFrames = title == GameTitle::Halo3 || title == GameTitle::Halo3ODST;
    shot_lag::EyeFrame frames[kCamFrameSlots]{};
    const size_t frameCount = cameraFrames ? ReadCamFrames(frames) : 0;
    size_t eyeIndex = 0, handIndex = 0;
    // The solve's eye is the newest render's engine eye (g_baseCam at this poll): stamped with the newest frame, the
    // camera sample a seated point and a pairless point were built from (shot_lag::IntentPoint::pointEye; the dev
    // key shot_point_transport moves P with the eye from there).
    uint64_t newestFrameUs = 0;
    for (size_t i = 0; i < frameCount; ++i)
        if (frames[i].valid && frames[i].stampUs > newestFrameUs)
            newestFrameUs = frames[i].stampUs;
    p.solveEyeStampUs = newestFrameUs;
    if (newestFrameUs)
    {
        p.pointEyeValid = true;
        memcpy(p.pointEye, ray.eye, sizeof(p.pointEye));
        p.pointEyeStampUs = newestFrameUs;
    }
    // A head sample repeated more than 100 ms apart is not the same frame. A hand older than 50 ms (renders stalled:
    // the newest hand whose frame rendered is several polls back) is the aim of that moment, not of now: the poll's
    // own pair stands instead. The point is stamped with the HAND's own stamp, so a consumer ages it from when the
    // player meant it -- never republished as fresh.
    constexpr uint64_t kIntentHandMaxAgeUs = 50000;
    if (keyed && frameCount &&
        shot_lag::SelectCoherentPair(frames, frameCount, s_hands, 8, 100000, eyeIndex, handIndex, now,
                                     kIntentHandMaxAgeUs))
    {
        const shot_lag::EyeFrame& eye = frames[eyeIndex];
        const shot_lag::HandFrame& hand = s_hands[handIndex];
        p.coherent = true;
        p.stampUs = hand.stampUs;
        p.serial = eye.serial;
        memcpy(p.head, eye.head, sizeof(p.head));
        memcpy(p.dir, hand.dir, sizeof(p.dir));
        p.eyeStampUs = eye.stampUs;
        // P's camera sample is this frame's: its engine eye and render time.
        p.pointEyeValid = true;
        memcpy(p.pointEye, eye.eye, sizeof(p.pointEye));
        p.pointEyeStampUs = eye.stampUs;
        Sight_NoteIntentPairing(title, hand.stampUs == now ? 0 : 1);
    }
    else
        Sight_NoteIntentPairing(title, cameraFrames ? 2 : 3);
    for (int axis = 0; axis < 3; ++axis)
        p.point[axis] = p.head[axis] + p.dir[axis] * rangeWu;
    // The engine eye's velocity on the render's own clock (the frames' stamps), else the ray publisher's estimate.
    if (frameCount >= 2)
    {
        // Oldest first (the ring is round robin).
        for (size_t i = 1; i < frameCount; ++i)
            for (size_t j = i; j > 0 && frames[j].stampUs < frames[j - 1].stampUs; --j)
                std::swap(frames[j], frames[j - 1]);
        shot_lag::EyeTrack track;
        for (size_t i = 0; i < frameCount; ++i)
            track.Push(frames[i].stampUs, frames[i].eye);
        p.eyeVelValid = track.Velocity(120000, 30000, p.eyeVel);
        if (!p.eyeStampUs)
            p.eyeStampUs = frames[frameCount - 1].stampUs;
    }
    if (!p.eyeVelValid && ray.eyeVelValid)
    {
        memcpy(p.eyeVel, ray.eyeVel, sizeof(p.eyeVel));
        p.eyeVelValid = true;
    }
    // A title without camera frames (Halo 4): P's camera sample is the solve's own ray -- its engine eye, sampled when
    // the ray's eye was (the controller root's publish; else this poll) -- and its velocity is the one the ray's
    // publish measured on that clock (Sight_PublishRay), read back. Flat parity extrapolates the muzzle shot's point
    // from it (no fire-tick eye source there: Sight_TransportIntent, Transport::Extrapolated).
    if (!cameraFrames && !seated)
    {
        p.pointEyeValid = shot_lag::Finite3(ray.eye);
        memcpy(p.pointEye, ray.eye, sizeof(p.pointEye));
        p.pointEyeStampUs = ray.eyeStampUs && ray.eyeStampUs <= now ? ray.eyeStampUs : now;
        if (!p.eyeStampUs)
            p.eyeStampUs = p.pointEyeStampUs;
        SightRay published{};
        if (!p.eyeVelValid && Sight_ReadRay(title, ray.generation, kSightRayFreshMs, published) &&
            published.eyeVelValid)
        {
            memcpy(p.eyeVel, published.eyeVel, sizeof(p.eyeVel));
            p.eyeVelValid = true;
        }
    }
    Sight_PublishIntent(title, intent);
}

// The local seat's natural holds, as both seated shot paths read them: `held` -- the direct drive held at the seat's
// stop, or the seat's reticle clamped at a natural stop; `turret` -- a rate-capped turret seat (Halo 3, ODST).
static void SeatNaturalHolds(GameTitle title, bool& held, bool& turret)
{
    held = false;
    turret = false;
    switch (title)
    {
    case GameTitle::Halo3:
    case GameTitle::Halo3ODST:
        held = LegacyDriveSeatLimited(title);
        // Critic M3: their muzzle owner checks rely on unit_in_vehicle, which answers false in a stationary
        // turret, so a walk-up turret is the one seat a redirect could reach. Only while that title is active.
        turret = TitleAdapter_GetActiveTitle() == title && OccupiedTurretSeat();
        break;
    case GameTitle::Halo4:
        held = LegacyDriveSeatLimited(title);   // its owner check already refuses a parented unit
        break;
    default:
        break;
    }
    // The seat's reticle is clamped at a natural stop (seat_limit_reticle_logic.h): the converged point is the hand's,
    // past the stop. A redirect through it would carry the shot past the stop the game holds the gun at; refused, the
    // shot leaves along the game's clamped aim, through the clamped mark.
    held = held || Sight_SeatLimitClampedLive(title);
}

converge::SeatMuzzleRefusal Game_SeatMuzzleRefusal(GameTitle title)
{
    bool held = false, turret = false;
    SeatNaturalHolds(title, held, turret);
    return converge::SeatMuzzleRefuses(held, turret);
}

converge::SeatMuzzleRefusal Game_SeatAssistReaimRefusal(GameTitle title)
{
    bool held = false, turret = false;
    SeatNaturalHolds(title, held, turret);
    return converge::SeatAssistReaimRefuses(held, turret);
}

// THE SEAT LIMIT RETICLE, the aim poll's half (src/common/seat_limit_reticle_logic.h).
// Direct drive keeps writing the hand's aim into a seat; the game clamps it at the seat's natural angular stops (a
// passenger's cone, a turret's or a tank gun's pitch stop) and the gun aims along the clamped direction. So the reticle
// sits there: on the clamped direction from the seat's shot origin, at the surface that ray meets (traced by the
// title's sim thread as the seat limit ray), drawn from the rendered eye -- or, for a title with no traced seat
// reticle, the reticle's own direction turned by what the clamp did. Inside the stops, or while the gun only slews
// (a rate cap, catch-up: no stop source sees those), nothing changes. The stops come from the title's sim thread (the
// seat-limit latch, or a record's own eased limits), published after each seat write.
struct SeatLimitPoll
{
    GameTitle title = GameTitle::None;
    bool stopsFresh = false;           // `stops` is a publication from within its freshness window
    seat_limit::Stops stops{};
    uint32_t seatKey = 0;
    float recordYaw = 0.0f;            // the record's yaw with those stops (kept along its up)
    float targetYaw = 0.0f, targetPitch = 0.0f;   // the aim the drive writes, world angles
    // Placed (traced) mark: the rendered centre eye H and the seat's shot origin E, world units.
    bool eyes = false;
    float head[3]{}, shotOrigin[3]{};
    // World -> VR for a placed mark: Halo 4's world angles, or Halo3SeatAimToVrReticle (the vehicle-follow frame).
    bool halo4Map = false, followed = false;
    float hullYaw = 0.0f, hullPitch = 0.0f, gameYawRef = 0.0f, headYawRef = 0.0f;
    float yawSign = -1.0f, pitchSign = 1.0f;
    // Direction-only mark: the reticle's own VR direction, turned by the clamp.
    float controllerVrYaw = 0.0f, controllerVrPitch = 0.0f;
    // A placed mark whose title's world -> VR basis is not this poll's to invert (Reach: its compact camera carries
    // view follow and pitch trim): the eye ray to the clamped point is drawn as the reticle's own direction turned by
    // that ray's yaw / pitch away from the intent ray (`intentDir`, world, the ray the reticle already rides).
    bool intentDelta = false;
    float intentDir[3]{};
    // A Halo 3 gun-slaved seat with its camera's offset fed forward (GunOffsetStep): the target is the RECORD's (the ray
    // minus the offset), so the clamped record's ray is put back by the offset -- that is where the gun's crosshair,
    // and so the shot, really goes at the stop.
    bool gunOffset = false;
    seat_frame::Frame gunOffsetFrame{};
    float gunOffsetYaw = 0.0f, gunOffsetPitch = 0.0f;
    // A Halo 3 look-steered LAND driver's GUN BAND (halo3_vehicle_gun_band.inl, vehicle_gun_band_logic.h): the guns
    // fire from `bandOrigin` along their hull-fixed barrels, and the assist turns a shot toward the crosshair point by
    // at most the cap -- so the shot's elevation relative to the hull's up is held to [bandLo, bandHi]. Its yaw is not
    // (the hull turns toward the hand: catch-up). Needs the eyes: the crosshair point is E along the (record-clamped)
    // aim at `targetRangeWu`, the distance from E to the point the aim was solved through.
    bool band = false;
    seat_frame::Frame bandHull{};
    float bandLo = 0.0f, bandHi = 0.0f;
    float bandOrigin[3]{};
    float targetRangeWu = 0.0f;
};

static seat_limit::Gate g_seatLimitGate;   // input thread only
static GameTitle g_seatLimitGateTitle = GameTitle::None;
static uint64_t g_seatLimitGateMs = 0;

static bool SeatLimitWorldToVr(const SeatLimitPoll& in, const float worldDir[3], float& vrYaw, float& vrPitch)
{
    const float length = std::sqrt(worldDir[0] * worldDir[0] + worldDir[1] * worldDir[1] + worldDir[2] * worldDir[2]);
    if (!std::isfinite(length) || length < 1.0e-6f)
        return false;
    const float n[3]{worldDir[0] / length, worldDir[1] / length, worldDir[2] / length};
    if (in.halo4Map)
    {
        vrYaw = in.headYawRef + in.yawSign * WrapPi(atan2f(n[1], n[0]) - in.gameYawRef);
        vrPitch = in.pitchSign * asinf(Clamp(n[2], -1.0f, 1.0f));
        return std::isfinite(vrYaw) && std::isfinite(vrPitch);
    }
    return Halo3SeatAimToVrReticle(n, in.followed, in.hullYaw, in.hullPitch, in.gameYawRef, in.headYawRef, in.yawSign,
                                   in.pitchSign, vrYaw, vrPitch);
}

// Not in a seat this poll that can clamp (on foot, an air vehicle, an unwritten seat, another title): nothing carries.
static void SeatLimitLeave()
{
    g_seatLimitGate.leave();
    g_seatLimitGateTitle = GameTitle::None;
}

// One seated poll. True when the reticle is clamped this poll (`mark` then holds it).
static bool SeatLimitReticleStep(const SeatLimitPoll& in, SeatLimitMarkPublication& mark)
{
    const uint64_t now = GetTickCount64();
    // Another title, or polls that stopped coming (a pause, a menu): start afresh.
    if (in.title != g_seatLimitGateTitle || !g_seatLimitGateMs || now < g_seatLimitGateMs ||
        now - g_seatLimitGateMs > 200)
        g_seatLimitGate.leave();
    g_seatLimitGateTitle = in.title;
    g_seatLimitGateMs = now;
    seat_limit::Stops use{};
    const bool haveStops = g_seatLimitGate.stops_for(in.stopsFresh, in.stops, in.seatKey, now, use);
    // The record's stops first (none: the target itself, exactly)...
    seat_limit::Result r{};
    const bool clampOk = (haveStops || in.band) &&
        seat_limit::Clamp(haveStops ? use : seat_limit::Stops{}, in.targetYaw, in.targetPitch, in.recordYaw, r);
    // ...then a look-steered driver's GUN BAND, on the shot's own line: from the guns toward the point the (clamped) aim's
    // crosshair reaches. Past the band the shot leaves at its edge, from the guns.
    gun_band::ShotClamp bandShot{};
    bool bandClamped = false;
    if (clampOk && in.band && in.eyes && in.targetRangeWu > 0.0f)
    {
        const float point[3]{in.shotOrigin[0] + r.dir[0] * in.targetRangeWu,
                             in.shotOrigin[1] + r.dir[1] * in.targetRangeWu,
                             in.shotOrigin[2] + r.dir[2] * in.targetRangeWu};
        bandClamped = gun_band::ClampShot(in.bandHull, in.bandLo, in.bandHi, in.bandOrigin, point, bandShot) &&
            bandShot.clamped;
    }
    float overshoot = r.any() ? r.overshootDeg : 0.0f;
    if (bandClamped && bandShot.overshootDeg > overshoot)
        overshoot = bandShot.overshootDeg;
    if (!g_seatLimitGate.decide(clampOk, overshoot) || !(r.any() || bandClamped))
        return false;
    bool placed = false;
    // The ray the gun really aims along at the stop: the clamped aim, put back by a gun camera's fed-forward offset --
    // or, held at a driver's gun band, the shot itself, from the guns.
    float rayDir[3]{r.dir[0], r.dir[1], r.dir[2]};
    const float* rayOrigin = bandClamped ? in.bandOrigin : in.shotOrigin;
    if (bandClamped)
    {
        for (int axis = 0; axis < 3; ++axis)
            rayDir[axis] = bandShot.dir[axis];
    }
    else if (in.gunOffset)
    {
        float y = 0.0f, p = 0.0f;
        if (gun_slaved::ShiftInFrame(in.gunOffsetFrame, r.worldYaw, r.worldPitch, in.gunOffsetYaw, in.gunOffsetPitch, y,
                                     p))
            seat_frame::Forward(y, p, rayDir);
    }
    if (in.eyes)
    {
        // THE SEAT LIMIT RAY: the seat's shot origin along the clamped aim, traced by the title's sim thread beside the
        // intent ray. Until its first trace lands (one ~30 ms interval after a clamp starts), the intent ray's traced
        // point at its distance from E stands in, then the crosshair distance.
        const uint32_t generation = TitleAdapter_GetGeneration(in.title);
        SightAuxRay ray{};
        ray.generation = generation;
        ray.sampleMs = Sight_NowMs();   // the sight clock (`now` above is the gate's GetTickCount64); the publish restamps
        for (int axis = 0; axis < 3; ++axis)
        {
            ray.origin[axis] = rayOrigin[axis];
            ray.dir[axis] = rayDir[axis];
        }
        Sight_PublishLimitRay(in.title, ray);
        bool limitHit = false;
        float limitRangeWu = 0.0f;
        const bool limitTraced = Sight_ReadLimitTrace(in.title, generation, kSightFreshMs, limitHit, limitRangeWu);
        bool intentTraced = false, intentHit = false;
        float intentDistanceWu = -1.0f;
        SightRay intentRay{};
        SightTrace intentTrace{};
        if (!limitTraced && Sight_ReadRay(in.title, generation, kSightRayFreshMs, intentRay) &&
            Sight_ReadTrace(in.title, generation, kSightFreshMs, intentTrace))
        {
            intentDistanceWu = shot_point::DistanceToRayPoint(rayOrigin, intentRay.head, intentRay.dir,
                                                                  intentTrace.rangeWu);
            intentTraced = intentDistanceWu > 0.0f;
            intentHit = intentTrace.hit;
        }
        const float unitsPerVrMetre = g_worldScale.load(std::memory_order_relaxed);
        const shot_point::RangeChoice range = shot_point::ChooseRange(
            limitTraced, limitHit, limitRangeWu, intentTraced, intentHit, intentDistanceWu,
            g_config.crosshair_distance_m * unitsPerVrMetre, kSightTraceLengthWu);
        shot_point::Placement p{};
        float vrYaw = 0.0f, vrPitch = 0.0f;
        bool mapped = false;
        if (shot_point::Place(in.head, rayOrigin, rayDir, range, unitsPerVrMetre, p))
        {
            if (in.intentDelta)
            {
                seat_frame::Angles toPoint{}, intent{};
                if (seat_frame::AnglesOf(p.dir, 0.0f, toPoint) && seat_frame::AnglesOf(in.intentDir, 0.0f, intent))
                {
                    vrYaw = in.controllerVrYaw + in.yawSign * std::remainder(toPoint.yaw - intent.yaw, 6.28318531f);
                    vrPitch = in.controllerVrPitch + in.pitchSign * (toPoint.pitch - intent.pitch);
                    mapped = std::isfinite(vrYaw) && std::isfinite(vrPitch);
                }
            }
            else
                mapped = SeatLimitWorldToVr(in, p.dir, vrYaw, vrPitch);
        }
        if (mapped)
        {
            mark.place(vrYaw, vrPitch, p.rangeVrM, p.surface);
            placed = mark.valid;
        }
    }
    if (!placed)
    {
        // Turned in place by what the clamp did to the target (a band-held shot: by its line's angles, an approximation
        // -- the line starts at the guns, not the eye).
        seat_limit::Result turned = r;
        if (bandClamped)
        {
            turned.worldYaw = bandShot.worldYaw;
            turned.worldPitch = bandShot.worldPitch;
        }
        float vrYaw = in.controllerVrYaw, vrPitch = in.controllerVrPitch;
        if (!seat_limit::TurnVrByClamp(in.targetYaw, in.targetPitch, turned, in.yawSign, in.pitchSign, vrYaw, vrPitch))
            return false;
        mark.turn(vrYaw, vrPitch);
        if (!mark.valid)
            return false;
    }
    Sight_MarkSeatLimitClamped(in.title);
    Sight_NoteSeatLimit(in.title, r.clamped[0], r.clamped[1], overshoot, bandClamped);
    return true;
}

// A SEAT AIMED WITH THE STICK (vehicle_control = stick; vehicle_control_logic.h). The hand aims nothing there, so
// the reticle is not the hand's: it is put on the game's own crosshair line -- from the game's own camera along its
// forward, the line a flat player's crosshair marks -- at the surface that line meets, drawn from the rendered eye.
// The line is traced by the sim thread as the seat limit ray: a stick-aimed seat is never held at a clamp of the
// hand's, so that ray is free. Without the rendered eye this poll the reticle is drawn along the line's direction
// at the crosshair distance. `in` carries the title, the eye and the world -> VR mapping; its stops and target are
// not used.
static void SeatStickReticleStep(const SeatLimitPoll& in, const float lineStart[3], const float lineDir[3],
                                 SeatLimitMarkPublication& mark)
{
    const float unitsPerVrMetre = g_worldScale.load(std::memory_order_relaxed);
    float vrYaw = 0.0f, vrPitch = 0.0f;
    if (in.eyes)
    {
        const uint32_t generation = TitleAdapter_GetGeneration(in.title);
        SightAuxRay ray{};
        ray.generation = generation;
        ray.sampleMs = Sight_NowMs();
        for (int axis = 0; axis < 3; ++axis)
        {
            ray.origin[axis] = lineStart[axis];
            ray.dir[axis] = lineDir[axis];
        }
        Sight_PublishLimitRay(in.title, ray);
        bool hit = false;
        float rangeWu = 0.0f;
        const bool traced = Sight_ReadLimitTrace(in.title, generation, kSightFreshMs, hit, rangeWu);
        const shot_point::RangeChoice range = shot_point::ChooseRange(
            traced, hit, rangeWu, false, false, -1.0f, g_config.crosshair_distance_m * unitsPerVrMetre,
            kSightTraceLengthWu);
        shot_point::Placement p{};
        if (shot_point::Place(in.head, lineStart, lineDir, range, unitsPerVrMetre, p) &&
            SeatLimitWorldToVr(in, p.dir, vrYaw, vrPitch))
        {
            mark.place(vrYaw, vrPitch, p.rangeVrM, p.surface);
            if (mark.valid)
                return;
        }
    }
    if (SeatLimitWorldToVr(in, lineDir, vrYaw, vrPitch))
        mark.place(vrYaw, vrPitch, Clamp(g_config.crosshair_distance_m, 2.0f, 50.0f), false);
}

// THE GUN CAMERA'S OWN OFFSET, the aim poll's half (Halo 3 gun-slaved seats; gun_slaved_seat_logic.h, "the gun's own
// offset"). In a seat whose first-person camera is the gun (seat flag bit 7) the firing assist aims the
// shot at that camera's crosshair, and the camera sits a fixed rotation off the occupant's aim the record drives (the
// gauss turret ~2.4 deg, the chaingun ~0.5 deg, both constant across the gun's travel). The poll learns that rotation
// in the turret's object frame while the gun is at rest on its aim and the hand is still, and feeds it FORWARD: the
// record is written as the ray through the point minus it, so the camera -- the record plus it -- lands on the ray.
// Where the gun stands in for the record (the drive's camera check and outcome guard, the servo's gun feedback, the
// turret witnesses) it is read minus the offset: the occupant's aim it implies. Nothing closes a loop on it. Halo 3
// only: ODST's seat snapshot carries no object frame to measure it in.
struct GunOffsetState
{
    gun_slaved::OffsetLearner learner{};
    gun_slaved::Stillness still{};
    gun_slaved::OffsetBook book{};
    uint32_t key = 0, definition = 0xFFFFFFFFu, generation = 0;
    uint64_t lastMs = 0;
    bool announced = false, refusalAnnounced = false;
#if HALOMCCVR_DEV_DIAGNOSTICS
    gun_slaved::OffsetRange range{};
    uint64_t rangeMs = 0;
    uint32_t applied = 0;
    unsigned refusedAtWindow[static_cast<unsigned>(gun_slaved::OffsetRefusal::Count)]{};
#endif
};
static GunOffsetState g_gunOffset;   // input thread only
constexpr unsigned kGunOffsetRefusals = static_cast<unsigned>(gun_slaved::OffsetRefusal::Count);

// The cold worker's view (GunAimReport): one release edge at a time (learned / refused), and the dev window.
struct GunOffsetNotes
{
    std::atomic<uint32_t> seq{0};            // odd while written
    std::atomic<uint32_t> kind{0};           // 1 learned (fed forward from now), 2 seeded from the definition, 3 refused
    std::atomic<uint32_t> definition{0}, samples{0}, refused{0};
    std::atomic<uint32_t> refusedBy[kGunOffsetRefusals]{};   // per gun_slaved::OffsetRefusal
    std::atomic<float> yaw{0.0f}, pitch{0.0f};
#if HALOMCCVR_DEV_DIAGNOSTICS
    std::atomic<uint32_t> windowSeq{0};
    std::atomic<uint32_t> windowSamples{0}, windowApplied{0}, windowDefinition{0};
    std::atomic<uint32_t> windowRefusedBy[kGunOffsetRefusals]{};
    std::atomic<float> window[10]{};         // delta yaw min/max, pitch min/max; gun yaw min/max, pitch min/max; the average
#endif
};
static GunOffsetNotes g_gunOffsetNotes;

static void GunOffsetNote(uint32_t kind, uint32_t definition, const gun_slaved::OffsetLearner& l)
{
    auto& n = g_gunOffsetNotes;
    n.seq.fetch_add(1, std::memory_order_acq_rel);
    n.kind.store(kind, std::memory_order_relaxed);
    n.definition.store(definition, std::memory_order_relaxed);
    n.samples.store(l.samples, std::memory_order_relaxed);
    n.refused.store(l.refused, std::memory_order_relaxed);
    for (unsigned i = 0; i < kGunOffsetRefusals; ++i)
        n.refusedBy[i].store(l.refusedBy[i], std::memory_order_relaxed);
    n.yaw.store(l.yaw, std::memory_order_relaxed);
    n.pitch.store(l.pitch, std::memory_order_relaxed);
    n.seq.fetch_add(1, std::memory_order_release);
}

// The turret's object frame from the snapshot's forward and up: orthonormalised, l = u x f (the game's own frame order;
// the same hull frame the gun band measures in, vehicle_gun_band_logic.h).
static bool GunOffsetTurretFrame(const float fwd[3], const float up[3], seat_frame::Frame& out)
{
    return gun_band::HullFrame(fwd, up, out);
}

// One poll of a Halo 3 gun-slaved seat. `gun*`: the gun camera's world aim (the published camera forward); `hand*`:
// the hand's own direction. True, with the offset to feed forward, once it is usable for this stint.
static bool GunOffsetStep(uint32_t seatKey, uint32_t definition, const seat_frame::Frame& turret, float gunYaw,
                          float gunPitch, float handYaw, float handPitch, float& dYaw, float& dPitch)
{
    auto& s = g_gunOffset;
    const uint64_t now = GetTickCount64();
    const uint32_t generation = TitleAdapter_GetGeneration(GameTitle::Halo3);
    if (seatKey != s.key || definition != s.definition || generation != s.generation || !s.lastMs ||
        now < s.lastMs || now - s.lastMs > 500)
    {
        // A new stint: start from what this gun definition taught the last one, if anything.
        s.learner.reset();
        s.still.reset();
#if HALOMCCVR_DEV_DIAGNOSTICS
        for (unsigned& at : s.refusedAtWindow)
            at = 0;   // the learner's counts restart with the stint
#endif
        if (const auto* e = s.book.find(definition, generation))
            s.learner.seed(e->yaw, e->pitch, e->samples);
        s.key = seatKey;
        s.definition = definition;
        s.generation = generation;
        s.announced = s.refusalAnnounced = false;
        if (s.learner.usable())
        {
            s.announced = true;
            GunOffsetNote(2, definition, s.learner);
        }
    }
    s.lastMs = now;
    float occYaw = 0.0f, occPitch = 0.0f;
    unsigned agreeing[2]{};
    if (LegacyDriveOccupantAim(GameTitle::Halo3, seatKey, occYaw, occPitch, agreeing))
    {
        const float v[6]{gunYaw, gunPitch, occYaw, occPitch, handYaw, handPitch};
        float y = 0.0f, p = 0.0f, sep = 0.0f;
        if (s.still.step(v, now))
        {
            // Refused by identity only (gun_slaved::OffsetSampleRefusal), never by the sample's size: the occupant's
            // aim proven against the record on both axes (the servo's own trust count), and the seat not held at its
            // stop. A sample whose angles do not resolve is counted as NonFinite.
            bool held = false, turretSeat = false;
            SeatNaturalHolds(GameTitle::Halo3, held, turretSeat);
            (void)turretSeat;
            const bool occupantProven = agreeing[0] >= gun_slaved::kServoTrustSamples &&
                                        agreeing[1] >= gun_slaved::kServoTrustSamples;
            if (!gun_slaved::OffsetInFrame(turret, gunYaw, gunPitch, occYaw, occPitch, y, p, sep))
                y = p = std::numeric_limits<float>::quiet_NaN();
            if (s.learner.step(y, p, gun_slaved::OffsetSampleRefusal(occupantProven, held)))
            {
                s.book.store(definition, generation, s.learner.yaw, s.learner.pitch, s.learner.samples);
#if HALOMCCVR_DEV_DIAGNOSTICS
                seat_frame::Angles gunFrame{};
                if (gun_slaved::AnglesInFrame(turret, gunYaw, gunPitch, 0.0f, gunFrame))
                    s.range.note(y, p, gunFrame.yaw, gunFrame.pitch);
#endif
            }
        }
    }
    else
    {
        s.still.reset();
    }
    if (s.learner.usable() && !s.announced)
    {
        s.announced = true;
        GunOffsetNote(1, definition, s.learner);
    }
    // Fail closed, once a stint: still samples keep arriving refused (by reason) and none was ever averaged in.
    if (!s.learner.usable() && !s.refusalAnnounced && s.learner.refused >= 30)
    {
        s.refusalAnnounced = true;
        GunOffsetNote(3, definition, s.learner);
    }
#if HALOMCCVR_DEV_DIAGNOSTICS
    if (!s.rangeMs || now < s.rangeMs || now - s.rangeMs >= 2000)
    {
        auto& n = g_gunOffsetNotes;
        n.windowSeq.fetch_add(1, std::memory_order_acq_rel);
        n.windowSamples.store(s.range.samples, std::memory_order_relaxed);
        n.windowApplied.store(s.applied, std::memory_order_relaxed);
        for (unsigned i = 0; i < kGunOffsetRefusals; ++i)
        {
            const unsigned total = s.learner.refusedBy[i];
            n.windowRefusedBy[i].store(total - (std::min)(s.refusedAtWindow[i], total), std::memory_order_relaxed);
            s.refusedAtWindow[i] = total;
        }
        n.windowDefinition.store(definition, std::memory_order_relaxed);
        const float w[10]{s.range.minYaw, s.range.maxYaw, s.range.minPitch, s.range.maxPitch, s.range.gunMinYaw,
                          s.range.gunMaxYaw, s.range.gunMinPitch, s.range.gunMaxPitch,
                          s.learner.have ? s.learner.yaw : std::numeric_limits<float>::quiet_NaN(),
                          s.learner.have ? s.learner.pitch : std::numeric_limits<float>::quiet_NaN()};
        for (int i = 0; i < 10; ++i)
            n.window[i].store(w[i], std::memory_order_relaxed);
        n.windowSeq.fetch_add(1, std::memory_order_release);
        s.range.reset();
        s.applied = 0;
        s.rangeMs = now;
    }
#endif
    if (!s.learner.usable())
        return false;
    dYaw = s.learner.yaw;
    dPitch = s.learner.pitch;
#if HALOMCCVR_DEV_DIAGNOSTICS
    ++s.applied;
#endif
    return true;
}

// Cold worker, every 2 s: the offset's edges (all builds) and, dev, the window -- is the offset the same across the
// gun's range?
void GunAimReport()
{
    static uint64_t s_last = 0;
    const uint64_t now = GetTickCount64();
    if (now - s_last < 2000)
        return;
    s_last = now;
    Halo3GunBandReport();   // SEAT LIMIT Halo 3 gun band: the driver's guns learned / animated / no weapon angle
#if HALOMCCVR_DEV_DIAGNOSTICS
    Halo3AssistWitnessReport();   // SHOT Halo 3 assist (dev)
    Halo3ImpactWitnessReport();   // SHOT IMPACT / SHOT RETICLE Halo 3 (dev)
#endif
    auto& n = g_gunOffsetNotes;
    static uint32_t s_seenSeq = 0;
    const uint32_t seq = n.seq.load(std::memory_order_acquire);
    if (seq != s_seenSeq && !(seq & 1u))
    {
        s_seenSeq = seq;
        const uint32_t kind = n.kind.load(std::memory_order_relaxed);
        const uint32_t definition = n.definition.load(std::memory_order_relaxed);
        const float yaw = n.yaw.load(std::memory_order_relaxed) * 57.29578f;
        const float pitch = n.pitch.load(std::memory_order_relaxed) * 57.29578f;
        if (kind == 1 || kind == 2)
            LOG("DRIVE Halo 3 gun-slaved seat: gun 0x%04X's camera sits %+.2f deg yaw, %+.2f deg pitch (turret frame) off "
                "the occupant's aim (%s); the record is written that much short of the ray through the point, so the "
                "gun's crosshair lands on it", definition & 0xFFFFu, yaw, pitch,
                kind == 1 ? "learned this stint from the gun at rest" : "remembered from this gun's last stint");
        else if (kind == 3)
            LOG("DRIVE Halo 3 gun-slaved seat: gun 0x%04X's camera offset NOT learned (%u still samples refused: the "
                "occupant's aim not proven against the record %u, the seat held at its stop %u, angles unresolved %u); "
                "the record is written as the ray, as before (the shot is still re-aimed through the point at the fire)",
                definition & 0xFFFFu, n.refused.load(std::memory_order_relaxed),
                n.refusedBy[static_cast<unsigned>(gun_slaved::OffsetRefusal::OccupantUnproven)].load(
                    std::memory_order_relaxed),
                n.refusedBy[static_cast<unsigned>(gun_slaved::OffsetRefusal::HeldAtStop)].load(std::memory_order_relaxed),
                n.refusedBy[static_cast<unsigned>(gun_slaved::OffsetRefusal::NonFinite)].load(std::memory_order_relaxed));
    }
#if HALOMCCVR_DEV_DIAGNOSTICS
    static uint32_t s_seenWindow = 0;
    const uint32_t window = n.windowSeq.load(std::memory_order_acquire);
    if (window != s_seenWindow && !(window & 1u))
    {
        s_seenWindow = window;
        const uint32_t samples = n.windowSamples.load(std::memory_order_relaxed);
        const uint32_t applied = n.windowApplied.load(std::memory_order_relaxed);
        const uint32_t unproven = n.windowRefusedBy[static_cast<unsigned>(gun_slaved::OffsetRefusal::OccupantUnproven)]
                                      .load(std::memory_order_relaxed);
        const uint32_t heldAtStop =
            n.windowRefusedBy[static_cast<unsigned>(gun_slaved::OffsetRefusal::HeldAtStop)].load(std::memory_order_relaxed);
        const uint32_t unresolved =
            n.windowRefusedBy[static_cast<unsigned>(gun_slaved::OffsetRefusal::NonFinite)].load(std::memory_order_relaxed);
        const uint32_t refused = unproven + heldAtStop + unresolved;
        float w[10];
        for (int i = 0; i < 10; ++i)
            w[i] = n.window[i].load(std::memory_order_relaxed) * 57.29578f;
        if (samples || applied || refused)
            LOG("DRIVE Halo 3 gun offset (dev): gun 0x%04X delta yaw %+.2f pitch %+.2f deg (fed forward in %u polls); "
                "%u still samples this window: delta yaw %+.2f..%+.2f, pitch %+.2f..%+.2f deg over the gun's yaw "
                "%+.1f..%+.1f, pitch %+.1f..%+.1f deg (turret frame); refused %u (occupant's aim unproven %u, held at a stop %u, "
                "unresolved %u; never by size)",
                n.windowDefinition.load(std::memory_order_relaxed) & 0xFFFFu, w[8], w[9], applied, samples,
                samples ? w[0] : 0.0f, samples ? w[1] : 0.0f, samples ? w[2] : 0.0f, samples ? w[3] : 0.0f,
                samples ? w[4] : 0.0f, samples ? w[5] : 0.0f, samples ? w[6] : 0.0f, samples ? w[7] : 0.0f, refused,
                unproven, heldAtStop, unresolved);
    }
#endif
}

