        float vrYaw = 0.0f, vrPitch = 0.0f;
        if (!assess_reticle::Place(head, shotOrigin, assessRay.dir, range, unitsPerVrMetre, assessPlaced) ||
            !assessToVr(assessPlaced.dir, vrYaw, vrPitch))
            return false;
