            assess_reticle::ChooseGameAimSource(assessReachOnFoot, assessUnitAimFresh);
        if (assessSource == assess_reticle::GameAimSource::None)
        {
            clamped.clear();
            g_assessNoUnitAim.fetch_add(1, std::memory_order_relaxed);
            return;
        }
