        const float assessAimPitch = asinf(Clamp(assessAim[2] / std::fmax(std::sqrt(assessAim[0] * assessAim[0] +
                                                     assessAim[1] * assessAim[1] + assessAim[2] * assessAim[2]),
                                                     1.0e-6f), -1.0f, 1.0f));
