bool WaitForNativeDetourQuiescence(const void* const* functions,
    const void* const* trampolines,size_t count,const std::atomic<uint32_t>& callbacks)
{
    // This shared worker-side retirement path serves CE's nine control
    // callbacks and Reach's larger grouped hook sets. Keep the bound fixed and
    // stack-backed so teardown never allocates while validating detours.
    // WHY IT WAS NOT VERIFIED. Every caller prints one line of its own ("... callbacks or ingress busy") for all
    // of these, and they are not the same thing: a thread that really stands in a detour, a callback counter
    // that never came back to zero, or a scan that could not be made at all (at a forced close the threads
    // cannot be frozen, and the log said "busy"). One line here, before the caller's, says which.
    const auto notVerified=[count](const char* why)
    {
        LOG("detour quiescence not verified for %zu hook%s: %s (the cleanup line that follows names them)",
            count,count==1?"":"s",why);
        return false;
    };
    if(!functions || !trampolines || !count || count>kNativeDetourRangeCapacity) return false;
    ReachDetourCodeRange ranges[kNativeDetourRangeCapacity]{};
    for(size_t i=0;i<count;++i)
        if(!functions[i] || !ResolveReachDetourCodeRange(functions[i],ranges[i]))
            return notVerified("a detour's own code range could not be resolved, so no thread could be checked against it");
    // What each look found, counted over the whole wait: the line at the end states these numbers and nothing
    // about "every" look (reporting the last look alone would read as if it had held for the 2 s).
    unsigned looks=0,counterLooks=0,scans=0,threadScans=0,counterAfterScans=0;
    for(unsigned waited=0;waited<2000;++waited)
    {
        ++looks;
        const bool counterBusy=callbacks.load(std::memory_order_acquire)!=0;
        if(counterBusy) ++counterLooks;
        if(!counterBusy)
        {
            ReachThreadFreeze frozen;
            if(!frozen.Capture())
                return notVerified("the process's threads could not be frozen for the scan (nothing was found busy)");
            bool busy=false,scanOk=true;
            for(const ReachFrozenThread& thread:frozen.Threads())
            {
                if(!thread.suspended) continue;
                CONTEXT context{};
                context.ContextFlags=CONTEXT_CONTROL;
                if(!GetThreadContext(thread.handle,&context))
                {
                    if(WaitForSingleObject(thread.handle,0)!=WAIT_OBJECT_0) scanOk=false;
                    continue;
                }
                for(size_t i=0;i<count;++i)
                {
                    const DWORD64 trampoline=reinterpret_cast<DWORD64>(trampolines[i]);
                    busy |= (context.Rip>=ranges[i].begin && context.Rip<ranges[i].end) ||
                        (trampoline && context.Rip>=trampoline && context.Rip<trampoline+64);
                }
            }
            ++scans;
            if(busy) ++threadScans;
            const bool counterAfter=callbacks.load(std::memory_order_acquire)!=0;
            if(counterAfter) ++counterAfterScans;
            busy |= counterAfter;
            const bool resumed=frozen.Release();
            if(!resumed) return notVerified("the frozen threads could not all be resumed");
            if(!scanOk) return notVerified("a live thread's position could not be read (nothing was found busy)");
            if(!busy) return true;
        }
        Sleep(1);
    }
    LOG("detour quiescence not verified for %zu hook%s: never quiet in 2 s. Of %u looks, the callback counter was "
        "not zero at %u (a callback running, or one that never came back if that is all of them); the threads "
        "were frozen and scanned %u times: a thread stood in a detour or its trampoline in %u of those, and the "
        "counter had become non-zero again by the end of %u (the cleanup line that follows names the hooks)",
        count,count==1?"":"s",looks,counterLooks,scans,threadScans,counterAfterScans);
    return false;
}

bool Game_TitleCoreState(GameTitle title, GameTitleCoreState& out) noexcept
{
    out = {};
    if (title == GameTitle::Halo4)
    {
        out.installed = g_halo4Camera.installed.load(std::memory_order_acquire);
        out.tearingDown = &g_halo4Camera.teardownRequested;
        out.lastFrameMs = &g_halo4LastFrameMs;
        return true;
    }
    if (title == GameTitle::Halo2)
    {
        // Halo 2's game end has not been measured: the gate only waits for a teardown its core began itself.
        out.installed = Halo2Observer6Dof_Installed();
        out.tearingDown = Halo2Observer6Dof_TeardownRequested();
        return true;
    }
    if (title == GameTitle::HaloCE)
    {
        // Halo CE's camera keeps stamping through a pause; the gate asks for the teardown when MCC loads halo1.dll
        // by name after it has been still for half a second (haloce_stereo_core.cpp teardownRequested).
        out.installed = HaloCE_Installed();
        out.tearingDown = HaloCE_TeardownRequested();
        out.lastFrameMs = HaloCE_LastFrameMs();
        return true;
    }
    return false;
}

#if HALOMCCVR_DEV_DIAGNOSTICS
// Why Halo 4's seat owner was refused (dev): the first failing gate per call, reported every 5 s on the
// `Vehicle first person title=4` lines. 0 ok, 1 preconditions, 2 the seat read failed, 3 not seated, 4 no
// engine TLS on this thread, 5 the unit is not a biped, 6 the parent resolves to nothing in the selector's
// own mask, 7 the unit's parent/seat changed under the read. Also counted, never refused: ok with an
// armor ability held (unit+0x664 set): refusing that case would refuse nearly every campaign seat.
namespace { std::atomic<uint32_t> g_h4OwnerWhy[8]{}, g_h4OwnerWithEquipment{0}; }
void Game_Halo4CameraOwnerReport() noexcept
{
    uint32_t why[8]{};
    for (unsigned k=0;k<8;++k) why[k]=g_h4OwnerWhy[k].exchange(0,std::memory_order_relaxed);
    LOG("Vehicle first person title=4 owner read: ok %u (armor ability held %u), preconditions %u, seat read "
        "failed %u, not seated %u, no TLS %u, unit not a biped %u, parent unresolved %u, parent/seat changed %u",
        why[0],g_h4OwnerWithEquipment.exchange(0,std::memory_order_relaxed),why[1],why[2],why[3],why[4],why[5],
        why[6],why[7]);
}
#define MCCVR_H4_OWNER_WHY(n) g_h4OwnerWhy[n].fetch_add(1,std::memory_order_relaxed)
#else
#define MCCVR_H4_OWNER_WHY(n) ((void)0)
#endif

