void* Game_ReloadPolicyWeapon(GameTitle title, uint32_t weapon)
{
    if (weapon==UINT32_MAX || !(weapon>>16) || title!=TitleAdapter_GetActiveTitle() ||
        !g_enabled.load() || !g_vrAim.load() || !Game_IsHeadTracking() ||
        !VR_IsStereoEnabled() || Menu_IsOpen() || VR_IsPausePresentation() ||
        VR_IsPausePresentationTarget() || VR_IsCutsceneTheaterActive() ||
        TitleAdapter_GetRuntimeMode()!=RuntimeMode::Gameplay) return nullptr;
    __try
    {
        const uint8_t* data=nullptr;
        uint32_t local=UINT32_MAX, owner=UINT32_MAX;
        switch(title)
        {
        case GameTitle::HaloCE:
        {
            HaloCELocalPlayerState state{};
            if (!HaloCEControls_GetLocalPlayerState(state) || state.weapon!=weapon || !state.onFoot ||
                !state.nativePreparesFirstPerson || state.nativePaused || state.nativeCinematicFlag ||
                state.nativeInputBlocked || state.nativeLookBlocked) return nullptr;
            const auto base=reinterpret_cast<uintptr_t>(GetModuleHandleW(L"halo1.dll"));
            // Controls admission independently verifies this exact accessor.
            using Get=uintptr_t(__fastcall*)(uint32_t,uint32_t);
            return base ? reinterpret_cast<void*>(reinterpret_cast<Get>(base+
                halo_ce::contract::player_state::state_object_try_get)(weapon,4)) : nullptr;
        }
        case GameTitle::Halo2: return Halo2Observer6Dof_ReloadWeapon(weapon);
        case GameTitle::Halo3:
            if (!g_halo3PlayerUnitGetter) return nullptr;
            local=g_halo3PlayerUnitGetter(0);
            data=Halo3MeleeSelectionObject(weapon,2);
            if (data && data[0x15d]) owner=*reinterpret_cast<const uint32_t*>(data+0x168);
            break;
        case GameTitle::Halo3ODST:
        {
            if (!g_odstPlayerUnitGetter || !OdstContactObject(weapon)) return nullptr;
            local=g_odstPlayerUnitGetter(0);
            const auto table=*reinterpret_cast<const uint8_t* const*>(OdstContactTls()+kOdstTlsObjectTableOffset);
            const auto entries=*reinterpret_cast<const uint8_t* const*>(table+0x48);
            const auto entry=entries+(weapon&0xffff)*0x18;
            if (entry[3]!=2) return nullptr;
            data=*reinterpret_cast<const uint8_t* const*>(entry+0x10);
            if (data && data[0x155]) owner=*reinterpret_cast<const uint32_t*>(data+0x160);
            break;
        }
        case GameTitle::HaloReach:
        {
            if (!g_reachCamera.playerUnitByOutputUser) return nullptr;
            local=g_reachCamera.playerUnitByOutputUser(0);
            uint8_t kind=0;
            data=ReachVehicleObjectData(weapon,kind);
            if (!data || kind!=2) return nullptr;
            owner=*reinterpret_cast<const uint32_t*>(data+0x32c);
            if (owner==UINT32_MAX && data[0x1a9]) owner=*reinterpret_cast<const uint32_t*>(data+0x1b4);
            break;
        }
        case GameTitle::Halo4:
        {
            Halo4FirstPersonAccess fp{};
            (void)Halo4ResolveFirstPerson(0,fp);
            if (!fp.record) return nullptr;
            local=*reinterpret_cast<const uint32_t*>(fp.record+kHalo4FirstPersonRecordUnitOffset);
            data=Halo4ContactObject(weapon);
            if (!data) return nullptr;
            data=g_halo4Contact.object(weapon,4);
            if (!data) return nullptr;
            owner=*reinterpret_cast<const uint32_t*>(data+0x624);
            if (owner==UINT32_MAX && data[0x471]) owner=*reinterpret_cast<const uint32_t*>(data+0x480);
            break;
        }
        default: return nullptr;
        }
        return local!=UINT32_MAX && (local>>16) && owner==local ? const_cast<uint8_t*>(data) : nullptr;
    }
    __except(EXCEPTION_EXECUTE_HANDLER) { return nullptr; }
}

// The CROUCH line's handsLift (game.h): the view lift each title last published for its hands.
float Game_ViewLiftWu(GameTitle title)
{
    switch (title)
    {
    case GameTitle::Halo3:
    case GameTitle::Halo3ODST:
        return g_baseCamValid.load(std::memory_order_acquire) ? g_baseCamViewLiftZ.load(std::memory_order_relaxed) : 0.0f;
#if HALOMCCVR_EXPERIMENTAL_HALO4_CAMERA
    case GameTitle::Halo4:
        return g_halo4HandsLiftZ.load(std::memory_order_relaxed);
#endif
#if HALOMCCVR_HALO2_STEREO6DOF
    case GameTitle::Halo2:
    {
        Halo2ObserverPosePublication publication{};
        return Halo2Observer6Dof_ReadPublishedPose(publication) ? publication.viewLiftZ : 0.0f;
    }
#endif
    default:
        return 0.0f;
    }
}

// Halo 4 publishes Gameplay in a seat too; the physical crouch needs its own on-foot state. Called from the
// XInput poll, which is NOT always the engine thread: reading Halo 4's per-thread TLS from there passes only
// when the poll happens to land on it, so the gate flickers about once a second and lets go of every duck.
// The camera hook stamps the verdict instead; a stale stamp is "not on foot".
bool Game_Halo4OnFoot()
{
#if HALOMCCVR_EXPERIMENTAL_HALO4_CAMERA
    const auto at = g_halo4OnFootMs.load(std::memory_order_acquire), now = GetTickCount64();
    return at && now >= at && now - at <= 250;
#else
    return false;
#endif
}

// ---- Weapon-order diagnostic tranche (read-only evidence) ----
// No gameplay, tracking, aiming, rendering, input, or lifecycle effect.
// detailOut bits shared by every diagnostic reader:
//   bit0  secondary slot present (where the reader naturally knows it)
//   bit1  ownership proven (H2/H4 mirror validation)
//   bit2  FP-side agreement (engine FP record already shows this handle)
//   bit30 lifecycle guard rejection (maps to GuardRejected)
//   bit31 native fault (maps to ExceptionOrFault)
// The Capture probe records the inventory/ownership view (bit2 raw), while
// the FP commit check requires bit2 so it fires only at the existing stable
// commit point where the FP record also agrees. CE is probed directly from
// vr.cpp through HaloCEControls_GetLocalPlayerState; H2 forwards to the
// observer core's guarded datum reader below.
namespace
{
    constexpr uint32_t kDiagnosticFpAgreement = 4u;
    constexpr uint32_t kDiagnosticGuard = 0x40000000u;

    std::atomic<uint64_t> g_diagnosticFpThread[8]{};
    // Recording session that the FP-thread observation belongs to. A numeric
    // thread id reused by a later session is not authorization until that
    // session observes its own FP entry.
    std::atomic<uint64_t> g_diagnosticFpSession[8]{};
    int DiagnosticTitleSlot(GameTitle title) noexcept
    {
        const int slot = static_cast<int>(title);
        return (slot >= 0 && slot < 8) ? slot : -1;
    }
    // True when the title lifecycle moved after the diagnostic read began:
    // used to classify a native fault that coincides with a reload/teardown
    // as a guard rejection rather than an unexplained fault. Safe to call
    // from an exception handler (atomic loads only).
    bool DiagnosticLifecycleChanged(GameTitle title,
        uint32_t expectedGeneration) noexcept
    {
        if (title != TitleAdapter_GetActiveTitle() ||
            TitleAdapter_GetGeneration(title) != expectedGeneration)
            return true;
        switch (title)
        {
        case GameTitle::Halo3:
            return g_halo3RuntimeGeneration.load(
                std::memory_order_acquire) != expectedGeneration;
        case GameTitle::Halo3ODST:
            return g_odstRuntimeGeneration.load(
                std::memory_order_acquire) != expectedGeneration;
        case GameTitle::HaloReach:
            return g_reachCamera.generation.load(
                std::memory_order_acquire) != expectedGeneration;
        case GameTitle::Halo4:
            return g_halo4Camera.generation.load(
                std::memory_order_acquire) != expectedGeneration;
        default:
            return false;
        }
    }
    bool H3PrimaryWeaponEvidence(uint32_t expectedGeneration, uint32_t& unitOut,
        uint32_t& weaponOut, uint32_t& detailOut,
        bool* primaryAbsentOut) noexcept
    {
        if (primaryAbsentOut) *primaryAbsentOut = false;
        if (!g_halo3PlayerUnitGetter || !g_halo3UnitInVehicle)
            return false;
        if (g_halo3RuntimeGeneration.load(std::memory_order_acquire) !=
            expectedGeneration)
        {
            detailOut = kDiagnosticGuard;
            return false;
        }
        const uint32_t owner = uint32_t(g_halo3PlayerUnitGetter(0));
        if (owner == UINT32_MAX || !(owner >> 16)) return false;
        if (g_halo3UnitInVehicle(int32_t(owner))) return false;
        uint32_t weapons[2]{};
        if (!Halo3ReadOwnedWeapons(owner, weapons, false, primaryAbsentOut))
            return false;
        if (weapons[0] == UINT32_MAX) return false;
        detailOut = (weapons[1] != UINT32_MAX) ? 1u : 0u;
        // FP-side slot agreement, mirroring the existing stable commit point
        // without its optional-feature gates. The Capture probe records this
        // raw; the FP commit requires it.
        if (g_engineTlsIndex && *g_engineTlsIndex < 0x200)
        {
            auto** slots = reinterpret_cast<uint8_t**>(HALOMCCVR_GAME_TLS_ARRAY());
            const auto* tls = slots ? slots[*g_engineTlsIndex] : nullptr;
            const auto* users = tls ?
                *reinterpret_cast<const uint8_t* const*>(tls + 0x568) :
                nullptr;
            if (users && *reinterpret_cast<const uint32_t*>(
                    users + 0x3C) == weapons[0])
                detailOut |= kDiagnosticFpAgreement;
        }
        if (g_halo3RuntimeGeneration.load(std::memory_order_acquire) !=
            expectedGeneration)
        {
            detailOut = kDiagnosticGuard;
            return false;
        }
        unitOut = owner;
        weaponOut = weapons[0];
        return true;
    }
    bool DiagnosticH3Primary(uint32_t expectedGeneration, uint32_t& unitOut,
        uint32_t& weaponOut, uint32_t& detailOut) noexcept
    {
        return H3PrimaryWeaponEvidence(expectedGeneration, unitOut, weaponOut,
            detailOut, nullptr);
    }
    bool OdstPrimaryWeaponEvidence(uint32_t expectedGeneration, uint32_t& unitOut,
        uint32_t& weaponOut, uint32_t& detailOut,
        bool* primaryAbsentOut) noexcept
    {
        if (primaryAbsentOut) *primaryAbsentOut = false;
        if (!g_odstPlayerUnitGetter || !g_odstUnitInVehicle)
            return false;
        if (g_odstRuntimeGeneration.load(std::memory_order_acquire) !=
            expectedGeneration)
        {
            detailOut = kDiagnosticGuard;
            return false;
        }
        const uint32_t owner = uint32_t(g_odstPlayerUnitGetter(0));
        if (owner == UINT32_MAX || !(owner >> 16)) return false;
        if (g_odstUnitInVehicle(int32_t(owner))) return false;
        uint32_t weapons[2]{};
        if (!OdstReadMuzzleWeapons(owner, weapons, primaryAbsentOut)) return false;
        if (weapons[0] == UINT32_MAX) return false;
        detailOut = (weapons[1] != UINT32_MAX) ? 1u : 0u;
        if (g_odstEngineTlsIndex && *g_odstEngineTlsIndex < 0x200)
        {
            auto** slots = reinterpret_cast<uint8_t**>(HALOMCCVR_GAME_TLS_ARRAY());
            const auto* tls = slots ? slots[*g_odstEngineTlsIndex] : nullptr;
            const auto* users = tls ?
                *reinterpret_cast<const uint8_t* const*>(tls + 0x598) :
                nullptr;
            if (users && *reinterpret_cast<const uint32_t*>(
                    users + 0x3C) == weapons[0])
                detailOut |= kDiagnosticFpAgreement;
        }
        if (g_odstRuntimeGeneration.load(std::memory_order_acquire) !=
            expectedGeneration)
        {
            detailOut = kDiagnosticGuard;
            return false;
        }
        unitOut = owner;
        weaponOut = weapons[0];
        return true;
    }
    bool ReachPrimaryWeaponEvidence(uint32_t expectedGeneration, uint32_t& unitOut,
        uint32_t& weaponOut, uint32_t& detailOut,
        bool* primaryAbsentOut) noexcept
    {
        if (primaryAbsentOut) *primaryAbsentOut = false;
        if (!g_reachCamera.playerUnitByOutputUser ||
            !g_reachCamera.unitInVehicle)
            return false;
        if (g_reachCamera.generation.load(std::memory_order_acquire) !=
            expectedGeneration)
        {
            detailOut = kDiagnosticGuard;
            return false;
        }
        const uint32_t owner =
            uint32_t(g_reachCamera.playerUnitByOutputUser(0));
        if (owner == UINT32_MAX || !(owner >> 16)) return false;
        if (g_reachCamera.unitInVehicle(int32_t(owner))) return false;
        if (!ReachMuzzleTargetStorage(owner)) return false;
        uint32_t weapons[2]{};
        if (!ReachReadMuzzleWeapons(owner, weapons, primaryAbsentOut))
            return false;
        if (weapons[0] == UINT32_MAX) return false;
        detailOut = (weapons[1] != UINT32_MAX) ? 1u : 0u;
        if (g_reachCamera.base)
        {
            auto** slots = reinterpret_cast<uint8_t**>(HALOMCCVR_GAME_TLS_ARRAY());
            const uint32_t index = *reinterpret_cast<const uint32_t*>(
                g_reachCamera.base + kReachEngineTlsIndexRva);
            const auto* tls =
                slots && index < 0x200 ? slots[index] : nullptr;
            const auto* users = tls ?
                *reinterpret_cast<const uint8_t* const*>(tls + 0x6A0) :
                nullptr;
            if (users && *reinterpret_cast<const uint32_t*>(
                    users + 0x3C) == weapons[0])
                detailOut |= kDiagnosticFpAgreement;
        }
        if (g_reachCamera.generation.load(std::memory_order_acquire) !=
            expectedGeneration)
        {
            detailOut = kDiagnosticGuard;
            return false;
        }
        unitOut = owner;
        weaponOut = weapons[0];
        return true;
    }
    bool DiagnosticOdstPrimary(uint32_t expectedGeneration, uint32_t& unitOut,
        uint32_t& weaponOut, uint32_t& detailOut) noexcept
    {
        return OdstPrimaryWeaponEvidence(expectedGeneration, unitOut, weaponOut,
            detailOut, nullptr);
    }
    bool DiagnosticReachPrimary(uint32_t expectedGeneration, uint32_t& unitOut,
        uint32_t& weaponOut, uint32_t& detailOut) noexcept
    {
        return ReachPrimaryWeaponEvidence(expectedGeneration, unitOut, weaponOut,
            detailOut, nullptr);
    }
    // candidate == UINT32_MAX selects the primary slot (Capture path); any
    // other value must resolve to primary slot 0 through the equipped-weapon
    // mapping (the FP skinning path, where the observed record is the
    // candidate). `primaryAbsentOut` (optional) reports an explicit raw empty
    // primary slot from the same guarded read (F03/F17); it is never set by a
    // validation/lifecycle failure. This is the shared production body: the
    // diagnostic probe below and the persistent support-grip producer both
    // read through it, so the native read logic exists once.
    bool Halo4WeaponOwnerEvidence(uint32_t expectedGeneration,
        uint32_t candidate, uint32_t& unitOut, uint32_t& weaponOut,
        uint32_t& detailOut, bool* primaryAbsentOut) noexcept
    {
        if (primaryAbsentOut) *primaryAbsentOut = false;
        if (g_halo4Camera.generation.load(std::memory_order_acquire) !=
            expectedGeneration)
        {
            detailOut = kDiagnosticGuard;
            return false;
        }
        Halo4VehicleInputState seat{};
        const char* vehicleReason = nullptr;
        const bool vehicleUsable = Halo4ReadVehicleInputEx(seat, &vehicleReason) &&
            !seat.seated && seat.unit != UINT32_MAX && (seat.unit >> 16) &&
            Halo4MuzzleTargetStorage(seat.unit) != nullptr;
        uint32_t owner = seat.unit;
        if (!vehicleUsable)
        {
            // The optional vehicle-input helper is an admission shortcut, not
            // a prerequisite for on-foot owner proof. When its runtime reader
            // cannot establish the local output unit, the engine's own
            // first-person weapon record carries the same evidence. Fail
            // closed: every stage below must pass or the owner stays Unknown.
            if (!g_halo4Camera.armed.load(std::memory_order_acquire) ||
                g_halo4Camera.teardownRequested.load(std::memory_order_acquire))
                return false;
            const auto* tls = Halo4MuzzleTls();
            const auto* fpRecord = tls ?
                Halo4VehicleRead<const uint8_t*>(tls, 0x6A0) : nullptr;
            const uint32_t fpFlags = fpRecord ?
                Halo4VehicleRead<uint32_t>(fpRecord, 0) : 0u;
            const uint32_t fpUnit = fpRecord ?
                Halo4VehicleRead<uint32_t>(fpRecord, 4) : UINT32_MAX;
            const auto* fpUnitObject = (fpRecord && fpUnit != UINT32_MAX &&
                (fpUnit >> 16)) ? Halo4MuzzleObject(fpUnit, 1) : nullptr;
            // H4EK E80C00/E977E0: on foot means no parent (+0x24) and no
            // controlling parent (+0x694), mirroring Halo4MuzzleTargetStorage.
            uint32_t fallbackUnit = UINT32_MAX;
            const auto stage = halo4_owner_evidence::ResolveFromFpRecord(
                fpRecord != nullptr, fpFlags, fpUnit, fpUnitObject != nullptr,
                fpUnitObject ? Halo4VehicleRead<uint32_t>(fpUnitObject, 0x24)
                    : UINT32_MAX,
                fpUnitObject ? Halo4VehicleRead<uint32_t>(fpUnitObject, 0x694)
                    : UINT32_MAX,
                fallbackUnit);
            static std::atomic<uint32_t> s_vehicleFallbackGeneration{0};
            if (expectedGeneration &&
                s_vehicleFallbackGeneration.exchange(expectedGeneration,
                    std::memory_order_relaxed) != expectedGeneration)
                // Statement of fact: entry into the fallback does not imply the
                // later stages resolved. The outcome is logged at the return
                // site that actually decided it.
                support_diagnostics::Record(support_diagnostics::Event::H4OwnerFallback);
            if (stage != halo4_owner_evidence::Stage::Ok) return false;
            owner = fallbackUnit;
        }
        uint32_t weapons[2]{};
        if (!Halo4ReadMuzzleWeapons(owner, weapons, primaryAbsentOut))
        {
            static std::atomic<uint32_t> s_notResolvedMuzzleWeapons{0};
            static std::atomic<uint32_t> s_notResolvedPrimaryAbsent{0};
            const bool absent = primaryAbsentOut && *primaryAbsentOut;
            auto& latch = absent ? s_notResolvedPrimaryAbsent
                                 : s_notResolvedMuzzleWeapons;
            if (expectedGeneration &&
                latch.exchange(expectedGeneration,
                    std::memory_order_relaxed) != expectedGeneration)
                support_diagnostics::Record(support_diagnostics::Event::H4OwnerWeaponsUnavailable);
            return false;
        }
        if (weapons[0] == UINT32_MAX)
        {
            // Explicit empty primary slot (role byte 0xFF): a real KnownAbsent
            // state, not an unexplained refusal.
            static std::atomic<uint32_t> s_notResolvedPrimaryAbsent{0};
            if (expectedGeneration &&
                s_notResolvedPrimaryAbsent.exchange(expectedGeneration,
                    std::memory_order_relaxed) != expectedGeneration)
                support_diagnostics::Record(support_diagnostics::Event::H4OwnerAbsent);
            return false;
        }
        if (candidate != UINT32_MAX &&
            ResolveEquippedWeaponSlot(candidate, weapons[0], weapons[1],
                true, weapons[1] != UINT32_MAX) != 0)
        {
            static std::atomic<uint32_t> s_notResolvedCandidate{0};
            if (expectedGeneration &&
                s_notResolvedCandidate.exchange(expectedGeneration,
                    std::memory_order_relaxed) != expectedGeneration)
                support_diagnostics::Record(support_diagnostics::Event::H4OwnerCandidateMismatch);
            return false;
        }
        // A validated local on-foot owner, always carrying the semantic
        // primary slot handle -- never the observed candidate.
        unitOut = owner;
        weaponOut = weapons[0];
        detailOut = ((weapons[1] != UINT32_MAX) ? 1u : 0u) | 2u;
        // Primary-slot FP producer agreement, mirroring the gated muzzle
        // capture without its option/bindings gate. Recorded raw here; the FP
        // commit requires the bit so the Capture probe measures the
        // inventory/ownership view rather than the FP assembly view.
        const auto* tls = Halo4MuzzleTls();
        const auto* fp = tls ?
            Halo4VehicleRead<const uint8_t*>(tls, 0x6A0) : nullptr;
        if (fp && (Halo4VehicleRead<uint32_t>(fp, 0) & 2) &&
            Halo4VehicleRead<uint32_t>(fp, 4) == owner &&
            Halo4VehicleRead<uint32_t>(fp, 0x6C) == weapons[0])
            detailOut |= kDiagnosticFpAgreement;
        if (g_halo4Camera.generation.load(std::memory_order_acquire) !=
            expectedGeneration)
        {
            detailOut = kDiagnosticGuard;
            static std::atomic<uint32_t> s_notResolvedGeneration{0};
            if (expectedGeneration &&
                s_notResolvedGeneration.exchange(expectedGeneration,
                    std::memory_order_relaxed) != expectedGeneration)
                support_diagnostics::Record(support_diagnostics::Event::H4OwnerGenerationMismatch);
            return false;
        }
        static std::atomic<uint32_t> s_resolvedGeneration{0};
        if (expectedGeneration &&
            s_resolvedGeneration.exchange(expectedGeneration,
                std::memory_order_relaxed) != expectedGeneration)
            support_diagnostics::Record(support_diagnostics::Event::H4OwnerResolved);
        return true;
    }
    // Weapon-order diagnostic entry: byte-for-byte the production body's
    // result, kept as the diagnostic probe's own name (the same body is what
    // the persistent support-grip producer reads).
    bool DiagnosticHalo4WeaponOwner(uint32_t expectedGeneration,
        uint32_t candidate, uint32_t& unitOut, uint32_t& weaponOut,
        uint32_t& detailOut) noexcept
    {
        return Halo4WeaponOwnerEvidence(expectedGeneration, candidate, unitOut,
            weaponOut, detailOut, nullptr);
    }
    // SEH-guarded tri-state observation of Halo 4's semantic primary owner.
    // A native fault is Unknown, never absence; the observation still names
    // the lifecycle generation so a coherent Unknown record can be published
    // for the current lifecycle (mirroring Game_ReadPrimaryWeaponEvidence's
    // per-title branches).
    PrimaryWeaponEvidence Halo4ObservePrimaryWeapon(uint32_t generation,
        uint32_t candidate) noexcept
    {
        PrimaryWeaponEvidence out{};
        out.generation = generation;
        uint32_t unit = UINT32_MAX;
        uint32_t weapon = UINT32_MAX;
        uint32_t detail = 0;
        bool absent = false;
        bool ok = false;
        __try
        {
            ok = Halo4WeaponOwnerEvidence(generation, candidate, unit, weapon,
                detail, &absent);
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            ok = false;
            absent = false;
        }
        out.detail = detail;
        if (ok)
        {
            out.state = static_cast<uint8_t>(
                support_grip::OwnerEvidence::KnownPresent);
            out.unit = unit;
            out.weapon = weapon;
        }
        else
            out.state = static_cast<uint8_t>(absent
                ? support_grip::OwnerEvidence::KnownAbsent
                : support_grip::OwnerEvidence::Unknown);
        return out;
    }
    // One safe-context support-grip invocation read. `candidate` is the
    // semantic primary (UINT32_MAX) at the pair's decision boundary; a unit
    // handle must never be offered here (F04). The shared resolver publishes
    // the tri-state evidence -- including an explicit Unknown, so no stale
    // KnownPresent survives -- and returns this invocation's relation to the
    // live relationship. No diagnostic-session dependency.
    SupportInvocationResolution Halo4ReadSupportInvocation(
        uint32_t candidate) noexcept
    {
        const uint32_t generation =
            TitleAdapter_GetGeneration(GameTitle::Halo4);
        const PrimaryWeaponEvidence evidence = (generation &&
                VR_SupportGripWiredForTitle(GameTitle::Halo4))
            ? Halo4ObservePrimaryWeapon(generation, candidate)
            : PrimaryWeaponEvidence{};
        return Game_ResolveSupportInvocation(GameTitle::Halo4, evidence, true,
            evidence, true, true);
    }
}

void Game_DiagnosticNoteFpThread(GameTitle title) noexcept
{
    const int slot = DiagnosticTitleSlot(title);
    if (slot < 0)
        return;
    const uint32_t generation = TitleAdapter_GetGeneration(title);
    if (!generation)
    {
        g_diagnosticFpThread[slot].store(0, std::memory_order_release);
        g_diagnosticFpSession[slot].store(0, std::memory_order_release);
        return;
    }
    g_diagnosticFpThread[slot].store(
        (uint64_t(generation) << 32) | GetCurrentThreadId(),
        std::memory_order_release);
    g_diagnosticFpSession[slot].store(
        Telemetry_CurrentSessionToken(), std::memory_order_release);
}

uint8_t Game_DiagnosticCaptureProbePermission(GameTitle title) noexcept
{
    if (title != GameTitle::Halo3 && title != GameTitle::Halo3ODST &&
        title != GameTitle::HaloReach && title != GameTitle::Halo4)
        return weapon_order_diagnostic::kProbePermissionGuardRejected;
    const int slot = DiagnosticTitleSlot(title);
    if (slot < 0)
        return weapon_order_diagnostic::kProbePermissionGuardRejected;
    const uint64_t stored =
        g_diagnosticFpThread[slot].load(std::memory_order_acquire);
    const uint64_t session =
        g_diagnosticFpSession[slot].load(std::memory_order_acquire);
    const bool titleMatches = title == TitleAdapter_GetActiveTitle();
    const uint32_t generation = TitleAdapter_GetGeneration(title);
    const bool generationMatches = generation != 0 &&
        uint32_t(stored >> 32) == generation;
    return weapon_order_diagnostic::CaptureProbePermission(titleMatches,
        generationMatches, stored, session,
        Telemetry_CurrentSessionToken(), GetCurrentThreadId());
}

bool Game_DiagnosticReadPrimaryWeapon(GameTitle title, uint32_t& unitOut,
    uint32_t& weaponOut, uint32_t& detailOut) noexcept
{
    unitOut = UINT32_MAX;
    weaponOut = UINT32_MAX;
    detailOut = 0;
    if (title != TitleAdapter_GetActiveTitle())
    {
        detailOut = 0x40000000u; // lifecycle guard rejection
        return false;
    }
    const uint32_t generation = TitleAdapter_GetGeneration(title);
    if (!generation)
    {
        detailOut = 0x40000000u;
        return false;
    }
    __try
    {
        switch (title)
        {
        case GameTitle::Halo3:
            return DiagnosticH3Primary(generation, unitOut, weaponOut,
                detailOut);
        case GameTitle::Halo3ODST:
            return DiagnosticOdstPrimary(generation, unitOut, weaponOut,
                detailOut);
        case GameTitle::HaloReach:
            return DiagnosticReachPrimary(generation, unitOut, weaponOut,
                detailOut);
        case GameTitle::Halo4:
            return DiagnosticHalo4WeaponOwner(generation, UINT32_MAX, unitOut,
                weaponOut, detailOut);
        case GameTitle::Halo2:
            return Halo2DiagnosticReadPrimaryWeapon(unitOut, weaponOut,
                detailOut);
        default:
            return false;
        }
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        // A fault that coincides with a title/generation change is a
        // lifecycle guard rejection, not an unexplained native fault. The
        // generation recheck is atomic-only and safe inside the handler.
        detailOut = DiagnosticLifecycleChanged(title, generation)
            ? 0x40000000u : 0x80000000u;
        return false;
    }
}

// ---- Persistent support grip: production owner evidence ----
//
// The tri-state semantic-primary read a title producer publishes to the
// durable relationship input. All six gameplay titles are wired: Halo 3,
// ODST and Reach read their own guarded native state through the shared
// H3/Odst/Reach PrimaryWeaponEvidence bodies, Halo 2 through its own guarded
// direct reader (safe outside the TLS-restricted titles) and Halo 4 through
// Halo4WeaponOwnerEvidence (the body behind DiagnosticHalo4WeaponOwner).
// Each distinguishes an explicit raw primary-slot absence (KnownAbsent) from
// an unprovable read (Unknown). Halo 3's raw slot absence is source-provable
// (role byte 0xFF) while the FP interpolation hook is running; whether the
// hook runs for every unarmed presentation is recorded as an open liveness
// question in the port doc (Halo 2's absence liveness is provided by its
// level-live poll seam, Halo 4 by its per-pair skinning invocation).
bool Game_ReadPrimaryWeaponEvidence(GameTitle title,
    PrimaryWeaponEvidence& out) noexcept
{
    out = {};
    if (title != TitleAdapter_GetActiveTitle())
        return false;
    const uint32_t generation = TitleAdapter_GetGeneration(title);
    if (!generation)
        return false;
    out.generation = generation;
    if (title == GameTitle::Halo2)
    {
        uint32_t unit = UINT32_MAX, weapon = UINT32_MAX, detail = 0;
        bool absent = false;
        bool ok = false;
        __try
        {
            ok = Halo2DiagnosticReadPrimaryWeapon(unit, weapon, detail,
                &absent);
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            out.detail = DiagnosticLifecycleChanged(title, generation)
                ? 0x40000000u : 0x80000000u;
            out.state = static_cast<uint8_t>(support_grip::OwnerEvidence::Unknown);
            return true;
        }
        out.detail = detail;
        if (ok)
        {
            out.state =
                static_cast<uint8_t>(support_grip::OwnerEvidence::KnownPresent);
            out.unit = unit;
            out.weapon = weapon;
            return true;
        }
        out.state = static_cast<uint8_t>(absent
            ? support_grip::OwnerEvidence::KnownAbsent
            : support_grip::OwnerEvidence::Unknown);
        return true;
    }
    if (title == GameTitle::Halo4)
    {
        // Halo 4's own guarded reader: the shared production body behind
        // DiagnosticHalo4WeaponOwner, including the tranche-E first-person
        // record fallback. A validated local on-foot owner is KnownPresent
        // (the shared resolver still requires the FP agreement bit for that
        // claim); an explicit raw empty primary slot is KnownAbsent without
        // it (F03); everything else is Unknown -- never absence. A native
        // fault is Unknown inside Halo4ObservePrimaryWeapon.
        out = Halo4ObservePrimaryWeapon(generation, UINT32_MAX);
        return true;
    }
    if (title != GameTitle::Halo3 && title != GameTitle::Halo3ODST &&
        title != GameTitle::HaloReach)
    {
        out.state = static_cast<uint8_t>(support_grip::OwnerEvidence::Unknown);
        return true;
    }
    uint32_t unit = UINT32_MAX, weapon = UINT32_MAX, detail = 0;
    bool absent = false;
    bool ok = false;
    __try
    {
        // Each wired title keeps its own reader: Halo 3 role bytes +262/+263,
        // ODST +276/+277, Reach +34A/+34B, each with its own FP agreement
        // record. The absence flag comes from the raw primary role byte BEFORE
        // the slot-validation guards (F03): a proven empty slot must resolve
        // without the FP agreement bit, which those readers can never set on
        // that path.
        if (title == GameTitle::Halo3)
            ok = H3PrimaryWeaponEvidence(generation, unit, weapon, detail,
                &absent);
        else if (title == GameTitle::Halo3ODST)
            ok = OdstPrimaryWeaponEvidence(generation, unit, weapon, detail,
                &absent);
        else
            ok = ReachPrimaryWeaponEvidence(generation, unit, weapon, detail,
                &absent);
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        // A native fault is never proof of absence: report Unknown (the
        // lifecycle classification is diagnostic detail only).
        out.detail = DiagnosticLifecycleChanged(title, generation)
            ? 0x40000000u : 0x80000000u;
        out.state = static_cast<uint8_t>(support_grip::OwnerEvidence::Unknown);
        return true;
    }
    out.detail = detail;
    if (ok)
    {
        out.state =
            static_cast<uint8_t>(support_grip::OwnerEvidence::KnownPresent);
        out.unit = unit;
        out.weapon = weapon;
        return true;
    }
    out.state = static_cast<uint8_t>(absent
        ? support_grip::OwnerEvidence::KnownAbsent
        : support_grip::OwnerEvidence::Unknown);
    return true;
}

// Persistent support grip: one observation of the title's current semantic
// primary published to the durable relationship input, including an explicit
// Unknown record, so a stale KnownPresent must not survive an observation that
// proves nothing. This is the observation path a title can run at a lifecycle
// seam that does not depend on a weapon packet (Halo 2's level-live poll).
// Read-only with respect to the durable relationship beyond the publication
// itself.
void Game_PublishSupportGripOwnerEvidence(GameTitle title) noexcept
{
    PrimaryWeaponEvidence evidence{};
    if (!Game_ReadPrimaryWeaponEvidence(title, evidence))
        evidence = {};
    VR_PublishSupportGripOwnerEvidence(title, evidence.generation,
        support_grip::OwnerTuple{title, evidence.generation, evidence.unit,
            evidence.weapon},
        static_cast<support_grip::OwnerEvidence>(evidence.state));
}

SupportInvocationResolution Game_ResolveSupportInvocation(GameTitle title,
    const PrimaryWeaponEvidence& before, bool beforeOk,
    const PrimaryWeaponEvidence& after, bool afterOk,
    bool requireProducerAgreement) noexcept
{
    SupportInvocationResolution resolution{};
    uint32_t generation = 0;
    uint32_t unit = UINT32_MAX;
    uint32_t weapon = UINT32_MAX;
    support_grip::OwnerEvidence state = support_grip::OwnerEvidence::Unknown;
    if (beforeOk && afterOk &&
        before.generation == after.generation &&
        before.unit == after.unit && before.weapon == after.weapon)
    {
        generation = before.generation;
        // F03: the agreement bit is a present-owner proof. The native readers
        // return before setting it when the primary slot is empty, so an
        // explicit absence must resolve without it; ResolveStableEvidence
        // requires agreement only for a KnownPresent claim.
        const support_grip::OwnerEvidence stable =
            support_grip::ResolveStableEvidence(requireProducerAgreement,
                before.state, (before.detail & 0x4u) != 0,
                after.state, (after.detail & 0x4u) != 0);
        if (stable == support_grip::OwnerEvidence::KnownPresent)
        {
            state = support_grip::OwnerEvidence::KnownPresent;
            unit = before.unit;
            weapon = before.weapon;
            resolution.evidencePresent = true;
        }
        else if (stable == support_grip::OwnerEvidence::KnownAbsent)
        {
            state = support_grip::OwnerEvidence::KnownAbsent;
            resolution.evidenceAbsent = true;
        }
    }
    if (!generation && beforeOk) generation = before.generation;
    if (!generation && afterOk) generation = after.generation;
    // Publish this invocation's evidence (including Unknown) so a stale
    // KnownPresent can never survive an invocation that could not prove
    // itself, and a proven absence reaches the durable writer.
    VR_PublishSupportGripOwnerEvidence(title, generation,
        support_grip::OwnerTuple{title, generation, unit, weapon}, state);
    // F06/F07 material: the resolved owner proof (including Unknown/absence)
    // plus the relationship reading taken at this same instant. A title that
    // publishes an invocation receipt copies these fields; every other caller
    // ignores them.
    resolution.generation = generation;
    resolution.evidence = state;
    resolution.owner = support_grip::OwnerTuple{title, before.generation,
        before.unit, before.weapon};
    resolution.producerAgreement =
        (before.detail & 0x4u) != 0 && (after.detail & 0x4u) != 0;
    if (state == support_grip::OwnerEvidence::KnownPresent)
    {
        SupportGripRelationshipSnapshot relationship{};
        if (VR_GetSupportGripRelationship(relationship))
        {
            resolution.relationshipReadable = true;
            resolution.relationshipEngaged = relationship.engaged;
            resolution.relationshipEpoch = relationship.epoch;
            if (support_grip::InvocationOwnerTrusted(relationship.engaged,
                    support_grip::OwnerTuple{relationship.title,
                        relationship.generation, relationship.unit,
                        relationship.weapon},
                    state,
                    support_grip::OwnerTuple{title, before.generation,
                        before.unit, before.weapon}))
                resolution.trusted = true;
        }
    }
    return resolution;
}

// Game_RoomscaleCameraVerdict / Game_TitleOnFootVerdict (roomscale's admission, and the head leash's) are defined
// after Game_TitleFirstPersonView below: they read the same camera-thread publications.

// Each title's LAST KNOWN seat state (a pause stops the samples, and whatever follows it must still see the
// seat), as a three-way answer so each consumer chooses how to treat "no answer":
//  - Unknown: no seat sampler (Halo 3 / ODST / Reach not installed or faulted, CE unreadable), or no answer
//    yet where that is known (Halo 4 since the level began, the Halo 2 observer down or not yet sampled).
//  - Seated: the title's own sampler last saw the local player in a seat. Walk-up turrets are seats wherever
//    the sampler sees them: CE (a turret is a vehicle), Halo 3 / ODST (the seat probe), Reach's camera-info
//    sampler (type-6 mounted turrets), Halo 2's observer and Halo 4's seat stamp.
//  - OnFoot: everything else, including a title that is not the active one.
// Reach's unit_in_vehicle fallback (camera sampler not installed) reports a mounted turret on foot, so its
// OnFoot is no answer while its Vehicle is still a seat.
// Runs inside the callers' __try: reads atomics and the SEH-guarded CE player state only.
namespace
{
    enum class TitleSeatState : uint8_t { Unknown, OnFoot, Seated };

    TitleSeatState ReadTitleSeatState(GameTitle title)
    {
        if (title!=TitleAdapter_GetActiveTitle()) return TitleSeatState::OnFoot;
        const auto seatedIf=[](bool seated) { return seated?TitleSeatState::Seated:TitleSeatState::OnFoot; };
        switch(title)
        {
        case GameTitle::HaloCE:
        {
            HaloCELocalPlayerState player{};
            if (!HaloCEControls_GetLocalPlayerState(player)) return TitleSeatState::Unknown;
            return seatedIf(player.hasControlledUnit&&!player.onFoot);
        }
        case GameTitle::Halo3:
            if (g_halo3VehicleBinding.load(std::memory_order_acquire)!=
                static_cast<uint8_t>(Halo3VehicleBindingState::Installed)) return TitleSeatState::Unknown;
            return seatedIf(g_halo3VehicleFpStable.load(std::memory_order_relaxed)==
                static_cast<uint32_t>(Halo3VehicleState::Vehicle));
        case GameTitle::Halo3ODST:
            if (g_odstVehicleBinding.load(std::memory_order_acquire)!=
                static_cast<uint8_t>(OdstVehicleBindingState::Installed)) return TitleSeatState::Unknown;
            return seatedIf(g_odstSeatedLastKnown.load(std::memory_order_relaxed));
        case GameTitle::HaloReach:
            if (g_reachVehicleInputSnapshot.load(std::memory_order_acquire)==ReachVehicleInputSnapshot(
                    TitleAdapter_GetGeneration(title),ReachVehicleInputState::Vehicle))
                return TitleSeatState::Seated;
            return g_reachCamera.vehicleCameraBindingState.load(std::memory_order_acquire)==
                    static_cast<uint8_t>(ReachVehicleCameraBindingState::Installed)
                ? TitleSeatState::OnFoot : TitleSeatState::Unknown;
#if HALOMCCVR_HALO2_STEREO6DOF
        case GameTitle::Halo2:
            if (!Halo2Observer6Dof_LastKnownSeatValid()) return TitleSeatState::Unknown;
            return seatedIf(Halo2Observer6Dof_LastKnownSeated());
#endif
#if HALOMCCVR_EXPERIMENTAL_HALO4_CAMERA
        case GameTitle::Halo4:
            if (!g_halo4SeatStamp.lastKnownValid.load(std::memory_order_relaxed)) return TitleSeatState::Unknown;
            return seatedIf(g_halo4SeatStamp.lastKnownSeated.load(std::memory_order_relaxed));
#endif
        default: return TitleSeatState::OnFoot;
        }
    }
}

// Whether the local player is in a vehicle seat, failing CLOSED: no answer reads "seated", so no lift.
// (A runtime sampler fault therefore costs the lift on foot until the title reloads: degraded, never wrong.)
// For the recenter's standing lift (VR_RecenterStandingLiftM): a seat
// composes its own view, the player may well be sitting in it, and nothing there pairs with the lift.
bool Game_TitleSeated(GameTitle title)
{
    __try { return ReadTitleSeatState(title)!=TitleSeatState::OnFoot; }
    __except(EXCEPTION_EXECUTE_HANDLER) { return false; }
}

// TWO-HANDED AIM'S EXIT CONDITION (first_person_view_logic.h): is the game showing the player's own first-person
// view? Each title's evidence, strongest rung first, read on VR's frame thread from atomics and the camera
// threads' publications only (CE's player state is the SEH-guarded global read Game_TitleSeated already makes here).
//
//   title   camera rung (game's own)          seat rung (parent link)             view-model rung (mod's witness)
//   CE      native user perspective == 0      unit +0xD8 parent                   -
//   Halo 2  director's first-person update    unit seat word (observer sample)    on-foot unit sample, 100 ms
//   Halo 3  director mode 3 / perspective 0   unit seat word (+ sampler's seat)   FP view model, 100 ms
//   ODST    director mode 3 / perspective 0   unit seat word (sampler)            FP view model, 100 ms
//   Reach   director mode 3 / perspective 0   unit_get_camera_info seat           FP view model, two hits, 150 ms
//   Halo 4  director mode 3 / perspective 0   the camera hook's seat stamp        FP view-model skinning, 100 ms
//
// plus the vetoes: a cinematic (the title's cinematic publication, CE's native flag, the cutscene theater), no
// controlled unit (CE, Halo 3, ODST) and Forge's Monitor (Halo 3, Reach, Halo 4: the game's own sandbox-editor
// answer, because an idle Monitor has the first-person camera; where that answer is unknown a first-person camera
// needs the view model to vouch). `hold` is the title's own pause flag (CE); VR's pause/menu gates are added by the
// caller.
namespace
{
    fp_view::Signal SignalIf(bool yes) { return yes ? fp_view::Signal::Yes : fp_view::Signal::No; }

    // A cinematic only ever vetoes: anything but a fresh "authored camera" says nothing.
    fp_view::Signal CinematicVeto(GameTitle title, uint64_t now)
    {
        if (VR_IsCutsceneTheaterActive())
            return fp_view::Signal::Yes;
        const auto cine = TitleAdapter_GetCinematicControlPublication(title);
        return cine.state == CinematicControlState::AuthoredLocked && cine.heartbeatMs && now >= cine.heartbeatMs &&
                       now - cine.heartbeatMs <= kTwoHandViewFreshMs
                   ? fp_view::Signal::Yes
                   : fp_view::Signal::Unavailable;
    }

    // Halo 3 / ODST: the camera thread's sample. Stale = the director (when bound) and the seat are Unread.
    struct TwoHandViewSample
    {
        bool fresh = false;
        uint32_t bits = 0;
        int32_t mode = -1, perspective = -1;
    };
    TwoHandViewSample ReadTwoHandView(const TwoHandViewPublication& p, uint32_t generation, uint64_t now)
    {
        TwoHandViewSample s{};
        const uint64_t at = p.stampMs.load(std::memory_order_acquire);
        s.fresh = generation && at && now >= at && now - at <= kTwoHandViewFreshMs &&
            p.generation.load(std::memory_order_relaxed) == generation;
        if (!s.fresh)
            return s;
        s.bits = p.bits.load(std::memory_order_relaxed);
        s.mode = p.mode.load(std::memory_order_relaxed);
        s.perspective = p.perspective.load(std::memory_order_relaxed);
        return s;
    }
    fp_view::Signal DirectorSignal(const TwoHandViewSample& s, const Halo3DirectorCameraBinding& binding,
                                   uint32_t generation)
    {
        if (!s.fresh)
            return binding.bound.load(std::memory_order_acquire) &&
                    binding.generation.load(std::memory_order_acquire) == generation
                ? fp_view::Signal::Unread : fp_view::Signal::Unavailable;
        return fp_view::DirectorCameraSignal((s.bits & kTwoHandViewDirectorBound) != 0,
            (s.bits & kTwoHandViewDirectorRead) != 0, s.mode, s.perspective);
    }
    fp_view::Signal UnitSignal(const TwoHandViewSample& s)
    {
        return s.fresh && (s.bits & kTwoHandViewUnitRead)
            ? SignalIf((s.bits & kTwoHandViewUnitPresent) != 0) : fp_view::Signal::Unavailable;
    }
    // The game's own "this player is Forge's Monitor" answer as the camera thread published it (Halo 3, Reach,
    // Halo 4). Unavailable: not bound for this generation, or faulted (`faulted` says which). Unread: stale.
    fp_view::Signal EditorSignal(const TwoHandViewSample& s, const Halo3SandboxEditorBinding& editor,
                                 uint32_t generation, bool& faulted)
    {
        const bool bound = generation && editor.bound.load(std::memory_order_acquire) &&
            editor.generation.load(std::memory_order_acquire) == generation;
        faulted = bound && editor.faulted.load(std::memory_order_relaxed);
        return !bound || faulted ? fp_view::Signal::Unavailable
            : !s.fresh || !(s.bits & kTwoHandViewEditorRead) ? fp_view::Signal::Unread
            : SignalIf((s.bits & kTwoHandViewEditor) != 0);
    }

    // DEV FAULT INJECTION (first_person_rung_fault, config.h; nothing in a player build): each rung of the
    // first-person ladder forced to fail through the real path, so the next one is seen to take over. Bit 3 is
    // applied before the value agreement observes the camera (which must then withdraw it); bits 0-2 after it.
    void DevFaultFirstPersonCamera(fp_view::Signal& camera) noexcept
    {
#if HALOMCCVR_DEV_DIAGNOSTICS
        if ((g_config.first_person_rung_fault & 8) && camera == fp_view::Signal::Yes)
            camera = fp_view::Signal::No;
#else
        (void)camera;
#endif
    }
    void DevFaultFirstPersonRungs(fp_view::Signal& camera, fp_view::Signal& monitor,
                                  fp_view::Signal& viewModel) noexcept
    {
#if HALOMCCVR_DEV_DIAGNOSTICS
        const int fault = g_config.first_person_rung_fault;
        if ((fault & 1) && viewModel == fp_view::Signal::Yes)
            viewModel = fp_view::Signal::No;           // an unarmed player: no view model drawn
        if (fault & 2)
            camera = monitor = fp_view::Signal::Unavailable;   // no camera rung: the behaviour before it
        if ((fault & 4) && monitor != fp_view::Signal::Yes)
            monitor = fp_view::Signal::Unavailable;    // the Monitor check unbound
#else
        (void)camera; (void)monitor; (void)viewModel;
#endif
    }

    // THE CAMERA RUNG'S VALUE AGREEMENT (director_camera::RungTrust), Reach / Halo 4 / Halo 2: the new rung against
    // the view-model witness it outranks. Observed on the title's camera thread, on frames the presentation admits
    // and only while the rest of the evidence says "on foot, in control"; the verdict for the generation is
    // published for the VR frame thread (two-handed aim) and for roomscale's report, which says each once.
    struct CameraRungTrustState
    {
        director_camera::RungTrust trust;     // camera thread only
        uint32_t generation = 0;              // camera thread only
        std::atomic<uint32_t> provenGeneration{0}, condemnedGeneration{0};
    };
    CameraRungTrustState g_cameraRungTrust[3];
    CameraRungTrustState* CameraRungTrustFor(GameTitle title)
    {
        switch (title)
        {
        case GameTitle::HaloReach: return &g_cameraRungTrust[0];
        case GameTitle::Halo4: return &g_cameraRungTrust[1];
        case GameTitle::Halo2: return &g_cameraRungTrust[2];
        default: return nullptr;
        }
    }
    // Any thread: the rung was condemned for this title generation, so the view model decides, as before.
    bool CameraRungCondemned(GameTitle title, uint32_t generation)
    {
        const CameraRungTrustState* state = CameraRungTrustFor(title);
        return state && generation && state->condemnedGeneration.load(std::memory_order_acquire) == generation;
    }
    void ObserveCameraRung(GameTitle title, uint32_t generation, roomscale_admission::TitleEvidence& e,
                           roomscale_admission::Verdict& verdict)
    {
        using fp_view::Signal;
        CameraRungTrustState* state = CameraRungTrustFor(title);
        if (!state || !generation)
            return;
        if (state->generation != generation)
        {
            state->trust.Reset();
            state->generation = generation;
        }
        const bool onFootInControl = e.cinematic != Signal::Yes && e.cinematic != Signal::Unread &&
            e.controlBlocked != Signal::Yes && e.unit != Signal::No && e.unit != Signal::Unread &&
            e.seated == Signal::No;
        if (onFootInControl)
        {
            switch (state->trust.Observe(e.camera, e.viewModel))
            {
            case director_camera::RungTrust::Step::Proven:
                state->provenGeneration.store(generation, std::memory_order_release);
                break;
            case director_camera::RungTrust::Step::Condemned:
                state->condemnedGeneration.store(generation, std::memory_order_release);
                break;
            default: break;
            }
        }
        verdict.cameraRungProven = state->trust.Proven();
        verdict.cameraRungCondemned = state->trust.condemned;
        if (state->trust.condemned)
        {
            e.camera = Signal::Unavailable;    // the view-model rung decides, as before
            e.monitor = Signal::Unavailable;
        }
    }

    TitleFirstPersonView ReadTitleFirstPersonView(GameTitle title, uint64_t now)
    {
        TitleFirstPersonView view{};
        // The published runtime mode: the shell, a load or a pause hold; a mode the title has already classified
        // as a seat, a cutscene or death is one more veto (CE, Halo 3 and ODST publish Vehicle / Turret; CE
        // Cutscene and Dead).
        const RuntimeMode mode = TitleAdapter_GetRuntimeMode();
        if (title == GameTitle::None || title != TitleAdapter_GetActiveTitle() || mode == RuntimeMode::Shell ||
            mode == RuntimeMode::Loading || mode == RuntimeMode::Paused)
        {
            view.hold = true;
            return view;
        }
        fp_view::Evidence e{};
        e.cinematic = CinematicVeto(title, now);
        const auto modeVetoes = [mode](fp_view::Evidence& evidence) {
            if (mode == RuntimeMode::Cutscene)
                evidence.cinematic = fp_view::Signal::Yes;
            else if (mode == RuntimeMode::Vehicle || mode == RuntimeMode::Turret)
                evidence.seated = fp_view::Signal::Yes;
            else if (mode == RuntimeMode::Dead)
                evidence.unit = fp_view::Signal::No;
        };
        switch (title)
        {
        case GameTitle::HaloCE:
        {
            HaloCELocalPlayerState player{};
            if (!HaloCEControls_GetLocalPlayerState(player))
                return view;   // Unread
            view.hold = player.nativePaused;
            if (player.nativeCinematicFlag)
                e.cinematic = fp_view::Signal::Yes;
            e.unit = SignalIf(player.hasControlledUnit);
            e.seated = player.hasControlledUnit ? SignalIf(!player.onFoot) : fp_view::Signal::Unavailable;
            e.camera = SignalIf(player.nativePreparesFirstPerson);
            e.monitor = fp_view::Signal::No;   // CE has no Forge
            break;
        }
        case GameTitle::Halo3:
        {
            const uint32_t generation = g_halo3RuntimeGeneration.load(std::memory_order_acquire);
            const TwoHandViewSample s = ReadTwoHandView(g_halo3TwoHandView, generation, now);
            e.unit = UnitSignal(s);
            e.camera = DirectorSignal(s, g_halo3DirectorCamera, generation);
            // An idle Forge Monitor has the first-person camera: the game's own editor answer, as roomscale
            // reads it (the same publication).
            bool editorFaulted = false;
            e.monitor = EditorSignal(s, g_halo3SandboxEditor, generation, editorFaulted);
            if (s.fresh && (s.bits & kTwoHandViewSeatRead))
                e.seated = SignalIf((s.bits & kTwoHandViewSeated) != 0);
            else if (g_halo3PlayerUnitGetter && e.unit != fp_view::Signal::No)
                e.seated = fp_view::Signal::Unread;
            // The vehicle sampler's debounced seat, as Game_TitleSeated reads it: a seat it has settled on stands.
            if (g_halo3VehicleBinding.load(std::memory_order_acquire) ==
                    static_cast<uint8_t>(Halo3VehicleBindingState::Installed) &&
                g_halo3VehicleFpStable.load(std::memory_order_relaxed) ==
                    static_cast<uint32_t>(Halo3VehicleState::Vehicle))
                e.seated = fp_view::Signal::Yes;
            e.viewModel = g_fpInterpolatorHooked.load(std::memory_order_acquire)
                ? SignalIf(WitnessFresh(g_halo3FirstPersonMs, now, kFirstPersonWitnessMs))
                : fp_view::Signal::Unavailable;
            break;
        }
        case GameTitle::Halo3ODST:
        {
            const uint32_t generation = g_odstRuntimeGeneration.load(std::memory_order_acquire);
            const TwoHandViewSample s = ReadTwoHandView(g_odstTwoHandView, generation, now);
            e.unit = UnitSignal(s);
            e.camera = DirectorSignal(s, g_odstDirectorCamera, generation);
            e.monitor = fp_view::Signal::No;   // ODST has no Forge
            if (g_odstVehicleBinding.load(std::memory_order_acquire) ==
                static_cast<uint8_t>(OdstVehicleBindingState::Installed))
                e.seated = s.fresh ? SignalIf(g_odstSeatedLastKnown.load(std::memory_order_relaxed))
                                   : fp_view::Signal::Unread;
            e.viewModel = g_odstCamera.installed.load(std::memory_order_acquire)
                ? SignalIf(WitnessFresh(g_odstFirstPersonMs, now, kFirstPersonWitnessMs))
                : fp_view::Signal::Unavailable;
            break;
        }
        case GameTitle::HaloReach:
        {
            // Only the camera-info sampler sees a mounted turret; the unit_in_vehicle fallback's "on foot" is no
            // answer there (ReadTitleSeatState), and the view-model witness then decides.
            const TitleSeatState seat = ReadTitleSeatState(title);
            e.seated = seat == TitleSeatState::Seated ? fp_view::Signal::Yes
                : seat == TitleSeatState::OnFoot      ? fp_view::Signal::No
                                                      : fp_view::Signal::Unavailable;
            e.viewModel = SignalIf(ReachFirstPersonFresh(now));
            // The game's own camera (director mode 3 / perspective 0) and Monitor answer, where bound and not
            // condemned by the view model this generation: a zoom no longer depends on the view model.
            const uint32_t cameraGeneration = g_reachDirectorCamera.generation.load(std::memory_order_acquire);
            if (!CameraRungCondemned(title, TitleAdapter_GetGeneration(title)))
            {
                const TwoHandViewSample s = ReadTwoHandView(g_reachTwoHandView, cameraGeneration, now);
                bool editorFaulted = false;
                e.camera = DirectorSignal(s, g_reachDirectorCamera, cameraGeneration);
                e.monitor = EditorSignal(s, g_reachSandboxEditor, cameraGeneration, editorFaulted);
            }
            break;
        }
#if HALOMCCVR_HALO2_STEREO6DOF
        case GameTitle::Halo2:
            if (Halo2Observer6Dof_LastKnownSeatValid())
            {
                e.seated = SignalIf(Halo2Observer6Dof_LastKnownSeated());
                // Halo 2's on-foot proof: the owned unit's own aim update ran within 100 ms with no seat. It stops
                // when the unit dies.
                e.viewModel = SignalIf(Halo2Observer6Dof_OnFootFresh());
                // The game's own perspective for user 0 (director_get_perspective's inputs), where bound and
                // not condemned: the dead, following and scripted cameras all leave. Halo 2 has no Forge.
                if (!CameraRungCondemned(title, TitleAdapter_GetGeneration(title)))
                    e.camera = static_cast<fp_view::Signal>(Halo2Observer6Dof_FirstPersonCamera());
                e.monitor = fp_view::Signal::No;
            }
            break;
#endif
#if HALOMCCVR_EXPERIMENTAL_HALO4_CAMERA
        case GameTitle::Halo4:
        {
            Halo4VehicleInputState seat{};
            if (Halo4ReadSeatStamp(seat))
                e.seated = SignalIf(seat.seated);
            else if (g_halo4SeatStamp.lastKnownValid.load(std::memory_order_relaxed))
                e.seated = SignalIf(g_halo4SeatStamp.lastKnownSeated.load(std::memory_order_relaxed));
            e.viewModel = g_halo4FirstPersonWitnessHooked.load(std::memory_order_acquire)
                ? SignalIf(WitnessFresh(g_halo4FirstPersonMs, now, kHalo4FirstPersonFreshMs))
                : fp_view::Signal::Unavailable;
            // The game's own camera and Monitor answer, as Reach's above.
            const uint32_t cameraGeneration = g_halo4DirectorCamera.generation.load(std::memory_order_acquire);
            if (!CameraRungCondemned(title, TitleAdapter_GetGeneration(title)))
            {
                const TwoHandViewSample s = ReadTwoHandView(g_halo4TwoHandView, cameraGeneration, now);
                bool editorFaulted = false;
                e.camera = DirectorSignal(s, g_halo4DirectorCamera, cameraGeneration);
                e.monitor = EditorSignal(s, g_halo4SandboxEditor, cameraGeneration, editorFaulted);
            }
            break;
        }
#endif
        default:
            return view;   // Unread: no title we know how to read
        }
        DevFaultFirstPersonCamera(e.camera);
        DevFaultFirstPersonRungs(e.camera, e.monitor, e.viewModel);
        modeVetoes(e);
        view.why = fp_view::Classify(e);
        return view;
    }
}

TitleFirstPersonView Game_TitleFirstPersonView(GameTitle title)
{
    __try { return ReadTitleFirstPersonView(title, GetTickCount64()); }
    __except(EXCEPTION_EXECUTE_HANDLER) { return TitleFirstPersonView{}; }
}

// The camera rung as last published, raw, for the dev line that says what each state's camera reads. Atomics (and
// Halo 2's SEH-guarded static read) only: any thread.
bool Game_FirstPersonCameraSample(GameTitle title, fp_view::Signal& camera, int32_t& mode, int32_t& perspective,
                                  fp_view::Signal& monitor)
{
    camera = monitor = fp_view::Signal::Unavailable;
    mode = perspective = -1;
    if (title == GameTitle::None || title != TitleAdapter_GetActiveTitle())
        return false;
    const uint64_t now = GetTickCount64();
    const auto director = [&](const TwoHandViewPublication& publication, const Halo3DirectorCameraBinding& binding,
                              const Halo3SandboxEditorBinding* editor, uint32_t generation) {
        const TwoHandViewSample s = ReadTwoHandView(publication, generation, now);
        camera = DirectorSignal(s, binding, generation);
        if (!s.fresh || !(s.bits & kTwoHandViewDirectorRead))
            return camera != fp_view::Signal::Unavailable;
        mode = s.mode;
        perspective = s.perspective;
        bool faulted = false;
        monitor = editor ? EditorSignal(s, *editor, generation, faulted) : fp_view::Signal::No;
        return true;
    };
    switch (title)
    {
    case GameTitle::Halo3:
        return director(g_halo3TwoHandView, g_halo3DirectorCamera, &g_halo3SandboxEditor,
            g_halo3RuntimeGeneration.load(std::memory_order_acquire));
    case GameTitle::Halo3ODST:
        return director(g_odstTwoHandView, g_odstDirectorCamera, nullptr,
            g_odstRuntimeGeneration.load(std::memory_order_acquire));
    case GameTitle::HaloReach:
        return director(g_reachTwoHandView, g_reachDirectorCamera, &g_reachSandboxEditor,
            g_reachDirectorCamera.generation.load(std::memory_order_acquire));
    case GameTitle::Halo4:
        return director(g_halo4TwoHandView, g_halo4DirectorCamera, &g_halo4SandboxEditor,
            g_halo4DirectorCamera.generation.load(std::memory_order_acquire));
#if HALOMCCVR_HALO2_STEREO6DOF
    case GameTitle::Halo2:
        camera = static_cast<fp_view::Signal>(Halo2Observer6Dof_FirstPersonCamera());
        monitor = fp_view::Signal::No;
        return camera != fp_view::Signal::Unavailable;
#endif
    default:
        return false;
    }
}

// ROOMSCALE'S ADMISSION (roomscale_admission_logic.h): each title's proof that the local player is on foot,
// player-controlled and looking through his own eyes -- no seat, no cinematic, no third-person camera, not Forge's
// Monitor. Roomscale adds its setting and presentation gates on top; the head leash uses it as it is.
//
//   title   on foot (unit / seat)                    first person: camera rung            Monitor            view model
//   CE      controlled unit, no parent               native user perspective == 0         no Forge           -
//   Halo 2  observer's on-foot unit sample, 100 ms   director's first-person camera       no Forge           FP palette packet, 250 ms
//                                                    update, no transition
//   Halo 3  unit seat word + the vehicle sampler     director mode 3 / perspective 0      the game's own     FP interpolation, 100 ms
//                                                                                         editor predicate
//   ODST    seat sampler, 100 ms                     director mode 3 / perspective 0      no Forge           FP interpolation, 100 ms
//   Reach   camera-info seat sampler, 100 ms         director mode 3 / perspective 0      the game's own     FP interpolation x2, 150 ms
//                                                                                         editor predicate
//   Halo 4  FP record's unit, no parent              director mode 3 / perspective 0      the game's own     FP skinning, 100 ms
//                                                                                         editor predicate
//
// The camera rung admits a first-person player with no weapon in his hands (the view model is not asked). Where a
// title's rung did not bind on this build, or the view model condemned it this generation (director_camera::
// RungTrust), the view model decides as before and an unarmed player stands down (the reason is named: "no
// first-person view model"). Runs on the title's camera thread, under the callers' SEH.
namespace
{
    fp_view::Signal CinematicSignal(CinematicControlState state)
    {
        return state == CinematicControlState::PlayerControlled ? fp_view::Signal::No
            : state == CinematicControlState::AuthoredLocked    ? fp_view::Signal::Yes
                                                                : fp_view::Signal::Unread;
    }
    // The title's unit sampler said "no unit" within its window (the death / spectator camera).
    bool AimUnitFreshlyAbsent(GameTitle title, uint64_t now)
    {
        const size_t slot = TitleRuntimeSlotIndex(title);
        if (slot >= kTitleRuntimeSlotCount)
            return false;
        const uint64_t word = g_aimUnitPresence[slot].load(std::memory_order_relaxed);
        const uint64_t at = aim_no_unit::UnpackMs(word);
        return aim_no_unit::UnpackPresence(word) == aim_no_unit::Presence::Absent && at && now >= at &&
            now - at <= aim_no_unit::kStaleMs;
    }

    // `hold`: the title's own pause flag (CE). `monitorFaulted`: the Monitor predicate faulted this generation.
    roomscale_admission::TitleEvidence ReadRoomscaleTitleEvidence(GameTitle title, uint64_t now, bool& hold,
                                                                  bool& monitorFaulted)
    {
        using fp_view::Signal;
        roomscale_admission::TitleEvidence e{};
        switch (title)
        {
        case GameTitle::HaloCE:
        {
            HaloCELocalPlayerState player{};
            if (!HaloCEControls_GetLocalPlayerState(player))
            {
                e.unit = Signal::Unread;
                break;
            }
            hold = player.nativePaused;
            e.cinematic = SignalIf(player.nativeCinematicFlag);
            e.controlBlocked = SignalIf(player.nativeInputBlocked || player.nativeLookBlocked);
            e.unit = SignalIf(player.hasControlledUnit);
            e.seated = player.hasControlledUnit ? SignalIf(!player.onFoot) : Signal::Unavailable;
            e.camera = SignalIf(player.nativePreparesFirstPerson);
            e.monitor = Signal::No;   // CE has no Forge
            break;
        }
        case GameTitle::Halo3:
        {
            int32_t scene = -1, shot = -1;
            e.cinematic = CinematicSignal(ReadCinematicControl(scene, shot));
            switch (Game_Halo3VehicleState().state)
            {
            case Halo3VehicleState::OnFoot: e.seated = Signal::No; break;
            case Halo3VehicleState::Vehicle: e.seated = Signal::Yes; break;
            default: e.seated = Signal::Unread; break;
            }
            if (!g_halo3PlayerUnitGetter)
                e.unit = Signal::Unread;
            else
            {
                // The unit's own seat word: a stationary turret is a seat unit_in_vehicle does not report.
                const auto* unit = Halo3MeleeSelectionObject(static_cast<uint32_t>(g_halo3PlayerUnitGetter(0)), 0);
                e.unit = SignalIf(unit != nullptr);
                if (unit && *reinterpret_cast<const int16_t*>(unit + kHalo3UnitSeatWordOffset) != -1)
                    e.seated = Signal::Yes;
            }
            const uint32_t generation = g_halo3RuntimeGeneration.load(std::memory_order_acquire);
            const TwoHandViewSample s = ReadTwoHandView(g_halo3TwoHandView, generation, now);
            e.camera = DirectorSignal(s, g_halo3DirectorCamera, generation);
            e.monitor = EditorSignal(s, g_halo3SandboxEditor, generation, monitorFaulted);
            // The witness hook installs apart from the camera (M3); without it there is none.
            e.viewModel = g_fpInterpolatorHooked.load(std::memory_order_acquire)
                ? SignalIf(WitnessFresh(g_halo3FirstPersonMs, now, kFirstPersonWitnessMs))
                : Signal::Unavailable;
            break;
        }
        case GameTitle::Halo3ODST:
        {
            int32_t scene = -1, shot = -1;
            e.cinematic = CinematicSignal(ReadOdstCinematicControl(scene, shot));
            const uint32_t generation = g_odstRuntimeGeneration.load(std::memory_order_acquire);
            const TwoHandViewSample s = ReadTwoHandView(g_odstTwoHandView, generation, now);
            const uint64_t at = g_odstRoomscaleOnFootMs.load();
            const bool onFootFresh = at && now >= at && now - at <= 100;
            const uint32_t stable = g_odstVehicleFpStable.load();
            if (g_odstVehicleBinding.load() != static_cast<uint8_t>(OdstVehicleBindingState::Installed))
                e.seated = Signal::Unread;
            else if (onFootFresh && stable == static_cast<uint32_t>(Halo3VehicleState::OnFoot))
            {
                e.unit = Signal::Yes;
                e.seated = Signal::No;
            }
            else
            {
                // Not freshly on foot: name why where the samplers say (no unit, a seat), else it is stale.
                e.unit = UnitSignal(s);
                e.seated = g_odstSeatedLastKnown.load(std::memory_order_relaxed) ||
                        stable == static_cast<uint32_t>(Halo3VehicleState::Vehicle)
                    ? Signal::Yes : Signal::Unread;
            }
            e.camera = DirectorSignal(s, g_odstDirectorCamera, generation);
            e.monitor = Signal::No;   // ODST has no Forge
            e.viewModel = g_odstCamera.installed.load(std::memory_order_acquire)
                ? SignalIf(WitnessFresh(g_odstFirstPersonMs, now, kFirstPersonWitnessMs))
                : Signal::Unavailable;
            break;
        }
        case GameTitle::HaloReach:
        {
            const uint32_t generation = TitleAdapter_GetGeneration(title);
            const auto cine = TitleAdapter_GetCinematicControlPublication(title);
            e.cinematic = cine.generation == generation && cine.heartbeatMs && now >= cine.heartbeatMs &&
                    now - cine.heartbeatMs <= 100
                ? CinematicSignal(cine.state) : Signal::Unread;
            const uint64_t at = g_reachVehicleSampleMs.load();
            const auto snapshot = g_reachVehicleInputSnapshot.load();
            if (AimUnitFreshlyAbsent(title, now))
                e.unit = Signal::No;
            if (!(at && now >= at && now - at <= 100))
                e.seated = Signal::Unread;
            else if (snapshot == ReachVehicleInputSnapshot(generation, ReachVehicleInputState::OnFoot))
                e.seated = Signal::No;
            else if (snapshot == ReachVehicleInputSnapshot(generation, ReachVehicleInputState::Vehicle))
                e.seated = Signal::Yes;
            else
                e.seated = Signal::Unread;
            // The view model (it also stops in Armor Lock and for the death camera), and above it the game's own
            // camera -- the director's record for output user 0: mode 3, perspective 0 -- with the game's own
            // Monitor answer (director_camera_logic.h). Unbound, the view model alone decides, as before.
            e.viewModel = SignalIf(ReachFirstPersonFresh(now));
            const uint32_t cameraGeneration = g_reachDirectorCamera.generation.load(std::memory_order_acquire);
            const TwoHandViewSample s = ReadTwoHandView(g_reachTwoHandView, cameraGeneration, now);
            e.camera = DirectorSignal(s, g_reachDirectorCamera, cameraGeneration);
            e.monitor = EditorSignal(s, g_reachSandboxEditor, cameraGeneration, monitorFaulted);
            break;
        }
#if HALOMCCVR_HALO2_STEREO6DOF
        case GameTitle::Halo2:
            if (Halo2Observer6Dof_OnFootFresh())
            {
                e.unit = Signal::Yes;
                e.seated = Signal::No;
            }
            else
                e.seated = Halo2Observer6Dof_LastKnownSeatValid() && Halo2Observer6Dof_LastKnownSeated()
                    ? Signal::Yes : Signal::Unread;
            // Halo 2's first-person palette packet, and above it the game's own perspective for user 0
            // (director_get_perspective's inputs; director_camera_logic.h). Halo 2 has no Forge.
            e.viewModel = SignalIf(Halo2Observer6Dof_FinalPaletteArmed());
            e.camera = static_cast<Signal>(Halo2Observer6Dof_FirstPersonCamera());
            e.monitor = Signal::No;
            break;
#endif
#if HALOMCCVR_EXPERIMENTAL_HALO4_CAMERA
        case GameTitle::Halo4:
        {
            if (!Halo4ContactMeleeReady() || g_halo4Contact.generation != g_halo4Camera.generation.load())
            {
                e.seated = Signal::Unread;
                break;
            }
            e.cinematic = CinematicSignal(ReadHalo4CinematicControl());
            if (AimUnitFreshlyAbsent(title, now))
                e.unit = Signal::No;
            Halo4FirstPersonAccess fp{};
            // record is validated even for an unarmed player with zero weapon nodes.
            (void)Halo4ResolveFirstPerson(0, fp);
            if (!fp.record)
            {
                if (e.unit != Signal::No)
                    e.unit = Signal::Unread;
                break;
            }
            const auto unit = *reinterpret_cast<const uint32_t*>(fp.record + kHalo4FirstPersonRecordUnitOffset);
            const auto* biped = Halo4ContactBiped(unit);
            // Existing H4EK-proven contact admission: unparented local biped.
            e.unit = SignalIf(biped != nullptr);
            if (biped)
                e.seated = SignalIf(*reinterpret_cast<const int32_t*>(biped + 0x24) != -1);
            // The camera at his eye (the first-person witness): third person is on foot and player-controlled
            // too. The skinning hook belongs to the optional floating hands; without it there is no witness.
            e.viewModel = g_halo4FirstPersonWitnessHooked.load(std::memory_order_acquire)
                ? SignalIf(WitnessFresh(g_halo4FirstPersonMs, now, kHalo4FirstPersonFreshMs))
                : Signal::Unavailable;
            // Above it the game's own camera (the director's record: mode 3, perspective 0) and Monitor answer
            // (director_camera_logic.h). Unbound, the view model alone decides, as before.
            const uint32_t cameraGeneration = g_halo4DirectorCamera.generation.load(std::memory_order_acquire);
            const TwoHandViewSample s = ReadTwoHandView(g_halo4TwoHandView, cameraGeneration, now);
            e.camera = DirectorSignal(s, g_halo4DirectorCamera, cameraGeneration);
            e.monitor = EditorSignal(s, g_halo4SandboxEditor, cameraGeneration, monitorFaulted);
            break;
        }
#endif
        default:
            e.seated = Signal::Unread;   // no title we know how to read
            break;
        }
        return e;
    }
}

roomscale_admission::Verdict Game_TitleOnFootVerdict(GameTitle title)
{
    roomscale_admission::Verdict verdict{};
    verdict.refusal = roomscale_admission::Refusal::WrongTitle;
    if (title != TitleAdapter_GetActiveTitle())
        return verdict;
    __try
    {
        bool hold = false, monitorFaulted = false;
        roomscale_admission::TitleEvidence e =
            ReadRoomscaleTitleEvidence(title, GetTickCount64(), hold, monitorFaulted);
        // Reach / Halo 4 / Halo 2: the camera rung against the view model (a condemned rung is withdrawn here).
        DevFaultFirstPersonCamera(e.camera);
        if (!hold)
            ObserveCameraRung(title, TitleAdapter_GetGeneration(title), e, verdict);
        DevFaultFirstPersonRungs(e.camera, e.monitor, e.viewModel);
        verdict.rungs = roomscale_admission::PackRungs(e.camera, e.monitor, e.viewModel);
        verdict.monitorCheckFaulted = monitorFaulted;
        verdict.refusal = hold ? roomscale_admission::Refusal::Menu : roomscale_admission::ClassifyTitle(e);
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        verdict.refusal = roomscale_admission::Refusal::StaleSample;
    }
    return verdict;
}

bool Game_TitleOnFootPlayerControlled(GameTitle title)
{
    return Game_TitleOnFootVerdict(title).Admitted();
}

roomscale_admission::Verdict Game_RoomscaleCameraVerdict(GameTitle title)
{
    roomscale_admission::Presentation p{};
    p.titleActive = title == TitleAdapter_GetActiveTitle();
    p.enabled = (g_config.roomscale_movement || g_config.physical_running) && g_enabled.load() &&
        g_positional.load() && g_vrAim.load() && VR_IsStereoEnabled();
    p.menu = Menu_IsOpen() || VR_IsPausePresentation() || VR_IsPausePresentationTarget();
    p.theatre = VR_IsCutsceneTheaterActive();
    p.mode = TitleAdapter_GetRuntimeMode();
    roomscale_admission::Verdict verdict{};
    verdict.refusal = roomscale_admission::ClassifyPresentation(p);
    if (verdict.refusal == roomscale_admission::Refusal::None)
        verdict = Game_TitleOnFootVerdict(title);
    return verdict;
}

bool Game_RoomscaleCameraAllowed(GameTitle title)
{
    return Game_RoomscaleCameraVerdict(title).Admitted();
}

// ---- the vehicle cameras in Halo 2's seats (halo2_vehicle_cameras.h; halo2_vehicle_cameras.inl has the work) ----

bool Game_Halo2VehicleCamerasBegin(const Halo2VehicleCameraSeatSample& seat, bool& followHull) noexcept
{
    return Halo2VehicleCamerasBegin(seat, followHull);
}

bool Game_Halo2VehicleCamerasPlace(const Halo2VehicleCameraSeatSample& seat, float viewYaw, float eye[3]) noexcept
{
    return Halo2VehicleCamerasPlace(seat, viewYaw, eye);
}

bool Game_Halo2VehicleCameraLeash(float head[3]) noexcept
{
    const Halo2VehicleCameraPassRecord& pass = g_halo2VehicleCameraPass;
    return head && pass.placed && vehicle_camera_place::LeashHead(pass.camera, pass.where, pass.reach, head);
}

bool Game_Halo2VehicleCameraPlacedSeat(uint32_t parent, int16_t seat) noexcept
{
    const uint64_t at = g_halo2VehicleCameraPlacedMs.load(std::memory_order_acquire);
    const uint64_t now = GetTickCount64();
    return at && now >= at && now - at <= 100 && parent != UINT32_MAX && seat >= 0 &&
           g_halo2VehicleCameraPlacedParent.load(std::memory_order_relaxed) == parent &&
           g_halo2VehicleCameraPlacedSeat.load(std::memory_order_relaxed) == seat;
}

void Game_Halo2VehicleAimMarkerStep(const float eye[3], const float forward[3], const float up[3],
                                    const float headQuat[4]) noexcept
{
    Halo2VehicleAimMarkerStep(eye, forward, up, headQuat);
}

void Game_Halo2VehicleCamerasOnFoot(uint32_t generation) noexcept
{
    g_halo2VehicleCameraPass.placed = false;
    Halo2VehicleCameraPublishSeat(nullptr, generation);
}

bool Game_Halo2VehicleCameraChase(const NativeVehicleCameraOwner& owner) noexcept
{
    if (owner.parent == UINT32_MAX || owner.seat < 0)
        return false;
    // The seat by its object and index (the salted handle names the object for the generation): the owner's model
    // identity is a fresh read each call, and a read that fails once must not flash the seat's view to first person.
    vehicle_camera_select::ActiveCamera camera;
    VehicleCameraSeatKey chosenFor;
    return VehicleCameraRead(camera, chosenFor) && chosenFor.generation == owner.generation &&
           chosenFor.vehicle == static_cast<int32_t>(owner.parent) && chosenFor.seatIndex == owner.seat &&
           chosenFor.mounted == (owner.root != UINT32_MAX && owner.root != owner.parent);
}

bool Game_ReclaimerOdstLevel() noexcept
{
    return g_hostIsProjectReclaimer && g_reclaimerOdstLevel.load(std::memory_order_relaxed);
}
